
:root{
  box-sizing:border-box;
  padding-top:env(safe-area-inset-top,0px);
  padding-bottom:env(safe-area-inset-bottom,0px);
  --bg:#E9ECF1; --surface:#F4F6FA; --ink:#1C2433; --muted:#636E83; --line:#DFE3EA;
  --accent:#2C55D6; --accent-ink:#FFFFFF; --mark:#FFE14D; --late:#C8352E; --soft:#EEF1F6;
  --display:"Bricolage Grotesque", "Avenir Next", "Segoe UI", system-ui, sans-serif;
  --body:"Figtree", "Segoe UI", system-ui, -apple-system, sans-serif;
  color-scheme:light;
}
@media (prefers-color-scheme:dark){
  :root:not([data-theme="light"]){
    --bg:#11141A; --surface:#1A1F28; --ink:#E9ECF2; --muted:#9AA3B4; --line:#2B3240;
    --accent:#7F9CFF; --accent-ink:#0F1320; --mark:#8A7414; --late:#FF7A70; --soft:#222834;
    color-scheme:dark;
  }
}
:root[data-theme="dark"]{
  --bg:#11141A; --surface:#1A1F28; --ink:#E9ECF2; --muted:#9AA3B4; --line:#2B3240;
  --accent:#7F9CFF; --accent-ink:#0F1320; --mark:#8A7414; --late:#FF7A70; --soft:#222834;
  color-scheme:dark;
}
*,*::before,*::after{box-sizing:inherit}
html{height:100%;scroll-padding-top:env(safe-area-inset-top,0px);scrollbar-gutter:stable;overscroll-behavior-y:none}
/* no bounce past the top or bottom (Chrome on Windows and Mac touchpads): it slid the page down and showed a strip of the light background above the sidebar */
body{overscroll-behavior-y:none}
body{margin:0;min-height:100%;background:var(--bg);color:var(--ink);font:1rem/1.5 var(--body);-webkit-font-smoothing:antialiased}
button,input,select,textarea{font:inherit;color:inherit}
button{cursor:pointer}
:focus-visible{outline:2px solid var(--accent);outline-offset:2px;border-radius:6px}
a{color:var(--accent)}
.wrap{max-width:760px;margin:0 auto;padding:0 18px 120px}

/* Header */
header.top{position:sticky;top:env(safe-area-inset-top,0px);z-index:5;background:var(--bg);padding:14px 0 10px}
.top-row{display:flex;align-items:center;gap:12px}
.brand{font:700 1.5rem/1.1 var(--display);letter-spacing:-.02em;margin:0;flex:1}
.today{color:var(--muted);font-size:.9rem;margin-top:2px}
.sync{font-size:.8rem;color:var(--muted)}
.sync-guest{flex:none;font:600 .72rem/1 var(--font,inherit);padding:6px 10px;border-radius:999px;border:1px solid color-mix(in srgb,var(--accent) 45%,var(--line));background:color-mix(in srgb,var(--accent) 12%,var(--surface));color:var(--ink);cursor:pointer;white-space:nowrap}
.sync-guest:hover,.sync-guest:focus-visible{border-color:var(--accent)}
.sync-guest .sg-s{display:none}
nav.tabs .sync-guest.sync-guest-side{display:block;margin:2px 6px 6px;white-space:normal;line-height:1.2;font:700 .68rem/1.2 var(--display);padding:6px 6px;text-align:center;color:#fff;background:var(--accent);border:1px solid rgba(255,255,255,.35);border-radius:10px}
nav.tabs .sync-guest.sync-guest-side[hidden]{display:none}
nav.tabs .sync-guest.sync-guest-side:hover,nav.tabs .sync-guest.sync-guest-side:focus-visible{filter:brightness(1.1)}
@media (max-width:600px){.sync-guest .sg-l{display:none}.sync-guest .sg-s{display:inline}}
.icon-btn{width:40px;height:40px;border-radius:12px;border:1px solid var(--line);background:var(--surface);display:grid;place-items:center}
.icon-btn svg{width:20px;height:20px}

/* Tabs */
nav.tabs{position:fixed;left:0;right:0;bottom:0;z-index:6;background:var(--surface);border-top:1px solid var(--line);padding-bottom:env(safe-area-inset-bottom,0px)}
nav.tabs .in{max-width:760px;margin:0 auto;display:grid;grid-template-columns:repeat(6,1fr)}
nav.tabs button{border:0;background:none;padding:9px 2px 10px;display:flex;flex-direction:column;align-items:center;gap:2px;font-size:.7rem;color:var(--muted)}
nav.tabs button svg{width:22px;height:22px}
nav.tabs button[aria-current="page"]{color:var(--ink);font-weight:600}
nav.tabs button[aria-current="page"] svg{color:var(--accent)}

.fab{position:fixed;right:max(18px,calc(50% - 362px));bottom:calc(76px + env(safe-area-inset-bottom,0px));z-index:6;border:0;border-radius:18px;background:var(--accent);color:var(--accent-ink);padding:14px 18px;font-weight:600;display:flex;align-items:center;gap:8px;box-shadow:0 6px 18px rgba(20,40,120,.25)}
.fab svg{width:20px;height:20px}
.fab span{position:relative;top:-1.5px}

/* Sections */
h2.sec{font:700 1.05rem/1.2 var(--display);margin:26px 0 10px;display:flex;align-items:baseline;gap:8px}
h2.sec .n{font:500 .85rem var(--body);color:var(--muted)}
h2.sec.hl span.t{background:linear-gradient(transparent 45%, var(--mark) 45%, var(--mark) 88%, transparent 88%);padding:0 3px;margin:0 -3px}
h2.sec.late span.t{color:var(--late)}
.summary{font:500 1.9rem/1.15 var(--display);letter-spacing:-.02em;margin:14px 0 4px;max-width:18ch}
.summary-sub{color:var(--muted);margin:0 0 6px}

.chips{display:flex;gap:8px;overflow-x:auto;padding:4px 0 6px;scrollbar-width:none}
.chips::-webkit-scrollbar{display:none}
.chip{flex:none;border:1px solid var(--line);background:var(--surface);border-radius:999px;padding:6px 12px;font-size:.88rem;display:flex;align-items:center;gap:7px}
.chip .dot{width:9px;height:9px;border-radius:50%;background:var(--c)}
.chip[aria-pressed="true"]{background:var(--ink);color:var(--bg);border-color:var(--ink)}

/* Tasks */
ul.tasks{list-style:none;margin:0;padding:0;background:var(--surface);border:1px solid var(--line);border-radius:14px;overflow:hidden}
li.task{display:flex;align-items:flex-start;border-top:1px solid var(--line);position:relative}
li.task:first-child{border-top:0}
li.task::before{content:"";position:absolute;left:0;top:10px;bottom:10px;width:4px;border-radius:0 4px 4px 0;background:var(--c)}
.check{flex:none;margin:12px 0 0 14px;width:26px;height:26px;border-radius:50%;border:2px solid var(--c);background:transparent;display:grid;place-items:center;padding:0}
.check svg{width:14px;height:14px;opacity:0;color:#fff}
li.is-done .check{background:var(--c)}
li.is-done .check svg{opacity:1}
.task-main{flex:1;min-width:0;text-align:left;border:0;background:none;padding:12px 14px 12px 12px;display:flex;flex-direction:column;gap:3px}
.task-title{font-weight:600;overflow-wrap:anywhere}
li.is-done .task-title{text-decoration:line-through;color:var(--muted);font-weight:500}
.task-meta{display:flex;flex-wrap:wrap;gap:4px 10px;font-size:.84rem;color:var(--muted)}
.task-meta .tag{color:var(--ink);font-weight:500}
.task-meta .late{color:var(--late);font-weight:600}
.pill{font-size:.75rem;font-weight:600;border-radius:6px;padding:1px 7px;background:var(--soft);color:var(--ink)}
.pill.hi{background:color-mix(in srgb,var(--late) 16%,transparent);color:var(--late)}

.empty{background:var(--surface);border:1px dashed var(--line);border-radius:14px;padding:22px;text-align:center;color:var(--muted)}
.empty strong{display:block;color:var(--ink);font:700 1.1rem var(--display);margin-bottom:4px}
.btn{border:1px solid var(--line);background:var(--surface);border-radius:12px;padding:10px 16px;font-weight:600}
.btn.primary{background:var(--accent);border-color:var(--accent);color:var(--accent-ink)}
.btn.danger{color:var(--late)}
.btn.small{padding:6px 12px;font-size:.88rem}
.btn.trash-btn{display:inline-flex;align-items:center;gap:5px}
.grp-kind button{flex:1}
.grp-tpl-row{display:flex;flex-wrap:wrap;gap:6px}
.grp-tpl-row .chip{display:inline-flex;align-items:center;gap:6px;flex-wrap:wrap}
.grp-tpl-row .chip .mini{font-weight:500;opacity:.8}
.grp-tpl-row .chip[aria-pressed=true]{background:var(--accent);color:#fff;border-color:var(--accent)}
.grp-tpl-row .chip[aria-pressed=true] .mini{color:#fff}
.grp-tpl-ic svg{width:18px;height:18px;display:block}
.fab-menu .fm-list{gap:10px}
.fab-menu .fm-list button{border:1px solid var(--line);border-radius:16px;padding:14px 16px;gap:14px;background:var(--surface);box-shadow:0 1px 2px rgba(0,0,0,.05);transition:transform .12s,box-shadow .12s,border-color .12s}
.fab-menu .fm-list button:hover,.fab-menu .fm-list button:focus-visible{border-color:var(--accent);box-shadow:0 6px 16px rgba(0,0,0,.12);transform:translateY(-1px)}
.fab-menu .fm-ic{flex:none;display:grid;place-items:center;width:46px;height:46px;border-radius:14px;background:color-mix(in srgb,var(--accent) 14%,var(--surface));color:var(--accent)}
.fab-menu .fm-ic .ai-ic{width:24px;height:24px;color:#8B5CF6}
.fab-menu .fm-t{flex:1;min-width:0}
.fab-menu .fm-t b{display:block;font-weight:700;font-size:1.02rem}
.fab-menu .fm-t .sub{margin-top:2px}
.fab-menu .fm-go{flex:none;color:var(--muted)}
.fab-menu .fm-list button.ai-row{border-color:color-mix(in srgb,#8B5CF6 45%,var(--line));background:color-mix(in srgb,#8B5CF6 8%,var(--surface))}
.fab-menu .fm-list button.ai-row .fm-ic{background:color-mix(in srgb,#8B5CF6 16%,var(--surface))}
@media (prefers-reduced-motion:reduce){.fab-menu .fm-list button{transition:none}.fab-menu .fm-list button:hover{transform:none}}
.empty .btn{margin-top:12px}
.link-btn{border:0;background:none;color:var(--accent);font-weight:600;padding:4px 0}

/* Board */
body.wide .wrap{max-width:1180px}
.board{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px;margin-top:12px;align-items:start}
@media (max-width:820px){
  .board{display:flex;overflow-x:auto;scroll-snap-type:x mandatory;gap:12px;margin:12px -18px 0;padding:0 18px 8px;scroll-padding:0 18px;scrollbar-width:none}
  .board::-webkit-scrollbar{display:none}
  .col{flex:0 0 84%;scroll-snap-align:start}
}
.board.dragging{scroll-snap-type:none}
.col{background:var(--soft);border-radius:16px;padding:10px;min-height:220px;transition:box-shadow .15s}
.col.over{box-shadow:inset 0 0 0 2px var(--accent)}
.col-head{display:flex;align-items:center;gap:8px;padding:4px 4px 10px;font:700 1.02rem var(--display)}
.col-resort{margin-left:auto;border:1px solid var(--line);background:var(--surface);color:var(--muted);border-radius:999px;padding:2px 9px;font:600 .74rem var(--body,inherit);cursor:pointer}.col-resort:hover{color:var(--ink)}

.col-head .sd{width:10px;height:10px;border-radius:3px;background:var(--sc)}
.col-head .n{color:var(--muted);font:500 .85rem var(--body)}
.col-list{display:flex;flex-direction:column;gap:8px;min-height:70px}
.card{position:relative;display:block;width:100%;text-align:left;border:1px solid color-mix(in srgb,var(--c) 28%,var(--line));border-left:5px solid var(--c);background:color-mix(in srgb,var(--c) 8%,var(--surface));border-radius:12px;padding:10px 12px;user-select:none;-webkit-user-select:none;-webkit-touch-callout:none;cursor:grab}
.card-course{font-size:.75rem;font-weight:700;color:color-mix(in srgb,var(--c) 78%,var(--ink))}
.card-title{font-weight:600;margin:2px 0 8px;overflow-wrap:anywhere;line-height:1.35}
.card.is-done .card-title{text-decoration:line-through;color:var(--muted)}
.ann-btn{position:relative}
.ann-btn[hidden]{display:none}
.ann-n{position:absolute;top:-5px;right:-5px;min-width:18px;height:18px;padding:0 5px;border-radius:9px;background:var(--late,#C0392B);color:#fff;font:700 .68rem/18px var(--body);text-align:center;box-sizing:border-box}
.nav-tool.ann-btn .ann-n{top:2px;right:calc(50% - 26px)}
.ann-sheet .sheet-body{gap:10px;align-content:start;grid-auto-rows:max-content}
.ann-bar{display:flex;gap:8px;flex-wrap:wrap;align-items:center}
.ann-bar .spacer{flex:1}
.ann-course{display:flex;align-items:center;gap:8px;margin:8px 0 0;font:700 .98rem var(--display)}
.ann-course .sd{width:10px;height:10px;border-radius:50%;background:var(--c);flex:none}
.ann-course .n{font:600 .75rem var(--body);color:var(--muted);margin-left:auto}
.ann-list{list-style:none;margin:0;padding:0;display:grid}
.ann-list li{padding:10px 2px 10px 14px;border-bottom:1px solid var(--line);position:relative}
.ann-list li.unread::before{content:"";position:absolute;left:0;top:17px;width:8px;height:8px;border-radius:50%;background:var(--accent)}
.ann-list li b{display:block;overflow-wrap:anywhere}
.ann-list li:not(.unread) b{font-weight:600;color:var(--muted)}
.ann-list .mini{display:block}
.ann-list details summary{cursor:pointer;color:var(--accent);font-size:.8rem;margin-top:4px}
.ann-list .ann-txt{margin:4px 0 0;font-size:.88rem;white-space:pre-line;overflow-wrap:anywhere}
.ann-list .bs-btns{margin-top:6px}
.ann-tabs{flex:none;display:flex;gap:6px;overflow-x:auto;padding:2px 2px 8px;margin:0 -2px;scrollbar-width:thin;-webkit-overflow-scrolling:touch;scroll-snap-type:x proximity;overscroll-behavior-x:contain}
.ann-tab{flex:none;display:inline-flex;align-items:center;gap:6px;max-width:min(70vw,220px);min-height:36px;padding:6px 12px;border-radius:999px;border:1px solid var(--line);background:var(--surface);color:var(--ink);font:600 .82rem var(--body);cursor:pointer;scroll-snap-align:start}
.ann-tab .sd{width:9px;height:9px;border-radius:50%;flex:none}
.ann-tab .ann-tl{overflow:hidden;text-overflow:ellipsis;white-space:nowrap;min-width:0}
.ann-tab[aria-selected="true"]{background:var(--ink);color:var(--bg);border-color:var(--ink)}
.ann-tab:focus-visible,#annPanel:focus-visible{outline:2px solid var(--accent);outline-offset:2px}
.ann-pill{flex:none;min-width:18px;height:18px;padding:0 5px;border-radius:9px;background:var(--accent);color:var(--accent-ink);font:700 .68rem/18px var(--body);text-align:center}
.ann-tab[aria-selected="true"] .ann-pill{background:var(--bg);color:var(--ink)}
#annPanel{flex:none;outline:none;display:grid;gap:2px}
.ann-bar,.ann-status{flex:none}
.ann-home-h{margin:6px 0 0;font:700 1.05rem var(--display)}
.ann-home-note{margin:0 0 4px}
.ann-chip{display:inline-flex;align-items:center;gap:6px;max-width:100%;margin:0 0 3px;padding:2px 9px 2px 7px;border-radius:999px;border:1px solid var(--line);background:var(--soft);font:600 .74rem var(--body);color:var(--ink)}
.ann-chip .sd{width:8px;height:8px;border-radius:50%;background:var(--c);flex:none}
.ann-chip .n{color:var(--muted);font-weight:500}
.ann-list li>.ann-chip{display:flex;width:max-content}
.ann-browse{display:flex;flex-wrap:wrap;gap:8px;margin-top:6px}
.ann-browse .btn-chip{cursor:pointer;padding:6px 11px;font-size:.8rem}
.ann-browse .btn-chip:hover{border-color:var(--accent)}
.ann-status{margin:0;padding:8px 10px;border-radius:10px;font-size:.86rem;background:var(--soft);overflow-wrap:anywhere}
.ann-status[data-kind="err"]{background:color-mix(in srgb,var(--late) 12%,var(--surface));color:var(--ink)}
.ann-status[data-kind="ok"]{background:color-mix(in srgb,var(--accent) 10%,var(--surface))}
.ann-status .btn{margin-left:6px}
.lms-go{flex:none;width:28px;height:28px;border-radius:50%;border:1px solid var(--line);background:var(--surface);color:var(--accent);display:inline-grid;place-items:center;padding:0;cursor:pointer}
.lms-go:hover{border-color:var(--accent);background:color-mix(in srgb,var(--accent) 10%,var(--surface))}
li.task>.lms-go{align-self:center;margin-right:12px}
.card-foot .lms-go{width:24px;height:24px;margin-left:auto}
.card-foot .lms-go svg{width:13px;height:13px}
.nu-row>.lms-go{align-self:center}
.plan-side .lms-go{margin-right:6px}
.course-wrap{display:flex;flex-direction:column;align-items:stretch}
.card-foot{display:flex;flex-wrap:wrap;gap:6px 10px;align-items:center;font-size:.8rem;color:var(--muted)}
.card-foot .late{color:var(--late);font-weight:600}
.placeholder{border:2px dashed var(--accent);border-radius:12px;background:color-mix(in srgb,var(--accent) 8%,transparent)}
.ghost{position:fixed;z-index:50;pointer-events:none;margin:0;transform:rotate(2deg) scale(1.03);box-shadow:0 14px 30px rgba(0,0,0,.28);cursor:grabbing;will-change:transform}
.prio{font-size:.72rem;font-weight:700;border-radius:6px;padding:1px 7px;white-space:nowrap}
.prio.low{background:var(--bg);color:var(--muted);border:1px solid var(--line)}
.prio.med{background:color-mix(in srgb,var(--accent) 15%,transparent);color:var(--accent)}
.prio.high{background:color-mix(in srgb,#E0673B 20%,transparent);color:color-mix(in srgb,#E0673B 75%,var(--ink))}
.prio.urgent{background:var(--late);color:#fff}
.hint-line{font-size:.85rem;color:var(--muted);margin:10px 0 0}

/* Timeline */
.tl-controls{display:flex;align-items:center;gap:10px;flex-wrap:wrap;margin-top:12px}
.tl-controls > .spacer{flex:1}
.tl-controls h2{flex:1;margin:0;font:700 1.2rem var(--display)}
.segb{display:flex;background:var(--surface);border:1px solid var(--line);border-radius:10px;padding:3px;gap:3px;flex:none;max-width:100%}   /* never squeezed narrower than its buttons, so the chosen pill sits evenly inside the outline at either end */
.segb button{border:0;background:none;border-radius:8px;padding:6px 12px;font-size:.85rem;font-weight:500;white-space:nowrap}
.segb button[aria-pressed="true"]{background:var(--ink);color:var(--bg);font-weight:600}
.tl-scroll{overflow-x:auto;background:var(--surface);border:1px solid var(--line);border-radius:14px;margin-top:10px}
.tl{position:relative}
.tl-bg{position:absolute;top:0;bottom:0;pointer-events:none;z-index:0}
.tl-bg .we{position:absolute;top:0;bottom:0;background:var(--soft)}
.tl-bg-top{z-index:1}
.tl-bg .today-line{position:absolute;top:58px;bottom:0;width:2px;background:var(--late)}
/* Today's line runs behind a due date's marker and label, never through them: they sit above it, the marker's own ring keeps a gap round it and the label has a soft halo in the page colour, so the line fades out behind the text */
.tl-track > .tl-ic,.tl-track > .tl-dl{z-index:2}
.tl-track > .tl-dl{text-shadow:0 0 2px var(--surface),0 0 4px var(--surface),0 0 6px var(--surface),0 0 8px var(--surface)}
.tl-row{display:flex;position:relative;z-index:auto;height:46px}
.tl-row > .tl-label,.tl-row > .tl-track{border-top:1px solid var(--line)}
.tl-headrow{height:30px}
.tl-headrow > .tl-label,.tl-headrow > .tl-track{border-top:0}
.tl-headrow + .tl-headrow{height:28px}
.tl-label{position:sticky;left:0;z-index:3;flex:none;background:var(--surface);border:0;border-right:1px solid var(--line);text-align:left;padding:3px 10px;display:flex;flex-direction:column;justify-content:center;overflow:hidden;font-size:.84rem;font-weight:600;white-space:nowrap;border-radius:0}
.tl-label .tt{overflow:hidden;text-overflow:ellipsis}
.tl-label small{font-weight:400;color:var(--muted);font-size:.72rem}
.tl-label.done .tt{text-decoration:line-through;color:var(--muted)}
.tl-group{height:34px;background:color-mix(in srgb,var(--c) 7%,transparent)}
.tl-group .tl-label{flex-direction:row;align-items:center;justify-content:flex-start;gap:8px;font:700 .88rem var(--display);background:color-mix(in srgb,var(--c) 7%,var(--surface))}
.tl-group .sd{width:10px;height:10px;border-radius:3px;background:var(--c);flex:none}
.tl-track{position:relative;flex:none}
.tl-m{position:absolute;top:0;bottom:0;overflow:hidden;box-sizing:border-box;display:flex;align-items:center;font:700 .92rem var(--display);letter-spacing:.01em;padding-left:8px;white-space:nowrap;border-left:1px solid var(--line)}
.tl-m small{font:600 .78rem var(--body);color:var(--muted);margin-left:6px}
.tl-d{position:absolute;top:0;bottom:0;display:flex;align-items:center;justify-content:center;font-size:.84rem;font-weight:500;color:var(--muted)}
.tl-d b{font:inherit}
.tl-d.is-today b{background:var(--late);color:#fff;border-radius:999px;min-width:22px;padding:1px 4px;text-align:center;font-weight:700}
.tl-d.is-today{color:var(--late);font-weight:700}
.tlbar{position:absolute;top:9px;height:28px;border-radius:7px;border:1.5px solid var(--c);background:color-mix(in srgb,var(--c) 20%,var(--surface));color:var(--ink);font-size:.75rem;font-weight:600;text-align:left;padding:0 8px;overflow:hidden;white-space:nowrap;text-overflow:ellipsis;min-width:10px}
.tlbar.st-doing{background:var(--c);color:#fff}
.tlbar.st-done{background:repeating-linear-gradient(135deg,color-mix(in srgb,var(--c) 22%,var(--surface)) 0 5px,var(--surface) 5px 10px);color:var(--muted);text-decoration:line-through;border-style:dashed}
.tlbar.late{box-shadow:inset -5px 0 0 var(--late)}
.tl-legend{display:flex;flex-wrap:wrap;gap:8px 16px;font-size:.82rem;color:var(--muted);margin-top:10px;align-items:center}
.tl-legend .tlbar{position:static;display:inline-block;width:34px;height:14px;padding:0;vertical-align:middle;margin-right:6px;--c:var(--muted)}

/* Courses */
.course-list{display:grid;gap:12px;margin-top:14px}
.course-card{display:flex;gap:14px;align-items:stretch;text-align:left;width:100%;background:var(--surface);border:1px solid var(--line);border-radius:14px;padding:14px}
.course-card .swatch{width:6px;border-radius:4px;background:var(--c);flex:none}
.course-card .body{flex:1;min-width:0;overflow-wrap:anywhere}
.course-card h3{margin:0;font:700 1.1rem/1.25 var(--display)}
.course-card .code{color:var(--muted);font-size:.88rem}
.course-card .stats{display:flex;gap:14px;margin-top:8px;font-size:.88rem;color:var(--muted)}
.course-card .stats b{color:var(--ink)}
.course-card .stats .late{color:var(--late)}

.detail-head{border-left:6px solid var(--c);padding:4px 0 4px 14px;margin:14px 0 4px}
.detail-head h2{margin:0;font:700 1.7rem/1.15 var(--display);letter-spacing:-.02em}
.detail-head .code{color:var(--muted)}
.facts{display:grid;grid-template-columns:auto 1fr;gap:6px 14px;margin:16px 0;font-size:.95rem;background:var(--surface);border:1px solid var(--line);border-radius:14px;padding:14px}
.facts dt{color:var(--muted)}
.facts dd{margin:0;overflow-wrap:anywhere}
.row-actions{display:flex;gap:10px;flex-wrap:wrap;margin:6px 0}
.notes{white-space:pre-wrap;background:var(--surface);border:1px solid var(--line);border-radius:14px;padding:14px;margin:0}
.back{display:inline-flex;align-items:center;gap:4px;border:0;background:none;color:var(--muted);padding:6px 0;font-weight:500}
.back svg{width:18px;height:18px}

/* Calendar */
.cal-head{display:flex;align-items:center;gap:10px;margin:14px 0 10px}
.cal-head h2{flex:1;margin:0;font:700 1.3rem var(--display)}
.cal{display:grid;grid-template-columns:repeat(7,1fr);gap:4px}
.cal .dow{text-align:center;font-size:.75rem;color:var(--muted);padding-bottom:2px}
.day{aspect-ratio:1/1.05;border:1px solid transparent;border-radius:10px;background:var(--surface);display:flex;flex-direction:column;align-items:center;padding:5px 2px;gap:4px;font-size:.9rem}
.day.out{background:transparent;color:var(--muted);opacity:.55}
.day.is-today .num{background:var(--mark);color:var(--ink);border-radius:6px;padding:0 5px;font-weight:700}
.day[aria-pressed="true"]{border-color:var(--ink)}
.dots{display:flex;gap:3px;flex-wrap:wrap;justify-content:center;max-width:34px}
.dots i{width:6px;height:6px;border-radius:50%;background:var(--c)}
.dots i.ci{display:grid;place-items:center;width:24px;height:24px;margin:0;border-radius:50%;color:#fff;transform:none}
.dots i.ci svg{width:15px;height:15px;stroke-width:2.2}
.dots{gap:2px;max-width:100%}
.dots .ci-more{font:700 .72rem/24px var(--body);color:var(--muted)}
@media (max-width:600px){.dots i.ci{width:15px;height:15px}.dots i.ci svg{width:10px;height:10px}.dots .ci-more{line-height:15px}}

/* Dialog */
dialog{border:0;padding:0;background:var(--surface);color:var(--ink);width:min(560px,100%);max-height:92vh;border-radius:20px;box-shadow:0 20px 60px rgba(0,0,0,.3)}
dialog::backdrop{background:rgba(10,14,24,.5)}
@media (max-width:600px){
  dialog{margin:auto 0 0;max-width:100%;width:100%;border-radius:20px 20px 0 0;max-height:90vh}
}
.sheet{display:flex;flex-direction:column;max-height:inherit}
.sheet-head{display:flex;align-items:center;gap:10px;padding:16px 18px 8px}
.sheet-head h2{flex:1;margin:0;font:700 1.25rem var(--display)}
.sheet-body{overflow:auto;padding:6px 18px 12px;display:grid;gap:14px}
.sheet-foot{display:flex;flex-wrap:wrap;gap:10px;padding:12px 18px calc(14px + env(safe-area-inset-bottom,0px));border-top:1px solid var(--line)}
.sheet-foot .spacer{flex:1}
label.f{display:grid;gap:5px;font-size:.88rem;font-weight:600}
label.f .hint{font-weight:400;color:var(--muted)}
label.f .lh{display:flex;flex-wrap:wrap;align-items:baseline;gap:0 6px}
label.f .lh .req{margin-left:0}
input[type=text],input[type=search],input[type=date],input[type=time],input[type=number],input[type=url],select,textarea{width:100%;border:1px solid var(--line);background:var(--bg);border-radius:10px;padding:10px 12px;font-size:max(16px,1rem);font-weight:400}
textarea{min-height:84px;resize:vertical}
.two{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:12px}
.two>*,label.f{min-width:0}
label.f select,label.f input:not([type=checkbox]):not([type=radio]){max-width:100%;min-width:0}
fieldset{border:0;margin:0;padding:0;display:grid;gap:6px}
legend{font-size:.88rem;font-weight:600;padding:0;margin-bottom:6px}
.seg{display:flex;background:var(--bg);border:1px solid var(--line);border-radius:10px;padding:3px;gap:3px}
.seg label{flex:1;position:relative}
.seg input{position:absolute;opacity:0;inset:0}
.seg span{display:block;text-align:center;padding:7px 4px;border-radius:8px;font-size:.88rem;font-weight:500}
.seg input:checked+span{background:var(--surface);box-shadow:0 1px 3px rgba(0,0,0,.12);font-weight:600}
.seg input:focus-visible+span{outline:2px solid var(--accent)}
.swatches{display:flex;gap:10px;flex-wrap:wrap}
.swatches label{position:relative}
.swatches input{position:absolute;opacity:0}
.swatches span{display:block;width:34px;height:34px;border-radius:50%;background:var(--c);border:3px solid var(--surface);box-shadow:0 0 0 1px var(--line)}
.swatches input:checked+span{box-shadow:0 0 0 2px var(--ink)}
.swatches input:focus-visible+span{outline:2px solid var(--accent);outline-offset:2px}
.menu-list{display:grid;gap:4px}
.menu-list button,.menu-list label.mi{display:flex;align-items:center;gap:12px;border:0;background:none;padding:12px 4px;text-align:left;border-bottom:1px solid var(--line);font-size:1rem;cursor:pointer}
.menu-list .sw{margin-left:auto}
.toast{position:fixed;left:50%;bottom:calc(140px + env(safe-area-inset-bottom,0px));transform:translateX(-50%);background:var(--ink);color:var(--bg);padding:10px 16px;border-radius:12px;font-size:.9rem;z-index:50;opacity:0;pointer-events:none;transition:opacity .2s}
.toast.show{opacity:1}
@media (prefers-reduced-motion:reduce){.toast{transition:none}}
.sr{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0)}
/* v2 additions */
nav.tabs .in{grid-template-columns:repeat(5,1fr)!important;max-width:720px}
nav.tabs button{font-size:.75rem!important}
.head-actions{display:flex;align-items:center;gap:8px}
#toolbar{display:grid;gap:8px;margin-bottom:4px}
#toolbar [hidden]{display:none!important}
.search-row{display:flex;gap:8px;align-items:center}
.search-row input{flex:1}
.qp{border-radius:6px;padding:1px 8px;background:var(--soft);color:var(--ink);font-weight:500;display:inline-flex;align-items:center;gap:6px}
.qp .dot{width:8px;height:8px;border-radius:50%;background:var(--c)}
.search-note{display:flex;align-items:center;gap:8px;font-size:.9rem;color:var(--muted);margin-top:10px}
.focus{background:var(--surface);border:1px solid var(--line);border-radius:16px;padding:14px;margin-top:6px}
.focus-head{display:flex;align-items:flex-start;gap:10px}
.focus-head h2{margin:0;font:700 1.15rem/1.2 var(--display)}
.focus-head h2 span{background:linear-gradient(transparent 50%,var(--mark) 50%,var(--mark) 90%,transparent 90%);padding:0 3px;margin:0 -3px}
.focus-sum{color:var(--muted);font-size:.9rem;margin-top:3px}
.focus-sum b{color:var(--ink)}
.focus-sum .late{color:var(--late)}
.focus ul.tasks{margin-top:12px}
.why{font-size:.78rem;color:var(--muted)}
.card-meta{display:flex;flex-wrap:wrap;gap:6px;align-items:center;margin-top:6px}
.soon{font-size:.72rem;font-weight:700;border-radius:6px;padding:1px 7px;background:var(--mark);color:#3A3000}
.soon.late{background:var(--late);color:#fff}
.prog{display:flex;align-items:center;gap:6px;font-size:.75rem;color:var(--muted);margin-top:8px}
.prog .track{flex:1;height:5px;border-radius:3px;background:color-mix(in srgb,var(--c) 18%,var(--surface));overflow:hidden}
.prog .track i{display:block;height:100%;background:var(--c)}
.mini{font-size:.75rem;color:var(--muted)}
.show-old{border:1px dashed var(--line);background:none;border-radius:12px;padding:8px;color:var(--muted);font-weight:600;font-size:.85rem}
.tlbar{touch-action:pan-y}
.tlbar .fill{position:absolute;left:0;top:0;bottom:0;background:color-mix(in srgb,var(--c) 40%,transparent);pointer-events:none}
.tlbar .txt{position:relative}
.tlbar.st-doing .fill{background:rgba(255,255,255,.25)}
.tlbar::before,.tlbar::after{content:"";position:absolute;top:5px;bottom:5px;width:3px;border-radius:2px;background:color-mix(in srgb,var(--c) 70%,var(--ink));opacity:0;transition:opacity .15s}
.tlbar::before{left:3px}.tlbar::after{right:3px}
.tlbar:hover::before,.tlbar:hover::after,.tlbar.dragging::before,.tlbar.dragging::after{opacity:.8}
.tlbar.dragging{z-index:5;box-shadow:0 6px 16px rgba(0,0,0,.25);cursor:grabbing}
.tl-tip{position:fixed;z-index:60;background:var(--ink);color:var(--bg);font-size:.8rem;font-weight:600;padding:5px 9px;border-radius:8px;pointer-events:none;white-space:nowrap}
.tl-work{height:40px}
.tl-work .tl-label{font-size:.75rem;color:var(--muted);font-weight:600}
.wk{position:absolute;top:4px;bottom:4px;border-radius:6px;display:flex;align-items:center;justify-content:center;font-size:.72rem;font-weight:700;color:var(--ink);border:1px solid var(--line);overflow:hidden;white-space:nowrap}
.wk.over{color:#fff;background:var(--late)!important;border-color:var(--late)}
.cl-edit{list-style:none;margin:0;padding:0;display:grid;gap:6px}
.cl-edit li{display:flex;align-items:center;gap:8px}
.cl-edit input[type=checkbox]{width:20px;height:20px;flex:none;accent-color:var(--accent)}
.cl-edit input[type=text]{flex:1}
.cl-edit li.done input[type=text]{text-decoration:line-through;color:var(--muted)}
.cl-new{display:flex;gap:8px;margin-top:6px}
.cl-new input{flex:1}
.x-btn{border:0;background:none;color:var(--muted);width:34px;height:34px;border-radius:8px;flex:none;display:grid;place-items:center}
.x-btn svg{width:16px;height:16px}
.toast{display:flex;align-items:center;gap:14px}
.toast.show{pointer-events:auto}
.toast button{border:0;background:none;color:var(--mark);font-weight:700;padding:2px 4px}
.toast button[hidden]{display:none}
.imp-list{list-style:none;margin:0;padding:0;display:grid;gap:6px;max-height:48vh;overflow:auto}
.status-msg{color:var(--muted);font-size:.9rem}
.menu-list .sub{display:block;font-size:.8rem;color:var(--muted);font-weight:400}
.menu-list button span,.menu-list label span{display:block}
.cap-row{display:flex;align-items:center;gap:10px;padding:10px 4px;border-bottom:1px solid var(--line)}
.cap-row input{width:90px}
.backup-list{display:grid;gap:8px}
.backup-list button{display:flex;justify-content:space-between;gap:10px;text-align:left;border:1px solid var(--line);background:var(--bg);border-radius:10px;padding:10px 12px}
.backup-list small{color:var(--muted)}
.link-row{display:flex;gap:14px;flex-wrap:wrap;font-size:.9rem}
[hidden]{display:none!important}
.nudge{display:flex;align-items:center;gap:10px;flex-wrap:wrap;margin-top:6px;padding:12px 14px;border-radius:14px;background:color-mix(in srgb,var(--mark) 30%,var(--surface));border:1px solid color-mix(in srgb,var(--mark) 60%,var(--line))}
.nudge span{flex:1;min-width:220px;font-size:.92rem}
.plan .focus-head{flex-wrap:wrap}
.hours-ctl{display:flex;align-items:center;gap:6px;background:var(--bg);border:1px solid var(--line);border-radius:12px;padding:4px 6px}
.hours-ctl b{min-width:44px;text-align:center;font-variant-numeric:tabular-nums}
.icon-btn.sm{width:30px;height:30px;border-radius:8px;font-size:1.1rem;font-weight:700;line-height:1}
.plan-warn{margin:10px 0 0;padding:10px 12px;border-radius:10px;background:color-mix(in srgb,var(--late) 12%,var(--surface));border:1px solid color-mix(in srgb,var(--late) 35%,transparent);font-size:.9rem}
.plan-list{list-style:none;margin:12px 0 0;padding:0}
.plan-more,.plan-how{margin-top:12px}
.plan-how p{font-size:.88rem;color:var(--muted);margin:8px 0 0;max-width:75ch}
.plan-fs{border:1px solid var(--line);border-radius:12px;padding:12px;display:grid;gap:12px}
.plan-fs legend{padding:0 6px}
.plan-hint{margin:0;font-size:.85rem;color:var(--muted)}
.plan-hint b{color:var(--ink)}

.nb-wrap{position:relative;margin-top:10px}
.nb-scroll{overflow:auto;height:calc(100vh - 290px);height:calc(100dvh - 290px);min-height:380px;border-radius:16px;border:1px solid color-mix(in srgb,#7A5230 40%,var(--line));box-shadow:inset 0 2px 10px rgba(60,35,10,.25)}
.nb-board{position:relative;z-index:0;isolation:isolate;min-width:100%;min-height:100%;box-sizing:border-box;background-color:#C69C6D;background-image:radial-gradient(rgba(90,55,20,.28) 1px,transparent 1.4px),radial-gradient(rgba(255,235,200,.22) 1px,transparent 1.5px);background-size:9px 9px,13px 13px;background-position:0 0,5px 7px}
.nb-board{-webkit-touch-callout:none}
.nb-scroll{touch-action:pan-x pan-y}   /* two-finger pinch zooms the board (handled in the page), not the whole page */
.nb-sizer{width:100%;height:100%}
.nb-sizer.zoomed{position:relative;overflow:hidden;width:auto;height:auto}
.nb-sizer.zoomed > .nb-board{transform-origin:0 0}
.nb-zoom{position:absolute;top:14px;left:14px;z-index:6;display:flex;align-items:center;gap:2px;padding:3px;border-radius:999px;background:color-mix(in srgb,var(--surface) 88%,transparent);border:1px solid var(--line);box-shadow:0 2px 8px rgba(40,25,10,.18);-webkit-backdrop-filter:blur(6px);backdrop-filter:blur(6px)}
.nb-zoom button{border:0;background:none;color:var(--ink);font:700 .82rem var(--display);min-width:30px;height:30px;padding:0 6px;border-radius:999px;cursor:pointer;display:inline-flex;align-items:center;justify-content:center;gap:4px;font-variant-numeric:tabular-nums}
.nb-zoom .nbz-b{font-size:1.05rem}
.nb-zoom button:hover:not(:disabled),.nb-zoom button:focus-visible{background:var(--soft)}
.nb-zoom button:disabled{opacity:.35;cursor:default}
.nb-zoom .nbz-pct svg{width:13px;height:13px}
.nb-zoom .nbz-pct.on{color:var(--accent)}
:root[data-theme="dark"] .nb-board{background-color:#6E5238}
@media (prefers-color-scheme:dark){:root:not([data-theme="light"]) .nb-board{background-color:#6E5238}}
.note{position:absolute;min-height:140px;padding:26px 14px 14px;background:var(--nc);color:#2A2418;border-radius:3px;box-shadow:0 8px 16px rgba(40,25,5,.28),0 1px 2px rgba(0,0,0,.2);transform:rotate(var(--rot));touch-action:none;cursor:grab;user-select:none;-webkit-user-select:none;-webkit-touch-callout:none;font-size:.95rem;line-height:1.4;transition:box-shadow .15s,opacity .15s}
.note:focus-visible{outline:3px solid var(--accent);outline-offset:3px}
.note.dragging{cursor:grabbing;box-shadow:0 18px 32px rgba(40,25,5,.38);transform:rotate(calc(var(--rot) + 3deg)) scale(1.04);pointer-events:none;transition:none;opacity:.95}
.note.dragging.over-target{opacity:.55;transform:scale(.8)}
.note.dim{opacity:.35}
.note.editing{cursor:default;touch-action:auto;user-select:text;-webkit-user-select:text;box-shadow:0 18px 40px rgba(40,25,5,.4)}
.pin{position:absolute;top:6px;left:50%;width:14px;height:14px;margin-left:-7px;border-radius:50%;background:radial-gradient(circle at 35% 35%,#FF8A80,#C62828 60%,#7F0000);box-shadow:0 2px 3px rgba(0,0,0,.35)}
.note-body{white-space:pre-wrap;overflow-wrap:anywhere;max-height:260px;overflow:hidden}
.note-empty{color:rgba(42,36,24,.55);font-style:italic}
.note-tag{display:inline-block;font-size:.7rem;font-weight:700;padding:1px 6px;border-radius:5px;background:color-mix(in srgb,var(--c) 22%,rgba(255,255,255,.6));color:color-mix(in srgb,var(--c) 70%,#1a1a1a);margin-bottom:6px;border-left:3px solid var(--c)}
.note-text{width:100%;min-height:120px;border:0;background:rgba(255,255,255,.45);border-radius:6px;padding:8px;font:inherit;color:#2A2418;resize:vertical}
.note-text:focus-visible{outline:2px solid rgba(42,36,24,.4)}
.note-conflict{display:block;width:100%;margin:0 0 6px;border:1px dashed rgba(42,36,24,.55);background:rgba(255,255,255,.55);color:#2A2418;border-radius:8px;padding:5px 8px;font:600 .74rem var(--body);text-align:left;cursor:pointer}
.sync-issue{border:1px solid var(--line);border-radius:12px;padding:12px;margin:0 0 10px;background:var(--surface);display:grid;gap:8px}
.sync-cols{display:grid;grid-template-columns:1fr 1fr;gap:8px}
@media(max-width:480px){.sync-cols{grid-template-columns:1fr}}
.sync-cols>div{min-width:0;border:1px solid var(--line);border-radius:10px;padding:8px;background:var(--bg)}
.sync-txt{white-space:pre-wrap;overflow-wrap:anywhere;max-height:9em;overflow:auto;font-size:.9rem;margin-top:4px}
.sync-btns{display:flex;flex-wrap:wrap;gap:8px}
.note-tools{display:grid;gap:8px;margin-top:8px}
.note-colors{display:flex;gap:6px;flex-wrap:wrap}
.nc{width:22px;height:22px;border-radius:50%;border:2px solid rgba(42,36,24,.25);padding:0}
.nc.on{border-color:#2A2418;box-shadow:0 0 0 2px rgba(255,255,255,.7)}
.note-course{padding:6px 8px;font-size:.875rem;background:rgba(255,255,255,.55);border:1px solid rgba(42,36,24,.2);border-radius:8px;color:#2A2418}
.note-btns{display:flex;gap:6px;align-items:center}
.note-btns .nb{border:0;background:rgba(255,255,255,.5);border-radius:8px;width:36px;height:34px;display:grid;place-items:center;color:#2A2418}
.note-btns .nb svg{width:18px;height:18px}
.note-btns .btn{margin-left:auto}
.note-hbtns{display:flex;flex-wrap:wrap;gap:4px}
.note-hbtns .btn,.note-xbtns .btn,.note-moredd>summary.btn{padding:3px 8px;font-size:.78rem;background:rgba(255,255,255,.5);color:#2A2418;border-color:transparent}
.nx-list{display:grid;gap:4px;max-height:38vh;overflow:auto;border:1px solid var(--line);border-radius:10px;padding:6px}
.nx-list label{display:flex;gap:8px;align-items:flex-start;font-size:.88rem;padding:3px 2px}
.nx-list .nx-h{font-weight:700;margin-top:4px}
.nx-list .nx-t{display:block;color:var(--muted);font-size:.8rem;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;max-width:46ch}
.nx-btns{display:flex;flex-wrap:wrap;gap:8px}
.nv-list{list-style:none;margin:0;padding:0;display:grid;gap:6px;max-height:50vh;overflow:auto}
.nv-list li{border:1px solid var(--line);border-radius:10px;padding:8px 10px;display:grid;gap:4px}
.nv-list .nv-top{display:flex;gap:8px;align-items:center;justify-content:space-between;font-size:.82rem;color:var(--muted)}
.nv-list .nv-pre{font-size:.86rem;white-space:pre-wrap;word-break:break-word;max-height:4.6em;overflow:hidden}
.nb-empty{position:absolute;left:50%;top:120px;transform:translateX(-50%);background:rgba(255,255,255,.85);color:#3A2E1C;border-radius:12px;padding:16px 20px;text-align:center;max-width:300px}
.nb-empty strong{display:block;font:700 1.05rem var(--display)}
.nb-targets{position:absolute;right:14px;bottom:14px;display:flex;gap:12px;pointer-events:none}
.nb-target{pointer-events:auto;width:84px;height:84px;border-radius:18px;background:color-mix(in srgb,var(--surface) 92%,transparent);border:2px solid var(--line);display:flex;flex-direction:column;align-items:center;justify-content:center;gap:4px;font-size:.75rem;font-weight:700;color:var(--ink);box-shadow:0 6px 16px rgba(0,0,0,.18);transition:transform .15s,background .15s,border-color .15s;cursor:pointer}
.nb-target.trash{cursor:pointer}
.nb-boards{display:flex;gap:6px;align-items:center;flex-wrap:wrap;margin:10px 0 12px}
.nb-tab{display:inline-flex;align-items:center;gap:7px;border:1.5px solid var(--line);background:var(--surface);color:var(--ink);border-radius:999px;padding:7px 13px;font:600 .88rem var(--display);min-height:40px;cursor:pointer;max-width:220px}
.nb-tab .sd{width:10px;height:10px;border-radius:50%;background:var(--c);flex:none}
.nb-tab .nb-tn{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.nb-tab .n{font:600 .74rem var(--body);color:var(--muted);background:var(--soft);border-radius:999px;padding:0 7px}
.nb-tab.on{border-color:var(--c);background:color-mix(in srgb,var(--c) 14%,var(--surface));box-shadow:0 0 0 1px var(--c)}
.nb-tab.add{border-style:dashed;color:var(--muted)}
.nb-tab.hot{transform:scale(1.06);border-color:var(--accent);background:color-mix(in srgb,var(--accent) 18%,var(--surface))}
.nb-target.hot{transform:scale(1.15);border-color:var(--accent);background:color-mix(in srgb,var(--accent) 18%,var(--surface))}
