/* ===== Studyboard look: notebook spine, graph paper, index cards ===== */
:root{
  --paper:#E5EAF2; --grid:rgba(57,136,254,.08); --surface:#F7F9FC; --ink:#0F1F3D; --navy:#0E2A56; --muted:#56657F;
  --line:#D2DBE8; --soft:#E1E8F2; --field:#F0F3F8; --accent:#1A60D0; --accent-2:#3988FE; --accent-ink:#FFFFFF;
  --sel:#0E2A56; --sel-ink:#FFFFFF; --mark:#FFE45C; --late:#D2382B; --tomato:#E4513B; --leaf:#1E9E74; --warn:#B86A00;
  --spine:#0E2A56; --spine-ink:#C9D7F2; --spine-hi:rgba(255,255,255,.11);
  --shadow:0 1px 2px rgba(14,42,86,.06),0 4px 14px rgba(14,42,86,.06);
  --bg:var(--paper);
  --display:"Lexend", "Avenir Next", "Segoe UI", system-ui, sans-serif;
  --body:"Atkinson Hyperlegible Next", "Atkinson Hyperlegible", "Segoe UI", system-ui, -apple-system, sans-serif;
  color-scheme:light;
}
@media (prefers-color-scheme:dark){
  :root:not([data-theme="light"]){
    --paper:#0A1428; --grid:rgba(96,160,255,.055); --surface:#111E38; --ink:#E7EEFA; --navy:#0E2A56; --muted:#93A3C2;
    --line:#22355C; --soft:#172848; --field:#0D1A33; --accent:#5B9DFF; --accent-2:#6BAAFF; --accent-ink:#071430;
    --sel:#3A6BC4; --sel-ink:#FFFFFF; --mark:#8C7713; --late:#FF7B6E; --tomato:#FF6B55; --leaf:#3CC794; --warn:#F2B04C;
    --spine:#060F24; --spine-ink:#A9BADC; --spine-hi:rgba(255,255,255,.08);
    --shadow:0 1px 2px rgba(0,0,0,.3),0 6px 18px rgba(0,0,0,.25);
    color-scheme:dark;
  }
}
:root[data-theme="dark"]{
  --paper:#0A1428; --grid:rgba(96,160,255,.055); --surface:#111E38; --ink:#E7EEFA; --navy:#0E2A56; --muted:#93A3C2;
  --line:#22355C; --soft:#172848; --field:#0D1A33; --accent:#5B9DFF; --accent-2:#6BAAFF; --accent-ink:#071430;
  --sel:#3A6BC4; --sel-ink:#FFFFFF; --mark:#8C7713; --late:#FF7B6E; --tomato:#FF6B55; --leaf:#3CC794; --warn:#F2B04C;
  --spine:#060F24; --spine-ink:#A9BADC; --spine-hi:rgba(255,255,255,.08);
  --shadow:0 1px 2px rgba(0,0,0,.3),0 6px 18px rgba(0,0,0,.25);
  color-scheme:dark;
}
body{background-color:var(--paper);background-image:linear-gradient(var(--grid) 1px,transparent 1px),linear-gradient(90deg,var(--grid) 1px,transparent 1px);background-size:24px 24px;background-attachment:fixed;font-size:16px;line-height:1.5}
h1,h2,h3{text-wrap:balance}
.wrap{padding-inline:16px}
/* Logo swaps with the theme */
.brand{display:flex;align-items:center;flex:none}
.brand .logo{height:34px;width:154px;display:block}
.site-link{display:block;color:inherit;border-radius:10px}.site-link[href]{cursor:pointer}.site-link[href]:hover{opacity:.85}.site-link:focus-visible{outline:2px solid var(--accent,#3B6FE0);outline-offset:3px}   /* the logo opens the Studyboard website */
.logo-d{display:none!important}
@media (prefers-color-scheme:dark){:root:not([data-theme="light"]) .logo-l{display:none!important}:root:not([data-theme="light"]) .logo-d{display:block!important}}
:root[data-theme="dark"] .logo-l{display:none!important}
:root[data-theme="dark"] .logo-d{display:block!important}
/* Header */
header.top{background:color-mix(in srgb,var(--paper) 86%,transparent);-webkit-backdrop-filter:blur(10px);backdrop-filter:blur(10px);padding:12px 0 10px;margin-inline:-16px;padding-inline:16px;border-bottom:1px solid transparent}
.top-row{gap:10px}
.top-row > div:first-child{display:flex;align-items:center;gap:14px;flex-wrap:wrap}
.today{font:500 .9rem/1.2 var(--display);color:var(--muted);margin:0}
.today .wd{color:var(--ink);font-weight:700;background:linear-gradient(transparent 58%,var(--mark) 58%,var(--mark) 92%,transparent 92%);padding:0 2px}
.sync{font-size:.78rem}
.icon-btn{border-radius:12px;border-color:var(--line);box-shadow:var(--shadow)}
.head-actions{gap:8px}
.pomo-btn{height:40px;min-width:40px;display:flex;align-items:center;justify-content:center;gap:6px;padding:0 11px;border:1px solid var(--line);background:var(--surface);border-radius:999px;color:var(--tomato);font:700 .9rem var(--display);font-variant-numeric:tabular-nums;box-shadow:var(--shadow)}
.pomo-btn span{color:var(--ink)}
.pomo-btn.m-short,.pomo-btn.m-long{color:var(--leaf)}
.pomo-btn.run{background:color-mix(in srgb,currentColor 12%,var(--surface));border-color:color-mix(in srgb,currentColor 45%,var(--line))}
.pomo-btn svg{width:20px;height:20px;flex:none}
html.sb-island #pomoBtnTime{display:none!important}html.sb-island .head-actions > .pomo-btn{width:40px;min-width:40px;padding:0;border-radius:50%;justify-content:center}   /* the time is in the Dynamic Island */
/* Navigation: floating dock on phones */
nav.tabs{left:10px;right:10px;bottom:calc(10px + env(safe-area-inset-bottom,0px));padding:6px;border:0;border-radius:20px;background:var(--spine);box-shadow:0 10px 30px rgba(8,20,50,.35)}
nav.tabs .in{grid-template-columns:none!important;grid-auto-flow:column;grid-auto-columns:1fr;max-width:760px;gap:1px}
nav.tabs .in button{color:var(--spine-ink);font:500 .66rem/1.1 var(--display)!important;padding:7px 1px 6px;border-radius:14px;gap:3px;width:100%}
nav.tabs .in button svg{width:22px;height:22px;flex:none}
nav.tabs .in button[aria-current="page"]{color:#fff;background:var(--spine-hi);font-weight:700}
nav.tabs .in button[aria-current="page"] svg{color:var(--accent-2)}
.nav-brand,.nav-pomo{display:none}
.fab{bottom:calc(92px + env(safe-area-inset-bottom,0px));right:16px;border-radius:16px;font:600 1rem var(--display);box-shadow:0 8px 22px color-mix(in srgb,var(--accent) 40%,transparent)}
.toast{bottom:calc(158px + env(safe-area-inset-bottom,0px));background:var(--navy);color:#fff;border-radius:12px;box-shadow:0 8px 24px rgba(8,20,50,.3)}
.toast button{color:var(--mark)}
@media (prefers-color-scheme:dark){:root:not([data-theme="light"]) .toast{background:#E7EEFA;color:#0A1428}:root:not([data-theme="light"]) .toast button{color:#1A5BC4}}
:root[data-theme="dark"] .toast{background:#E7EEFA;color:#0A1428}
:root[data-theme="dark"] .toast button{color:#1A5BC4}
@media (max-width:979px){
  .top-row > div:first-child{flex-direction:column;align-items:flex-start;gap:4px}
  .today{white-space:nowrap}
}
@media (max-width:600px){
  .sync[data-state="ok"]{display:none}
  .focus-head{flex-wrap:wrap}
}
