  .nav-pomo{display:flex;align-items:center;gap:8px;margin-top:auto;background:rgba(255,255,255,.06);border:1px solid rgba(255,255,255,.08);border-radius:16px;padding:10px 10px 10px 12px}
  nav.tabs .nav-pomo button{font:inherit;border-radius:0;gap:0}
  nav.tabs .nav-pomo .np-open{flex:1;min-width:0;border:0;background:none;color:#fff;text-align:left;display:grid;gap:1px;padding:0}
  .np-mode{display:flex;align-items:center;gap:6px;font:500 .78rem var(--display);color:var(--spine-ink)}
  .np-mode svg{color:var(--tomato);width:16px;height:16px}
  .nav-pomo.m-short .np-mode svg,.nav-pomo.m-long .np-mode svg{color:var(--leaf)}
  .np-time{font:700 1.55rem/1.1 var(--display);font-variant-numeric:tabular-nums;letter-spacing:-.01em;color:#fff}
  nav.tabs .nav-pomo .np-go{width:42px;height:42px;border-radius:50%;border:0;background:var(--tomato);color:#fff;display:grid;place-items:center;flex:none;padding:0}
  nav.tabs .nav-pomo.m-short .np-go,nav.tabs .nav-pomo.m-long .np-go{background:var(--leaf)}
