}
/* Type */
h2.sec,.col-head,.tl-controls h2,.view-head h2,.cal-head h2,.fcrumb,.sheet-head h2,.detail-head h2,.course-card h3,.deck-name,.focus-head h2,.empty strong,.lane-head{font-family:var(--display);letter-spacing:-.01em}
.view-head{display:flex;align-items:center;gap:10px;flex-wrap:wrap;margin-top:14px}
.view-head h2{flex:1;margin:0;font:700 1.45rem/1.2 var(--display)}
.tl-controls h2{font-size:1.45rem;line-height:1.2}   /* same line height as .view-head h2, so the scene themes' plate behind every page title is the same height */
/* Controls */
.btn{border-radius:11px;border-color:var(--line);font-weight:700;box-shadow:0 1px 0 rgba(14,42,86,.05)}
.btn:hover{border-color:color-mix(in srgb,var(--accent) 45%,var(--line))}
.btn.primary{background:var(--accent);border-color:var(--accent);color:var(--accent-ink)}
