.btn:disabled{opacity:.5;cursor:not-allowed}
input[type=text],input[type=search],input[type=date],input[type=time],input[type=number],input[type=url],input[type=email],input[type=password],select,textarea{background:var(--field);border-color:var(--line);border-radius:10px;color:var(--ink);width:100%;border-width:1px;border-style:solid;padding:10px 12px;font-size:16px}
input:focus-visible,select:focus-visible,textarea:focus-visible{outline:2px solid var(--accent);outline-offset:1px;border-color:var(--accent)}
.seg,.segb{background:var(--field);border-color:var(--line)}
.seg input:checked+span,.segb button[aria-pressed="true"]{background:var(--sel);color:var(--sel-ink);box-shadow:none}
.chip{border-color:var(--line);box-shadow:0 1px 0 rgba(14,42,86,.04)}
.chip[aria-pressed="true"]{background:var(--sel);color:var(--sel-ink);border-color:var(--sel)}
.req{color:var(--late);font-weight:700;margin-left:2px}
.req-note{margin:0;font-size:.8rem;color:var(--muted)}
dialog{border-radius:18px;background:var(--surface);color:var(--ink);box-shadow:0 24px 70px rgba(8,20,50,.35)}
dialog::backdrop{background:rgba(6,15,36,.55)}
#askDlg{width:min(420px,calc(100% - 32px));margin:auto}
#askDlg .sheet-foot{display:flex;gap:8px}
.sheet-head{border-bottom:1px solid var(--line);padding-bottom:12px}
.sheet-body{padding-top:14px}
/* Advanced settings drawer */
details.adv{min-width:0;max-width:100%;border:1px solid var(--line);border-radius:12px;background:color-mix(in srgb,var(--soft) 45%,transparent)}
details.adv > summary{list-style:none;cursor:pointer;display:flex;align-items:center;gap:10px;padding:12px 14px;border-radius:12px}
details.adv > summary::-webkit-details-marker{display:none}
details.adv > summary::before{content:"";width:8px;height:8px;border-right:2px solid var(--muted);border-bottom:2px solid var(--muted);transform:rotate(-45deg);transition:transform .15s;flex:none}
details.adv[open] > summary::before{transform:rotate(45deg)}
.adv-title{font:700 .95rem var(--display)}
.adv-sum{color:var(--muted);font-size:.84rem;flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;text-align:right}
.adv-body{display:grid;gap:14px;padding:4px 14px 16px}
.three{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px}
.focus-btn{display:inline-flex;align-items:center;gap:6px;color:var(--tomato)}
.focus-btn svg{width:16px;height:16px}
/* Lists: course color lives on the checkbox, not on a side bar */
li.task::before,.plan-row::before{display:none}
ul.tasks,.plan-list,.flist,.fc-list{box-shadow:var(--shadow);border-color:var(--line)}
.focus-go{width:32px;height:32px;border-radius:50%;border:1px solid var(--line);background:var(--surface);color:var(--tomato);display:grid;place-items:center;padding:0}
