.plan-fc{display:flex;align-items:center;gap:10px;margin-top:12px;padding:10px 12px;border-radius:12px;background:color-mix(in srgb,var(--accent) 8%,var(--surface));border:1px solid color-mix(in srgb,var(--accent) 25%,var(--line));font-size:.92rem}
.plan-fc svg{color:var(--accent);flex:none}
.plan-fc span{flex:1}
.focus{box-shadow:var(--shadow)}
.pomo-count{display:inline-flex;align-items:center;gap:3px;color:var(--tomato);font-weight:700}
.pomo-count svg{width:14px;height:14px}
/* Board: index cards with a folder tab in the course color */
.col{background:color-mix(in srgb,var(--surface) 55%,transparent);border:1px solid var(--line);border-radius:16px}
.col-head .n{background:var(--soft);border-radius:999px;padding:0 8px;font-weight:700;color:var(--muted)}
.col-list{gap:12px}
.card-grip{display:none}
@media (pointer:coarse){.board .card{padding-right:34px}.board .card-grip{display:grid;place-items:center;position:absolute;right:2px;top:50%;transform:translateY(-50%);width:30px;height:44px;border-radius:10px;color:var(--muted);opacity:.7;touch-action:none;-webkit-user-select:none;user-select:none;-webkit-touch-callout:none}.board .card-grip:active{background:var(--soft)}}
.card{border:1px solid var(--line);border-left:1px solid var(--line);background:var(--surface);border-radius:4px 12px 12px 12px;box-shadow:var(--shadow);padding:11px 12px 12px}
.card.has-tab{margin-top:17px}
