.course-card::before{content:attr(data-code);position:absolute;left:-1px;top:-18px;height:18px;padding:1px 10px 0;border-radius:8px 8px 0 0;background:color-mix(in srgb,var(--c) 66%,#000);color:#fff;font:700 .68rem/17px var(--display);letter-spacing:.03em}
.course-list{gap:26px;grid-template-columns:1fr;margin-top:20px}
