.deck-count{position:absolute;top:-11px;right:-9px;z-index:3;min-width:26px;height:26px;padding:0 8px;box-sizing:border-box;display:inline-grid;place-items:center;border-radius:999px;background:var(--c);color:#fff;font:700 .82rem/1 var(--display);box-shadow:0 2px 6px rgba(0,0,0,.3);border:2px solid var(--surface);font-variant-numeric:tabular-nums}
.deck-fc .deck-face .deck-main,.deck-fc .deck-face .deck-actions{position:relative;z-index:1}   /* above the style's shimmer or texture layer */
