.deck-fc .deck-face .deck-arch:hover{opacity:1}
.deck-fc .deck-face .btn:not(.primary):not(.deck-arch){color:var(--ink)}
.deck-fc > .deck-tab{left:0;z-index:2}   /* on the article, not inside the card, so it lines up with the card's outer edge whatever the card's border is */
.deck-fc.cs-neon .deck-face .btn:not(.primary):not(.deck-arch),.deck-fc.cs-chalk .deck-face .btn:not(.primary):not(.deck-arch),.deck-fc.cs-blueprint .deck-face .btn:not(.primary):not(.deck-arch){background:rgba(255,255,255,.14);border-color:rgba(255,255,255,.4);color:inherit}
.deck-fc.cs-ticket .deck-main,.deck-fc.cs-ticket .deck-actions{padding-left:36px;padding-right:36px}
.deck-fc.cs-polaroid .deck-main{padding-top:8px}
.deck-actions .deck-arch{margin-left:auto;background:none;border-color:transparent;color:var(--muted)}
.deck-actions .deck-arch:hover{color:var(--ink);border-color:var(--line)}
.deck-archived{margin-top:28px}
.sheet .deck-archived{margin-top:0}
.deck-archived summary{cursor:pointer;min-height:44px;display:flex;align-items:center;gap:8px;font:700 .95rem var(--display);color:var(--muted)}
.deck-archived ul{list-style:none;margin:0;padding:0;background:var(--surface);border:1px solid var(--line);border-radius:14px;overflow:hidden}
.deck-archived li{display:flex;align-items:center;gap:10px;padding:8px 8px 8px 14px;border-top:1px solid var(--line)}
.deck-archived li:first-child{border-top:0}
.da-name{flex:1;min-width:0;display:grid;gap:1px}
.da-name b{overflow-wrap:anywhere}
.deck-grid + .hint-line{margin-top:30px}
.rate + .hint-line{text-align:center}
.deck-head{position:relative;background:var(--surface);border:1px solid var(--line);border-radius:4px 16px 16px 16px;box-shadow:var(--shadow);padding:18px;margin-top:26px}
.deck-head h2{margin:0 0 6px;font:700 1.6rem/1.2 var(--display)}
.deck-stats{display:flex;flex-wrap:wrap;gap:6px 18px;color:var(--muted);font-size:.92rem;margin-bottom:10px}
