.fc-add textarea{min-height:64px}
.fc-list{list-style:none;margin:14px 0 0;padding:0;background:var(--surface);border:1px solid var(--line);border-radius:14px;overflow:hidden}
.fc-row{display:flex;align-items:center;gap:12px;border-top:1px solid var(--line);padding-right:14px}
