.face{position:absolute;inset:0;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:10px;padding:34px 28px 26px;border-radius:6px;backface-visibility:hidden;-webkit-backface-visibility:hidden;border:1px solid var(--line);box-shadow:0 12px 30px rgba(14,42,86,.14);color:#15213A;
  background-color:#FFFEF9;background-image:linear-gradient(to bottom,transparent 38px,rgba(214,57,44,.55) 38px,rgba(214,57,44,.55) 40px,transparent 40px),repeating-linear-gradient(to bottom,transparent 0 27px,rgba(57,136,254,.18) 27px 28px);background-size:100% 100%,100% calc(100% - 40px);background-position:0 0,0 40px;background-repeat:no-repeat,no-repeat}
.face.back{transform:rotateY(180deg)}
