.pp-sess.is-done .pp-check{background:var(--leaf);border-color:var(--leaf)}
.pp-today{display:grid;gap:6px;margin:8px 0}
.pp-today-row{display:flex;align-items:center;gap:10px;flex-wrap:wrap;padding:8px 12px;border:1px solid var(--line);border-radius:12px;background:var(--surface)}
.pp-today-t{flex:1 1 220px}
.pp-today-a{display:inline-flex;align-items:center;gap:4px}
.pp-form{display:flex;align-items:center;gap:10px;flex-wrap:wrap;padding:8px 12px;border:1px solid var(--line);border-radius:12px;background:var(--field)}
.pp-form>div{flex:1 1 200px;display:grid;gap:4px}
.pp-exams{list-style:none;margin:0 0 8px;padding:0;display:grid;gap:6px}
.pp-exams li{display:flex;align-items:center;gap:8px;flex-wrap:wrap;border:1px solid var(--line);border-radius:12px;padding:8px 12px;background:var(--surface)}
.pp-ex-main{display:grid;text-align:left;flex:1 1 180px;background:none;border:0;padding:0;color:inherit;font:inherit;cursor:pointer}
/* Same look and spot as Break It Down: centred in the row, before the open-in-school-site link */
li.task .pp-row-btn{flex:none;align-self:center;margin:0 10px 0 0;min-height:40px;padding:0 14px;border:1px solid var(--line);border-radius:999px;background:var(--surface);color:var(--accent);font:600 .8rem var(--body,inherit);cursor:pointer;white-space:nowrap}
li.task .pp-row-btn:last-child{margin-right:12px}
@media (max-width:600px){li.task .pp-row-btn{margin-right:6px;padding:0 8px;font-size:.76rem}}
.pp-open{white-space:nowrap}
/* summaries */
.sum-list{margin:0;padding-left:20px;display:grid;gap:4px}
.sum-terms{display:grid;grid-template-columns:minmax(100px,auto) 1fr;gap:4px 12px;margin:0}
.sum-terms dt{font-weight:700}
.sum-terms dd{margin:0}
@media (max-width:560px){.sum-terms{grid-template-columns:1fr}.sum-terms dd{margin-bottom:6px}}
/* ask */
.ask .sheet-body{min-height:40vh}
.ask-src{border:1px solid var(--line);border-radius:12px;padding:8px 12px;background:var(--field)}
.ask-src summary{font-weight:700;cursor:pointer}
.ask-log{display:grid;gap:8px}
.ask-q{justify-self:end;max-width:85%;background:var(--accent);color:var(--accent-ink);border-radius:14px 14px 4px 14px;padding:8px 12px;white-space:pre-wrap}
.ask-a{justify-self:start;max-width:92%;background:var(--surface);border:1px solid var(--line);border-radius:14px 14px 14px 4px;padding:6px 12px}
.ask-a p{margin:6px 0}.ask-a ul{margin:6px 0;padding-left:20px}
.ask-cites,.ask-acts{display:flex;flex-wrap:wrap;gap:6px;margin:6px 0;align-items:center}
.ask-cites .chip{font-size:.78rem;padding:3px 8px}
.ask-fu{cursor:pointer;font-size:.84rem;text-align:left}
.ask-empty{display:flex;flex-wrap:wrap;gap:6px}
.ask-empty p{flex-basis:100%;margin:0}
.ask-foot{align-items:flex-end}
.ask-foot textarea{flex:1;min-height:0;resize:none;max-height:9em;overflow-y:auto;line-height:1.35}
.ask-foot .btn{align-self:flex-end}
.note-body{max-height:480px;overflow:hidden;white-space:pre-wrap}
/* Notes never scroll: a long note grows to 480px, then fades out with a Show More button; the edit box grows with its text. */
.note.nb-clip:not(.nb-open) .note-body{-webkit-mask-image:linear-gradient(#000 78%,transparent);mask-image:linear-gradient(#000 78%,transparent)}
.note.nb-open .note-body{max-height:none}
.note-more{display:flex;align-items:center;justify-content:center;gap:4px;width:100%;margin:6px 0 0;padding:6px 8px;border:0;border-radius:8px;background:rgba(255,255,255,.5);color:#2A2418;font:700 .78rem var(--body);cursor:pointer}
.note-more:hover{background:rgba(255,255,255,.7)}
.note-more svg{width:14px;height:14px;transition:transform .2s}
.note.nb-open .note-more svg{transform:rotate(180deg)}
.note-text{resize:none!important;overflow:hidden!important;scrollbar-width:none}
.note-moredd{margin:6px 0 0}
.note-moredd>summary{display:inline-flex;align-items:center;gap:4px;list-style:none;cursor:pointer;user-select:none}
.note-moredd>summary::-webkit-details-marker{display:none}
.note-moredd>summary svg{transition:transform .2s}
.note-moredd[open]>summary svg{transform:rotate(180deg)}
.note-xbtns{display:flex;flex-wrap:wrap;gap:6px;margin-top:6px}
.note-text::-webkit-scrollbar{display:none}
.qa-item>*{width:auto!important}
.qa-item input[type=text]{flex:1 1 220px!important}
.qa-item select{max-width:150px}
@media (max-width:600px){.qa-item input[type=text]{flex-basis:100%!important}.qa-item select,.qa-item input[type=date]{flex:1 1 40%}}
.nu-title .tag{font:700 .72rem var(--body);letter-spacing:.04em;color:var(--muted);margin-left:8px;vertical-align:2px}


/* ---- Today's Plan: one calm card ---- */
.plan{padding:16px 18px}
.plan .focus-head{display:flex;align-items:center;gap:8px 14px;flex-wrap:wrap}
.plan .fh-txt{flex:1 1 220px;min-width:0}
.plan .fh-ctl{display:flex;align-items:center;gap:6px 8px;flex-wrap:wrap;margin-left:auto}
.plan .hours-ctl{display:flex;align-items:center;gap:0;background:transparent;border:1px solid var(--line);border-radius:999px;padding:2px 3px 2px 12px;min-height:36px}
.plan .hours-ctl .mini{margin-right:4px;font-size:.78rem;color:var(--muted);white-space:nowrap}
.plan .hours-ctl b{min-width:36px;font-size:.92rem}
.plan .hours-ctl .icon-btn.sm{width:30px;height:30px;border-radius:50%;border:0;background:transparent;color:var(--ink);box-shadow:none}
.plan .hours-ctl .icon-btn.sm:hover{background:var(--soft)}
.plan .btn.small.fh-hide{background:transparent;border-color:transparent;box-shadow:none;color:var(--muted);min-height:36px}
.plan .btn.small.fh-hide:hover{background:var(--soft);color:var(--ink)}
/* Do This Next */
.next-up{margin:14px 0 2px;padding:12px 14px 12px 14px;border-radius:14px;background:color-mix(in srgb,var(--c) 7%,var(--surface));border:1px solid color-mix(in srgb,var(--c) 22%,var(--line));box-shadow:inset 3px 0 0 var(--c)}
.nu-top{display:flex;align-items:center;gap:8px;margin:0 0 6px 36px}
.nu-nochk .nu-top{margin-left:0}
.nu-label{flex:1;min-width:0;font:700 .72rem var(--display);letter-spacing:.08em;text-transform:uppercase;color:var(--muted)}
.nu-alloc{flex:none;font-size:.8rem;font-weight:600;color:var(--muted);font-variant-numeric:tabular-nums}
.nu-row{display:flex;align-items:center;gap:10px 12px;flex-wrap:wrap}
.nu-row>.check{margin:0;align-self:flex-start;margin-top:1px}
.nu-body{flex:1 1 260px;min-width:0;display:grid;gap:3px}
.nu-title{border:0;background:none;padding:0;text-align:left;font:700 1.08rem var(--display);color:var(--ink);cursor:pointer}
.nu-title:hover{text-decoration:underline;text-decoration-thickness:1px;text-underline-offset:3px}
.nu-why{font-size:.86rem;color:var(--muted)}
.nu-step{font-size:.86rem;font-weight:600}
.nu-acts{display:flex;gap:6px;flex-wrap:wrap;margin-left:auto}
.nu-acts svg{width:16px;height:16px;margin-right:4px;vertical-align:-3px}
.nu-acts .btn.primary svg{color:var(--tomato);filter:drop-shadow(0 0 1px #fff)}   /* the tomato stays red whatever the button text color is */
/* the rest of today */
.plan-sub{margin:16px 0 0;font:700 .72rem var(--display);letter-spacing:.08em;text-transform:uppercase;color:var(--muted)}
.plan .plan-list{list-style:none;margin:4px 0 0;padding:0;background:transparent;border:0;border-radius:0;box-shadow:none;overflow:visible}
.plan-row{display:grid;grid-template-columns:26px minmax(0,1fr) auto auto;grid-template-areas:"chk main why side" ". slot slot slot" ". more more more";align-items:center;column-gap:12px;padding:6px 0 6px 2px;border-top:1px solid color-mix(in srgb,var(--line) 70%,transparent);position:relative}
.plan .plan-list>.plan-row:first-child{border-top:0}
.plan-row::before{display:none}
.plan-row>.check{grid-area:chk;margin:0;width:24px;height:24px}
.plan-row>.check svg{width:13px;height:13px}
.plan-main{grid-area:main;display:flex;align-items:center;gap:8px;min-width:0;padding:6px 0;border:0;background:none;text-align:left;color:var(--ink);font:inherit;cursor:pointer}
.plan-main .task-title{font-weight:600;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.plan-main:hover .task-title{text-decoration:underline;text-decoration-thickness:1px;text-underline-offset:3px}
.pr-chip{flex:none;display:inline-flex;align-items:center;gap:5px;font:700 .68rem/1 var(--body);letter-spacing:.03em;color:color-mix(in srgb,var(--c) 55%,var(--ink));background:color-mix(in srgb,var(--c) 13%,transparent);border:0;border-radius:999px;padding:3px 8px 3px 7px;white-space:nowrap;font-variant-numeric:normal}
.pr-chip::before{content:"";width:6px;height:6px;border-radius:50%;background:var(--c);flex:none}
.pr-chip.gt-chip::before{display:none}
.pr-why{grid-area:why;justify-self:end;display:inline-flex;align-items:center;gap:6px;max-width:21em;min-width:0;border:0;background:none;padding:4px 6px;border-radius:8px;font-size:.82rem;color:var(--muted);text-align:right}
button.pr-why{cursor:pointer}
button.pr-why:hover{background:var(--soft);color:var(--ink)}
.pr-why.late{color:var(--late)}
.pr-lead{min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.pr-n{flex:none;font-size:.7rem;font-weight:700;color:var(--muted);border:1px solid var(--line);border-radius:999px;padding:0 6px;line-height:1.55}
.why-open .pr-n{background:var(--soft);color:var(--ink)}
.plan-row>.plan-side{grid-area:side;display:flex;align-items:center;justify-content:flex-end;gap:2px;margin:0;flex:none}
.plan-row .alloc,.plan-row .score{margin:0;min-width:42px;text-align:right;padding:0;background:none;border-radius:0;color:var(--ink);font-weight:600;font-size:.85rem;font-variant-numeric:tabular-nums}
.plan-row .alloc.idle{color:var(--muted);font-weight:500}
.plan-gap{margin:4px 0 0;font-size:.85rem;line-height:1.4;color:var(--muted);max-width:60ch}
.plan-rows{margin:6px 0 0}
.plan-row .score{color:var(--muted)}
.plan-row .focus-go{width:30px;height:30px;border:1px solid transparent;background:transparent}
.plan-row .focus-go svg{width:16px;height:16px}
.plan-row .focus-go:hover,.plan-row .focus-go:focus-visible{border-color:color-mix(in srgb,var(--tomato) 50%,var(--line));background:color-mix(in srgb,var(--tomato) 8%,var(--surface))}
@media (hover:hover) and (pointer:fine){
  .plan-row .focus-go{opacity:0;transition:opacity .12s}
  .plan-row:hover .focus-go,.plan-row:focus-within .focus-go{opacity:1}
}
.pr-more{grid-area:more;list-style:none;margin:0 0 8px;padding:8px 12px;display:grid;gap:4px;font-size:.84rem;color:var(--muted);background:color-mix(in srgb,var(--soft) 70%,transparent);border-radius:10px}
.pr-more li{display:flex;align-items:baseline;gap:8px}
.pr-more li::before{content:"";flex:none;width:5px;height:5px;border-radius:50%;background:var(--c);transform:translateY(-2px)}
/* footer: Full Ranking and How This Is Ranked */
.plan-foot{display:flex;flex-wrap:wrap;gap:2px 18px;margin-top:8px;padding-top:6px;border-top:1px solid color-mix(in srgb,var(--line) 70%,transparent)}
.pf-link{display:inline-flex;align-items:center;gap:4px;border:0;background:none;padding:6px 0;font-size:.84rem;font-weight:600;color:var(--muted);cursor:pointer}
.pf-link:hover,.pf-link[aria-expanded=true]{color:var(--ink)}
.pf-chev{width:14px;height:14px;transition:transform .15s}
.pf-link[aria-expanded=true] .pf-chev{transform:rotate(180deg)}
.plan-more,.plan-how{margin-top:4px}
.plan-more .fsec{margin-top:14px}
.plan-cap{margin:6px 0 0;font-size:.82rem;color:var(--muted)}
.plan-how p:first-child{margin-top:4px}
@media (max-width:600px){
  .plan{padding:14px}
  .plan .fh-ctl{margin-left:0;width:100%}
  .plan .fh-hide{margin-left:auto}
  .nu-top{margin-left:38px}
  .nu-body{flex-basis:150px}
  .nu-row>.lms-go{align-self:flex-start}
  .nu-acts{flex-basis:100%;margin-left:0;padding-left:38px}
  .nu-nochk .nu-top{margin-left:0}
  .nu-nochk .nu-acts{padding-left:0}
  .plan-row{grid-template-columns:26px minmax(0,1fr) auto;grid-template-areas:"chk main side" "chk why side" ". slot slot" ". more more";column-gap:12px;padding:8px 0}
  .plan-row>.check{align-self:start;width:26px;height:26px;margin-top:2px}
  .plan-main{flex-wrap:wrap;gap:4px 8px;padding:3px 0 1px}
  .plan-main .task-title{white-space:normal;overflow-wrap:anywhere}
  .pr-why{justify-self:start;max-width:100%;padding:2px 0;text-align:left}
  button.pr-why:hover{background:none}
  .plan-row .focus-go{opacity:1;width:32px;height:32px;border-color:var(--line)}
}
/* automatic AI, phone board tabs */
.ai-chip{border:1px solid color-mix(in srgb,#8B5CF6 35%,var(--line));background:color-mix(in srgb,#8B5CF6 8%,var(--surface));color:var(--ink);border-radius:999px;padding:5px 10px;font-size:.78rem;font-weight:600;display:inline-flex;align-items:center;gap:5px;white-space:nowrap}
.ai-chip.paused{border-color:color-mix(in srgb,var(--warn) 50%,var(--line));background:color-mix(in srgb,var(--warn) 10%,var(--surface))}
.ai-chip .ai-ic{width:14px;height:14px}
.nu-label .ai-ic{width:13px;height:13px;vertical-align:-2px}
.ai-auto{display:grid;gap:8px}
/* Today's Plan / Task Board switch, on every screen size */
.plan-extra{margin-top:12px;border:1px solid var(--line);border-radius:12px;background:var(--surface)}
.plan-extra>summary{cursor:pointer;display:flex;align-items:baseline;gap:10px;flex-wrap:wrap;padding:10px 14px;list-style:none}
.plan-extra>summary::-webkit-details-marker{display:none}
.plan-extra>summary::after{content:"";margin-left:auto;width:8px;height:8px;border-right:2px solid var(--muted);border-bottom:2px solid var(--muted);transform:rotate(45deg);align-self:center;transition:transform .15s}
.plan-extra[open]>summary::after{transform:rotate(-135deg)}
.plan-extra .pe-t{font:700 .95rem var(--display)}
.plan-extra .pe-s{font-size:.82rem;color:var(--muted)}
.plan-extra .pe-b{display:grid;gap:12px;padding:0 12px 12px}
.plan-extra .pe-item{border:1px solid var(--line);border-radius:10px;background:var(--surface)}
.plan-extra .pe-item>summary{cursor:pointer;list-style:none;display:flex;align-items:center;gap:8px;padding:8px 12px;font:600 .9rem var(--display)}
.plan-extra .pe-item>summary::-webkit-details-marker{display:none}
.plan-extra .pe-item>summary::after{content:"";margin-left:auto;width:7px;height:7px;border-right:2px solid var(--muted);border-bottom:2px solid var(--muted);transform:rotate(45deg);transition:transform .15s}
.plan-extra .pe-item[open]>summary::after{transform:rotate(-135deg)}
.pe-dot{flex:none;display:inline-grid;place-items:center;min-width:19px;height:19px;padding:0 5px;box-sizing:border-box;border-radius:10px;background:var(--late,#C0392B);color:#fff;font:700 .68rem/1 var(--body);font-style:normal;margin-left:2px}
.plan-extra .pe-item>:not(summary){margin:0 8px 8px}
.bview-row{display:flex;align-items:center;gap:10px 16px;flex-wrap:wrap;margin:0 0 12px}
.bview-row>.bview-tabs{margin:0;flex:1 1 280px}
.bview-row>.board-ctl{margin:0 0 0 auto}
.bview-tabs{display:flex;gap:4px;padding:4px;margin:0 0 12px;background:var(--soft);border:1px solid var(--line);border-radius:14px;max-width:460px}
.bview-tabs button{flex:1;border:0;background:transparent;border-radius:10px;padding:10px 8px;font:700 .95rem var(--display);color:var(--muted);display:flex;align-items:center;justify-content:center;gap:6px}
.bview-tabs button[aria-selected=true]{background:var(--surface);color:var(--ink);box-shadow:var(--shadow)}
.bview-tabs .n{font:600 .75rem var(--body);background:var(--soft);border-radius:8px;padding:1px 6px}
.bview[data-bview=plan] .bpane-board,.bview[data-bview=board] .bpane-plan{display:none}
.bview[data-bview=board] .board-sec{margin-top:0;padding-top:0;border-top:0}
.bview[data-bview=board] .board-sec::before{display:none}
.bview[data-bview=board] .board-sec-head,.bview[data-bview=plan] .focus-head h2{display:none}
/* Calendar's Timeline / Schedule switch: the same look as the phone's Today's Plan / Task Board switch, on every screen size */
.pview-tabs{display:flex;gap:4px;padding:4px;margin:0 0 12px;background:var(--soft);border:1px solid var(--line);border-radius:14px;max-width:420px}
.pview-tabs button{flex:1;border:0;background:transparent;border-radius:10px;padding:10px 8px;font:700 .95rem var(--display);color:var(--muted);display:flex;align-items:center;justify-content:center;gap:6px;cursor:pointer}
.pview-tabs button[aria-selected=true]{background:var(--surface);color:var(--ink);box-shadow:var(--shadow)}
.pview-tabs.cf-tabs{box-sizing:border-box;width:min(420px,100%);max-width:420px;align-self:flex-start;margin-left:0;margin-right:auto}
.pview-tabs.cf-tabs button{flex:1 1 0;min-width:0}
@media (max-width:979px){.pview-tabs{max-width:none}}
/* App tour (coach marks) and the bug report form */
.tour{position:fixed;inset:0;z-index:9000}
dialog.tour{width:100%;height:100%;max-width:none;max-height:none;margin:0;padding:0;border:0;border-radius:0;background:transparent;box-shadow:none;overflow:visible;color:inherit}
dialog.tour::backdrop{background:transparent}
.tour [hidden]{display:none!important}
.tour-block{position:absolute;inset:0}
.tour-spot{position:absolute;border-radius:14px;box-shadow:0 0 0 9999px rgba(8,14,30,.64),0 0 0 3px var(--accent-2,var(--accent));transition:left .25s,top .25s,width .25s,height .25s;pointer-events:none}
.tour.center .tour-spot{left:50%;top:50%;width:0;height:0;box-shadow:0 0 0 9999px rgba(8,14,30,.64)}
