.tour-card h2{margin:0;font:700 1.1rem var(--display)}
.tour-card p{margin:0;font-size:.92rem;line-height:1.45}
.tour-more{margin-top:8px}
.tour-more > .link-btn{font-size:.88rem;font-weight:700;color:var(--accent);padding:2px 0}
.tour-more-body{margin-top:6px;padding:10px 12px;border-radius:12px;background:var(--soft);max-height:min(260px,40vh);overflow:auto;font-size:.86rem;line-height:1.45}
.tour-more-body ol{margin:0 0 6px;padding-left:20px;display:grid;gap:4px}
.tour-more-body p{font-size:.84rem;color:var(--muted)}
.pomo-how-b{padding:4px 2px 2px;font-size:.9rem;line-height:1.5}
.pomo-how-b ol{margin:0 0 8px;padding-left:20px;display:grid;gap:5px}
.pomo-how-b p{margin:0;color:var(--muted);font-size:.86rem}
.tour-step{color:var(--muted);font-weight:600;text-transform:uppercase;letter-spacing:.04em}
.tour-top{display:flex;align-items:center;justify-content:space-between;gap:8px}
.tour-ex{flex:none;padding:2px 9px;border-radius:999px;border:1px solid color-mix(in srgb,var(--accent) 45%,var(--line));background:color-mix(in srgb,var(--accent) 12%,transparent);color:var(--ink);font:700 .7rem/1.5 var(--display);letter-spacing:.03em}
.tour-ex[hidden]{display:none}
.tour-dots{display:flex;gap:6px;justify-content:center;flex-wrap:wrap;margin:2px 0 0}
.tour-dots span{width:7px;height:7px;border-radius:4px;background:var(--line);transition:width .2s,background .2s}
