.bug-shot{display:grid;gap:6px;justify-items:start}
.bug-diag summary{cursor:pointer;font-size:.85rem;color:var(--muted)}


/* ===== Style Shop v2 ===== */
body{background-image:var(--bgimg,linear-gradient(var(--grid) 1px,transparent 1px),linear-gradient(90deg,var(--grid) 1px,transparent 1px));background-size:var(--bgsize,24px 24px);background-position:var(--bgpos,0 0);background-attachment:var(--bgatt,scroll)}
.motion-tog,.anim-tog{display:inline-flex;align-items:center;gap:6px;cursor:pointer;font-weight:600}
.kit-row{display:flex;align-items:center;justify-content:space-between;gap:10px;padding:10px 12px;border:1px dashed var(--line);border-radius:12px;margin:8px 0}
/* theme flashcards and shapes */
.cs-theme .face{background:var(--tc-bg,#fff);color:var(--tc-ink,#15213A);border:2px solid var(--tc-bd,var(--line));border-radius:var(--tc-r,14px)}
.cs-theme .face-label{color:var(--tc-mc,var(--accent))}
:root[data-skin] .btn.primary{border-radius:var(--btn-r,11px)}
:root[data-skin] .fab{border-radius:var(--fab-r,16px)}

.motion-tog{display:inline-flex;align-items:center;gap:6px;margin-left:auto;font-size:.9rem;cursor:pointer}
.sp-art{position:absolute;inset:0 0 0 18px;z-index:0;overflow:hidden;pointer-events:none}
.skin-prev .sp-main{position:relative;z-index:1}
body::after{content:"";position:fixed;left:0;right:0;bottom:0;height:var(--scene-h,0px);background:var(--scene,none) center bottom/100% 100% no-repeat;pointer-events:none;z-index:-1}
nav.tabs{background:var(--spine-bg,var(--spine))}
body.desk::before{background:var(--spine-bg,var(--spine))}
/* A wide window: the sidebar runs to the very top, and the strip for the window buttons is the page itself, frosted, instead of a dark band
   (its buttons take the page's colour too, see deskTint). On a Mac the sidebar leaves room for the traffic lights. */
@media (min-width:980px){
  body.desk nav.tabs{top:0}
  body.desk.mac nav.tabs{padding-top:calc(var(--tb) + 8px)}
  html body.desk::before{z-index:5;background:color-mix(in srgb,var(--paper,var(--bg)) 88%,transparent);-webkit-backdrop-filter:blur(14px) saturate(1.15);backdrop-filter:blur(14px) saturate(1.15)}
}
.btn.primary,.fab{background:var(--btn-bg,var(--accent))}
.btn.primary{border-color:transparent}
/* No stray line of the wrong colour beside or under a themed button: a gradient or picture fill is drawn across the whole box (not repeated
   into the border edge), and the thin shadow under plain buttons is not drawn under coloured ones */
.btn.primary,.fab{background-origin:border-box !important;background-clip:border-box !important}
.btn.primary{box-shadow:none}
:root[data-skin] .btn.primary:hover,:root[data-skin] .fab:hover{background:var(--btn-bg,color-mix(in srgb,var(--accent) 88%,#000));filter:brightness(.95)}
/* flashcard styles */
.cs-plain .face{background:#fff;background-image:none;border-radius:22px;border-color:#E3E8F0}
.cs-grid .face{background-color:#FDFEFF;background-image:linear-gradient(rgba(57,136,254,.17) 1px,transparent 1px),linear-gradient(90deg,rgba(57,136,254,.17) 1px,transparent 1px);background-size:20px 20px;background-position:0 0;background-repeat:repeat}
.cs-kraft .face{background-color:#D8B98C;background-image:radial-gradient(rgba(90,60,30,.2) 1px,transparent 1.5px),radial-gradient(rgba(255,240,210,.28) 1px,transparent 1.5px);background-size:7px 7px,11px 11px;background-position:0 0,3px 5px;background-repeat:repeat;color:#3B2A18;border-color:#B8966A;border-radius:4px}
.cs-kraft .face-label,.cs-kraft .face-hint{color:rgba(59,42,24,.62)}
.cs-chalk .face{background:#2F4F3E radial-gradient(rgba(255,255,255,.07),transparent 70%);color:#F4F1E8;border:10px solid #8A5A2B;border-radius:6px;box-shadow:inset 0 0 30px rgba(0,0,0,.35),0 12px 30px rgba(0,0,0,.25)}
.cs-chalk .face-label,.cs-chalk .face-hint{color:rgba(244,241,232,.62)}
.cs-chalk .face-text{text-shadow:0 0 1.5px rgba(255,255,255,.55);letter-spacing:.02em}
.cs-neon .face{background:#120B26;background-image:none;color:#fff;border:2px solid #FF2FB3;border-radius:14px;box-shadow:0 0 16px rgba(255,47,179,.55),inset 0 0 18px rgba(40,230,255,.25)}
.cs-neon .face-text{text-shadow:0 0 8px rgba(40,230,255,.85)}
.cs-neon .face-label,.cs-neon .face-hint{color:#7CF3FF}
.cs-polaroid .face{background:#F2EFE7;background-image:none;border:14px solid #fff;border-bottom-width:50px;border-radius:3px;box-shadow:0 12px 30px rgba(14,42,86,.2);color:#2A2A2A}
.cs-polaroid .face-hint{bottom:-36px;color:#6B6B6B;font-style:italic}
.cs-ticket .face{background-color:#FFF1D6;background-image:linear-gradient(90deg,transparent 30px,rgba(214,120,40,.45) 30px 32px,transparent 32px calc(100% - 32px),rgba(214,120,40,.45) calc(100% - 32px) calc(100% - 30px),transparent 0);border:0;border-radius:10px;color:#5A2E0E;-webkit-mask:radial-gradient(circle 16px at 0 50%,#0000 98%,#000) left/51% 100% no-repeat,radial-gradient(circle 16px at 100% 50%,#0000 98%,#000) right/51% 100% no-repeat;mask:radial-gradient(circle 16px at 0 50%,#0000 98%,#000) left/51% 100% no-repeat,radial-gradient(circle 16px at 100% 50%,#0000 98%,#000) right/51% 100% no-repeat;padding-left:44px;padding-right:44px}
.cs-ticket .face-label{left:44px;color:rgba(90,46,14,.6)}
.cs-pastel .face{background:linear-gradient(135deg,#FFD6E8,#E2D6FF 50%,#CFF3FF);border:0;border-radius:28px;color:#3A2A55}
.cs-holo .face{background:linear-gradient(115deg,#FFD6F5,#D6ECFF 20%,#D6FFE9 40%,#FFF6D0 60%,#EAD6FF 80%,#FFD6F5);background-size:300% 300%;animation:holo 7s ease-in-out infinite alternate;border:1px solid rgba(255,255,255,.9);border-radius:16px;color:#2A2240;box-shadow:0 12px 30px rgba(120,80,200,.22),inset 0 0 0 1px rgba(255,255,255,.6)}
.cs-holo .face::after{content:"";position:absolute;inset:0;border-radius:inherit;background:linear-gradient(120deg,transparent 30%,rgba(255,255,255,.55) 45%,transparent 60%);background-size:250% 100%;animation:holo 5s linear infinite;pointer-events:none}
@keyframes holo{from{background-position:0% 50%}to{background-position:100% 50%}}
@media (prefers-reduced-motion:reduce){.cs-holo .face,.cs-holo .face::after{animation:none}}
.cs-blueprint .face{background-color:#1D4E9E;background-image:linear-gradient(rgba(255,255,255,.14) 1px,transparent 1px),linear-gradient(90deg,rgba(255,255,255,.14) 1px,transparent 1px),linear-gradient(rgba(255,255,255,.06) 1px,transparent 1px),linear-gradient(90deg,rgba(255,255,255,.06) 1px,transparent 1px);background-size:50px 50px,50px 50px,10px 10px,10px 10px;background-position:0 0;background-repeat:repeat;color:#fff;border:2px solid rgba(255,255,255,.7);outline:1px dashed rgba(255,255,255,.5);outline-offset:-10px;border-radius:4px;font-family:ui-monospace,Menlo,Consolas,monospace}
.cs-blueprint .face-label,.cs-blueprint .face-hint{color:rgba(255,255,255,.72)}
.cs-parchment .face{background:radial-gradient(ellipse at center,#FBF1D8 40%,#EBD3A0 80%,#C9A060 100%);border:0;border-radius:6px;color:#4A3520;box-shadow:0 12px 30px rgba(90,60,20,.25),inset 0 0 40px rgba(140,90,30,.35)}
.cs-parchment .face-text{font-family:Georgia,"Times New Roman",serif}
.cs-parchment .face-label,.cs-parchment .face-hint{color:rgba(74,53,32,.6)}
