.note.ns-folded{background:linear-gradient(315deg,transparent 22px,var(--nc) 22px);border-radius:3px}
.note.ns-folded::after{content:"";position:absolute;right:0;bottom:0;width:31px;height:31px;background:linear-gradient(315deg,transparent 50%,color-mix(in srgb,var(--nc) 70%,#6b4a1a) 50%);border-radius:0 0 0 6px;box-shadow:-2px -2px 4px rgba(0,0,0,.1)}
.note.ns-lined{background-color:var(--nc);background-image:linear-gradient(90deg,transparent 22px,rgba(214,57,44,.45) 22px 23.5px,transparent 23.5px),repeating-linear-gradient(transparent 0 21px,rgba(57,100,180,.25) 21px 22px);background-position:0 0,0 25px;padding-left:30px;line-height:22px;border-radius:2px}
.note.ns-gridnote{background-color:var(--nc);background-image:linear-gradient(rgba(57,100,180,.2) 1px,transparent 1px),linear-gradient(90deg,rgba(57,100,180,.2) 1px,transparent 1px);background-size:14px 14px;border-radius:2px}
.note.ns-speech{border-radius:22px}
.note.ns-speech::after{content:"";position:absolute;left:30px;bottom:-16px;border-top:18px solid var(--nc);border-right:20px solid transparent}
.note.ns-circle{border-radius:50%;aspect-ratio:1;min-height:0;padding:44px 28px 28px;text-align:center;overflow:visible}
.note.editing.ns-circle{border-radius:18px;aspect-ratio:auto;text-align:left;padding:26px 14px 14px}
.note.editing.ns-torn,.note.editing.ns-cloud,.note.editing.ns-heart,.note.editing.ns-scallop{background:var(--nc);filter:none;box-shadow:0 18px 40px rgba(40,25,5,.4);padding:26px 14px 14px;text-align:left}
.note.editing.ns-torn::before,.note.editing.ns-cloud::before,.note.editing.ns-heart::before,.note.editing.ns-scallop::before{display:none}
