.note.ns-circle .pin.pk-corners,.note.ns-heart .pin.pk-corners,.note.ns-cloud .pin.pk-corners{bottom:0;height:auto}
.note.ns-circle .pin.pk-corners::before{left:-2%;top:11%}.note.ns-circle .pin.pk-corners::after{right:-2%;top:11%}
.note.ns-heart .pin.pk-corners::before{left:-6%;top:1%}.note.ns-heart .pin.pk-corners::after{right:-6%;top:1%}
.note.ns-cloud .pin.pk-corners::before{left:1%;top:14%}.note.ns-cloud .pin.pk-corners::after{right:-1%;top:9%}
.note.ns-circle .pin.pkk-clip{left:calc(33% - 10px);top:-10px}
.note.ns-speech .pin.pk-corners::before{left:-12px;top:2px}.note.ns-speech .pin.pk-corners::after{right:-12px;top:2px}
.pin svg{display:block;width:100%;height:100%}
/* stickers on notes */
.stk{position:absolute;width:48px;height:48px;transform:translate(-50%,-50%) rotate(var(--r,0deg)) scale(var(--s,1));z-index:3}
.stk > svg{width:100%;height:100%;display:block;overflow:visible;filter:drop-shadow(1.6px 0 0 #fff) drop-shadow(-1.6px 0 0 #fff) drop-shadow(0 1.6px 0 #fff) drop-shadow(0 -1.6px 0 #fff) drop-shadow(0 2px 3px rgba(0,0,0,.28))}   /* the white outline is the sticker's own, not the rotate handle's */
.stk-rot{position:absolute;right:-9px;top:-9px;width:20px;height:20px;border-radius:50%;background:#fff;color:#2A2418;box-shadow:0 0 0 1px rgba(0,0,0,.14),0 1px 2px rgba(0,0,0,.2);display:grid;place-items:center;opacity:0;transition:opacity .15s;cursor:grab;touch-action:none;transform:scale(calc(1 / var(--s,1)))}
.stk-rot svg{width:12px;height:12px}
.nb-board .note .stk:hover .stk-rot,.stk.rotating .stk-rot{opacity:1}
.stk.rotating .stk-rot{cursor:grabbing}
@media (hover:none){.nb-board .note .stk-rot{opacity:.85}}   /* (no hover on a touch screen, so the handle shows, as on notes) */
.ns-demo .stk-rot,.stk-ghost .stk-rot{display:none}
.nb-board .note .stk{cursor:grab;touch-action:none}
.ns-demo .stk{pointer-events:none;width:34px;height:34px}
.stk-ghost{position:fixed;z-index:10000;pointer-events:none;transform:translate(-50%,-50%) rotate(-6deg) scale(1.08);filter:drop-shadow(1.6px 0 0 #fff) drop-shadow(-1.6px 0 0 #fff) drop-shadow(0 1.6px 0 #fff) drop-shadow(0 -1.6px 0 #fff) drop-shadow(0 8px 10px rgba(0,0,0,.3))}
body.stk-dragging,body.stk-dragging *{cursor:grabbing!important;user-select:none}
.note.stk-target{outline:3px dashed rgba(255,255,255,.9);outline-offset:4px}
.note-row2{display:grid;grid-template-columns:1fr 1fr;gap:6px}
.note-shape,.note-pin{min-width:0;padding:6px 6px;font-size:.8125rem;background:rgba(255,255,255,.55)!important;border:1px solid rgba(42,36,24,.2)!important;border-radius:8px;color:#2A2418!important}
/* the sticker envelope */
.nb-wrap{display:flex;gap:14px;align-items:flex-start}
.nb-main{position:relative;flex:1;min-width:0}
.env{position:relative;flex:none;width:190px;border-radius:14px;background:#E6CC9E;background-image:radial-gradient(rgba(120,80,30,.14) 1px,transparent 1.4px);background-size:6px 6px;box-shadow:0 10px 24px rgba(60,35,10,.22),inset 0 0 0 1px rgba(120,80,30,.25);display:flex;flex-direction:column;overflow:hidden;max-height:calc(100dvh - 290px);min-height:200px}
.env-head{position:relative;border:0;background:#D9B97F;padding:12px 12px 26px;display:flex;align-items:center;gap:8px;cursor:pointer;color:#4A3014;font:800 .95rem var(--display);letter-spacing:.02em;clip-path:polygon(0 0,100% 0,100% 55%,50% 100%,0 55%);box-shadow:inset 0 -2px 0 rgba(120,80,30,.25)}
.env-title{flex:1;text-align:left}
.env-caret{font-size:.8rem}
.env-head::after{content:"";position:absolute;left:50%;bottom:8px;width:16px;height:16px;margin-left:-8px;border-radius:50%;background:radial-gradient(circle at 35% 35%,#FF8A80,#C62828 60%,#7F0000);box-shadow:0 1px 2px rgba(0,0,0,.35)}
.env-body{display:grid;gap:8px;padding:6px 10px 12px;overflow:auto;min-height:0}
.env.closed .env-body,.env.closed .env-pocket{display:none}
.env.closed{min-height:0}
.env-packs{display:grid;grid-template-columns:repeat(5,1fr);gap:3px}
.env-packs button{position:relative;border:1px solid transparent;background:rgba(255,255,255,.35);border-radius:8px;padding:2px;aspect-ratio:1;cursor:pointer}
.env-packs button.on{background:#fff;border-color:rgba(74,48,20,.45);box-shadow:0 1px 3px rgba(0,0,0,.15)}
.env-packs svg{width:100%;height:100%;display:block}
.env-packs .lock{position:absolute;right:-3px;bottom:-3px;font-size:.6rem;font-style:normal}
.env-name{display:flex;align-items:center;gap:6px;color:#4A3014;font-size:.85rem}
.env-sheet{display:grid;grid-template-columns:repeat(3,1fr);gap:6px;background:#FFFDF8;border-radius:10px;padding:8px;box-shadow:0 2px 6px rgba(60,35,10,.2),inset 0 0 0 1px rgba(0,0,0,.05);background-image:linear-gradient(rgba(0,0,0,.03) 1px,transparent 1px);background-size:100% 12px}
.env-sheet.locked{opacity:.55}
.env-results{display:grid;gap:8px}
.env-search{position:relative}
.env-q{width:100%;box-sizing:border-box;min-height:36px;padding:6px 30px 6px 10px;border-radius:10px;border:1px solid rgba(74,48,20,.3);background:rgba(255,255,255,.75);color:#3A260F;font:600 .85rem var(--body)}
.env-q::placeholder{color:#8A6A3C;font-weight:500}
.env-q::-webkit-search-cancel-button{display:none}
.env-q:focus-visible{outline:2px solid #8A5A1E;outline-offset:1px;background:#fff}
.env-qx{position:absolute;right:3px;top:50%;transform:translateY(-50%);width:30px;height:30px;border:0;border-radius:50%;background:none;color:#6B4A22;font-size:1.1rem;line-height:1;cursor:pointer}
.env-qx:hover{background:rgba(74,48,20,.12)}
.env-qx:focus-visible{outline:2px solid #8A5A1E}
.env-qx[hidden]{display:none}
.env.searching .env-packs button.on{background:rgba(255,255,255,.35);border-color:transparent;box-shadow:none}
.env-name .mini{color:#6B4A22;font-weight:500}
.env-found{max-height:260px;overflow-y:auto}
.env-stk[data-locked]{opacity:.5}
.env-stk:focus-visible{outline:2px solid #8A5A1E;outline-offset:2px;border-radius:8px}
.env-empty{display:grid;gap:6px;justify-items:center;text-align:center;background:#FFFDF8;border-radius:10px;padding:14px 10px;color:#4A3014;font-size:.82rem;box-shadow:inset 0 0 0 1px rgba(0,0,0,.05)}
.env-try{display:flex;flex-wrap:wrap;gap:4px;justify-content:center}
.env-try button{border:1px solid rgba(74,48,20,.3);background:rgba(255,255,255,.8);color:#4A3014;border-radius:99px;padding:4px 10px;min-height:30px;font:600 .78rem var(--body);cursor:pointer}
.env-try button:hover{background:#fff}
.env-stk{display:block;aspect-ratio:1;cursor:grab;touch-action:none;filter:drop-shadow(1.3px 0 0 #fff) drop-shadow(-1.3px 0 0 #fff) drop-shadow(0 1.3px 0 #fff) drop-shadow(0 -1.3px 0 #fff) drop-shadow(0 2px 2px rgba(0,0,0,.2));transition:transform .12s}
.env-stk:hover{transform:scale(1.12) rotate(-4deg)}
.env-stk svg{width:100%;height:100%;display:block;pointer-events:none;overflow:visible}
.env-hint{margin:0;font-size:.75rem;color:#6B4A22;text-align:center}
.env-pocket{height:14px;background:linear-gradient(170deg,transparent 48%,rgba(120,80,30,.18) 50%,transparent 52%),linear-gradient(190deg,transparent 48%,rgba(120,80,30,.18) 50%,transparent 52%);flex:none}
@media (max-width:700px){
  .nb-wrap{flex-direction:column;align-items:stretch}
  .env{position:fixed;z-index:45;left:12px;right:12px;bottom:calc(84px + env(safe-area-inset-bottom,0px));width:auto;max-height:none;min-height:0;box-shadow:0 -6px 24px rgba(60,35,10,.3),inset 0 0 0 1px rgba(120,80,30,.25)}
  .env.closed{left:auto;right:14px;border-radius:999px}
  .env.closed .env-head{border-radius:999px;padding:9px 14px}
  .env-head{clip-path:none;padding:10px 12px}
  .nb-wrap:has(.env:not(.closed)) .nb-main{padding-bottom:170px}
  .env-head::after{display:none}
  .env-packs{display:flex;overflow-x:auto;gap:4px}
  .env-packs button{flex:none;width:34px}
  .env-sheet{display:flex;overflow-x:auto;touch-action:pan-x}
  .env-stk{flex:none;width:52px;touch-action:pan-x}
  .env-found{max-height:none}
}
