.av-chips{display:flex;flex-wrap:wrap;gap:8px}
.av-chip{display:inline-flex;align-items:baseline;gap:8px;min-height:40px;padding:8px 14px;border:1px solid var(--line);border-radius:999px;background:var(--surface);color:var(--ink);cursor:pointer;font:inherit;font-size:.9rem;align-items:center}
.av-chip small{color:var(--muted);font-size:.8rem}
.av-chip:hover,.av-chip:focus-visible{border-color:var(--accent)}
.pr-slot{grid-area:slot;font-size:.84rem;color:var(--muted);padding:0 0 4px;min-width:0;overflow-wrap:anywhere}
.pr-slot b,.nu-slot b{color:var(--ink);font-weight:600}
.av-form fieldset{border:1px solid var(--line);border-radius:10px;padding:8px 12px 12px;margin:10px 0 0;min-width:0;min-inline-size:0}
.av-form legend{padding:0 6px}
.av-form .seg span{padding:11px 4px}
.av-form .meet-days{gap:6px;flex-wrap:wrap}
.av-form .meet-days button{min-height:40px;min-width:40px;width:auto;padding:0 8px}
.av-form input[type=color]{width:100%;min-height:44px;padding:3px;border-radius:10px}
.av-form textarea{min-height:60px}
.av-list{list-style:none;margin:10px 0;padding:0;display:grid;gap:8px}
.av-row{display:grid;gap:6px;padding:8px 10px;border:1px solid var(--line);border-left:6px solid var(--c);border-radius:10px;min-width:0}
.av-dot{display:none}
.av-rt{min-width:0;overflow-wrap:anywhere}
.av-ra{display:flex;gap:6px;flex-wrap:wrap}
.av-none{padding:8px 0}
.av-rrow{display:flex;align-items:center;gap:10px;flex-wrap:wrap;margin:6px 0}
.av-cal{margin-top:8px}
.av-cal-h{display:flex;align-items:center;justify-content:space-between;gap:8px;margin-bottom:4px}
.av-cal-h .icon-btn{width:40px;height:40px;font-size:1.3rem}
.av-cal-w,.av-cal-g{display:grid;grid-template-columns:repeat(7,minmax(0,1fr));gap:4px}
.av-cal-w span{text-align:center;font-size:.74rem;color:var(--muted)}
.av-cal-g button{min-height:40px;border:1px solid var(--line);background:var(--surface);color:var(--ink);border-radius:8px;font:600 .9rem var(--body)}
.av-cal-g button.is-today{border-color:var(--accent)}
.av-cal-g button[aria-pressed="true"]{background:var(--sel);border-color:var(--sel);color:var(--sel-ink)}
.av-dchips{display:flex;flex-wrap:wrap;gap:6px}
.av-dchips p{flex-basis:100%}
.av-dc{min-height:36px;padding:4px 10px;border:1px solid var(--line);background:var(--surface);color:var(--ink);border-radius:999px;font-size:.84rem}
@media (max-width:600px){.av-form .two{grid-template-columns:minmax(0,1fr)}.av-form .av-times,.av-form .av-buf{grid-template-columns:minmax(0,1fr) minmax(0,1fr)}}
.ics-list{display:grid;gap:4px;max-height:46vh;overflow:auto;margin-top:10px;border:1px solid var(--line);border-radius:10px;padding:6px}
.ics-row{display:flex;align-items:center;gap:10px;padding:6px 6px;border-radius:8px}
.ics-row:nth-child(odd){background:var(--soft)}
.ics-main{flex:1;min-width:0;display:grid}
.ics-main b{font-weight:600;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.ics-row select{width:auto;flex:none}
.help-list{padding-left:18px;display:grid;gap:6px}
.occ-foot{flex-wrap:wrap;gap:8px}.occ-foot .btn{white-space:nowrap}.occ-foot .btn.primary{margin-left:auto}
/* daily quote */
.qod-wrap{position:fixed;inset:0;z-index:200;display:grid;place-items:center;padding:16px;background:rgba(10,16,30,.28);backdrop-filter:blur(2px);opacity:0;transition:opacity .25s}
.qod-wrap.in{opacity:1}.qod-wrap.out{opacity:0}
.qod{width:min(440px,100%);background:var(--surface);color:var(--ink);border:1px solid var(--line);border-radius:20px;box-shadow:0 20px 60px rgba(8,20,50,.3);padding:26px 26px 20px;text-align:center;transform:translateY(10px) scale(.98);transition:transform .3s cubic-bezier(.2,.9,.3,1.2)}
.qod-wrap.in .qod{transform:none}
.qod-eyebrow{font:700 .72rem/1 var(--display);letter-spacing:.12em;text-transform:uppercase;color:var(--accent)}
.qod h2{margin:10px 0 8px;font:700 1.4rem/1.2 var(--display)}
.qod-q{font:600 1.28rem/1.4 var(--display);margin:14px 0 6px;text-wrap:balance}
.qod-who{margin:0 0 10px;color:var(--muted);font-size:.9rem}
.qod-who::before{content:"— "}
.qod-streak{margin:14px 0 0;padding:10px 12px;border-radius:12px;background:var(--soft);font-size:.86rem;color:var(--ink)}
.qod-foot{display:flex;justify-content:center;gap:8px;margin-top:16px;flex-wrap:wrap}
.streak-chip{margin-left:10px;border:0;background:color-mix(in srgb,var(--tomato) 14%,var(--surface));color:var(--ink);font:700 .8rem/1 var(--display);padding:5px 9px;border-radius:999px;vertical-align:middle;cursor:pointer}
@media (prefers-reduced-motion:reduce){.qod-wrap,.qod{transition:none}}
/* Heads Up (automatic AI) */
/* Exam location: where an exam or quiz is taken (REMOTEX) */
.rx-chip{display:inline-block;font:700 .68rem/1 var(--body);letter-spacing:.03em;border-radius:6px;padding:4px 7px;border:1px solid var(--line);color:var(--muted);background:var(--surface);white-space:nowrap}
.rx-chip.yes{color:var(--accent-ink,var(--ink));background:color-mix(in srgb,var(--accent) 14%,var(--surface));border-color:color-mix(in srgb,var(--accent) 40%,var(--line))}
.rx-chip.no{color:var(--ink);background:color-mix(in srgb,var(--ink) 6%,var(--surface))}
.rx-note{margin:6px 0 0;line-height:1.5}
.rx-q{flex:none;min-width:22px;height:22px;padding:0 6px;border-radius:50%;border:1px dashed var(--muted);background:transparent;color:var(--muted);font:700 .72rem/1 var(--body);cursor:pointer}
.rx-q:hover,.rx-q:focus-visible{border-color:var(--accent);color:var(--accent)}
.plan-fixed{margin:10px 0 0}
.plan-fixed ul{list-style:none;margin:4px 0 0;padding:0;display:grid;gap:2px}
.plan-fixed li{display:flex;align-items:center;gap:8px;min-height:36px;padding:2px 6px;border-radius:10px;border-left:3px solid var(--c,var(--line))}
.plan-fixed .plan-main{flex:1;min-width:0;text-align:left;background:none;border:0;padding:4px 0;font:inherit;color:inherit;cursor:pointer}
.plan-fixed .pf-when{flex:none;font:600 .78rem/1 var(--body);color:var(--muted)}
.tag.rx-tag{background:color-mix(in srgb,var(--accent) 14%,var(--surface))}
.plan-heads{margin:10px 0 0;padding:10px 12px;border-radius:12px;border:1px solid color-mix(in srgb,var(--accent) 30%,var(--line));background:color-mix(in srgb,var(--accent) 6%,var(--surface))}
.plan-heads .ph-label{display:inline-flex;align-items:center;gap:5px;font:700 .72rem/1 var(--display);letter-spacing:.06em;text-transform:uppercase;color:var(--accent)}
.plan-heads .ph-label .ai-ic{width:13px;height:13px}
.plan-heads ul{list-style:none;margin:6px 0 0;padding:0;display:grid;gap:4px}
.plan-heads li{display:flex;align-items:center;gap:8px;font-size:.9rem;line-height:1.35}
.plan-heads li span{flex:1}
.plan-heads .ph-x{width:26px;height:26px;min-width:26px;opacity:.6}
.plan-heads .ph-x svg{width:14px;height:14px}

.auto-badge{display:inline-block;font:700 .62rem/1 var(--display);letter-spacing:.05em;text-transform:uppercase;padding:2px 6px;border-radius:999px;color:#6D3FD0;background:color-mix(in srgb,#8B5CF6 14%,var(--surface));border:1px solid color-mix(in srgb,#8B5CF6 30%,var(--line));vertical-align:middle}
.auto-ins{margin:10px 0 0;padding:10px 12px;border-radius:12px;border:1px solid color-mix(in srgb,#8B5CF6 28%,var(--line));background:color-mix(in srgb,#8B5CF6 5%,var(--surface))}
.auto-ins .ai-top{display:flex;align-items:center;gap:8px;flex-wrap:wrap}
.auto-ins .ph-label{display:inline-flex;align-items:center;gap:6px;font:700 .72rem/1 var(--display);letter-spacing:.06em;text-transform:uppercase;color:var(--accent)}
.auto-ins .ph-label .ai-ic{width:13px;height:13px}
.auto-ins ul{list-style:none;margin:8px 0 4px;padding:0;display:grid;gap:8px}
.auto-ins li{display:flex;align-items:flex-start;gap:8px;font-size:.9rem;line-height:1.35;padding-top:8px;border-top:1px solid var(--line)}
.auto-ins li:first-child{border-top:0;padding-top:0}
.auto-ins .ins-body{flex:1;min-width:0}
.auto-ins .ins-k{display:block;font:700 .64rem/1.3 var(--display);letter-spacing:.06em;text-transform:uppercase;color:var(--muted)}
.auto-ins li[data-kind=attn] .ins-k{color:var(--warn)}
.auto-ins .ins-acts{display:flex;align-items:center;gap:4px;flex-shrink:0;flex-wrap:wrap;justify-content:flex-end;max-width:46%}
.auto-ins .ph-x{width:26px;height:26px;min-width:26px;opacity:.6}
.auto-ins .ph-x svg{width:14px;height:14px}
.auto-ins .ins-more ol{margin:4px 0 0;padding-left:18px}
.ann-ai{margin:4px 0 0;font-size:.85rem}
.ann-attn{display:inline-block;font:700 .66rem/1 var(--display);text-transform:uppercase;letter-spacing:.04em;padding:3px 6px;border-radius:6px;background:color-mix(in srgb,var(--warn) 18%,var(--surface));color:var(--warn)}
.ap-row{padding:8px 0;border-top:1px solid var(--line)}
@media (max-width:560px){.auto-ins li{flex-direction:column}.auto-ins .ins-acts{max-width:none;justify-content:flex-start}}

/* Full screen board (boardMax in 01-notes.js): the arrow button at the board's top left corner, and the board filling the app window */
.board-max-btn{position:absolute;z-index:6;display:inline-flex;align-items:center;justify-content:center;width:36px;height:36px;padding:0;border-radius:999px;cursor:pointer;color:var(--ink);background:color-mix(in srgb,var(--surface) 88%,transparent);border:1px solid var(--line);box-shadow:0 2px 8px rgba(40,25,10,.18);-webkit-backdrop-filter:blur(6px);backdrop-filter:blur(6px)}
.board-max-btn svg{width:17px;height:17px}
.board-max-btn:hover{filter:brightness(.96)}
.board-max-btn:focus-visible{outline:2px solid var(--accent);outline-offset:2px}
.nb-max{top:14px;right:14px}
/* Archive and Trash: round icon buttons beside it at the top (their names are in their labels; dragging a note over one still grows it) */
.nb-main .nb-targets{top:14px;right:58px;bottom:auto!important;gap:8px!important;z-index:6}
.nb-main .nb-target{width:36px!important;height:36px!important;padding:0!important;gap:0!important;border-radius:999px!important;border:1px solid var(--line)!important;background:color-mix(in srgb,var(--surface) 88%,transparent)!important;box-shadow:0 2px 8px rgba(40,25,10,.18)!important;justify-content:center!important;align-items:center!important}
.nb-main .nb-target>span{display:none}
.nb-main .nb-target svg{width:18px!important;height:18px!important;margin:0!important}
.nb-main .nb-target.hot{transform:scale(1.35)}
.nb-main .nb-target.trash.hot{background:color-mix(in srgb,var(--late) 18%,var(--surface))!important;border-color:var(--late)!important}
.nb-main .nb-target:not(.trash).hot{background:color-mix(in srgb,var(--accent) 18%,var(--surface))!important;border-color:var(--accent)!important}
.wb-max{top:8px;right:8px;color:#22262D;background:rgba(255,255,255,.9);border-color:rgba(0,0,0,.1);box-shadow:0 2px 8px rgba(20,30,45,.16)}
.wb-dk .wb-max{background:rgba(38,45,54,.95);border-color:rgba(255,255,255,.1);color:#E6EAEE}
.wb-stage .wb-zoom{left:8px;right:auto}
@media (max-width:639px){
  .nb-max{top:12px;right:12px}
  .nb-main .nb-targets{top:12px;right:54px}
  .wb-max{top:6px;right:6px}
  .wb-stage .wb-zoom{left:6px;right:auto}
}
html.board-max,html.board-max body{overflow:hidden!important;overscroll-behavior:none}
html.board-max{scrollbar-gutter:auto}
html.board-max .nb-wrap,html.board-max .wb-host{position:fixed;inset:0;z-index:40;margin:0!important;box-sizing:border-box;background:var(--bg)}
html.board-max .nb-wrap{display:flex;align-items:stretch;gap:12px;padding:max(10px,env(safe-area-inset-top,0px)) max(10px,env(safe-area-inset-right,0px)) max(10px,env(safe-area-inset-bottom,0px)) max(10px,env(safe-area-inset-left,0px))}
html.board-max .nb-main{display:flex;flex-direction:column;min-height:0;padding-bottom:0}
html.board-max .nb-scroll{flex:1;height:auto!important;min-height:0}
html.board-max .env{max-height:none}
html.board-max .wb-host{height:auto!important;min-height:0}
html.board-max .wb-stage{border-radius:0;padding:max(8px,env(safe-area-inset-top,0px)) max(8px,env(safe-area-inset-right,0px)) max(8px,env(safe-area-inset-bottom,0px)) max(8px,env(safe-area-inset-left,0px))}
@media (max-width:700px){
  html.board-max .nb-wrap{flex-direction:column}
  html.board-max .nb-main{flex:1}
  html.board-max .env{bottom:calc(12px + env(safe-area-inset-bottom,0px))}
}
/* ===== module: 05-account.css ===== */
/* Studyboard account sheets */
.sb-acct .sb-code{letter-spacing:.35em;font-size:1.25rem;text-align:center;font-variant-numeric:tabular-nums}
.sb-acct .status-msg:empty{display:none}
.sb-acct .mini .link-btn{font-size:inherit}
/* On phones there's no room beside the logo for words, so a sync problem shows as a small amber dot (tap Settings for details) */
@media (max-width:600px){
  .top-row .sync:not([data-state="ok"]){font-size:0;width:9px;height:9px;flex:none;border-radius:50%;background:#E0A030;box-shadow:0 0 0 3px color-mix(in srgb,#E0A030 22%,transparent);align-self:center}
}


/* ===== module: 10-plan.css ===== */
/* Studyboard Pro sheet, Your Devices, and the Settings row */
dialog:has(.plan-sheet){width:min(600px,calc(100% - 24px))}
@media (max-width:600px){dialog:has(.plan-sheet){width:100%}}   /* phones: full width like every other sheet (they sit at the left edge, so a narrower one looked off centre) */
.plan-sheet{--pro-a:#FFB443;--pro-b:#FF5C8A;--pro-glow:color-mix(in srgb,var(--pro-b) 22%,transparent)}
.plan-sheet .sheet-body{display:flex;flex-direction:column;gap:14px}
.plan-sheet .sheet-body > *{flex:none}
.plan-reason{display:flex;align-items:flex-start;gap:10px;margin:0;padding:10px 12px;border-radius:12px;font-weight:600;font-size:.94rem;
  background:color-mix(in srgb,var(--pro-a) 13%,var(--surface));border:1px solid color-mix(in srgb,var(--pro-a) 45%,var(--line));color:var(--ink)}
.plan-reason svg{width:20px;height:20px;flex:none;margin-top:1px;color:color-mix(in srgb,var(--pro-a) 70%,var(--ink))}

.plan-hero{--hero-a:#4ADE80;--hero-b:#16A34A;--hero-glow:color-mix(in srgb,var(--hero-b) 30%,transparent);   /* Free plan: green */
  position:relative;display:flex;align-items:center;gap:14px;padding:16px;border-radius:16px;overflow:hidden;
  background:radial-gradient(120% 140% at 0% 0%,color-mix(in srgb,var(--hero-a) 18%,transparent),transparent 55%),
             radial-gradient(120% 140% at 100% 100%,color-mix(in srgb,var(--hero-b) 14%,transparent),transparent 60%),
             color-mix(in srgb,var(--surface) 92%,var(--paper));
  border:1px solid color-mix(in srgb,var(--hero-b) 22%,var(--line))}
.plan-hero.is-pro{--hero-a:var(--pro-a);--hero-b:var(--pro-b);--hero-glow:var(--pro-glow)}   /* Pro bought: orange */
.plan-hero b{display:block;font:700 1.08rem var(--display);color:var(--ink)}
.plan-hero .mini{margin:3px 0 0;line-height:1.4}
.plan-orb{flex:none;display:grid;place-items:center;width:46px;height:46px;border-radius:50%;color:#fff;
  background:linear-gradient(135deg,var(--hero-a),var(--hero-b));box-shadow:0 0 0 5px color-mix(in srgb,var(--hero-b) 12%,transparent),0 6px 22px var(--hero-glow)}
.plan-orb svg{width:26px;height:26px}
@media (prefers-reduced-motion:no-preference){.plan-orb{animation:planGlow 3.6s ease-in-out infinite}}
@keyframes planGlow{50%{box-shadow:0 0 0 8px color-mix(in srgb,var(--hero-b) 8%,transparent),0 8px 28px var(--hero-glow)}}

.cp-banner{position:fixed;left:50%;bottom:16px;transform:translateX(-50%);z-index:60;display:flex;align-items:center;gap:12px;max-width:calc(100vw - 24px);padding:8px 8px 8px 16px;border-radius:999px;
  background:var(--surface);color:var(--ink);border:1px solid var(--line);box-shadow:0 8px 28px rgba(0,0,0,.35);font:600 .9rem var(--display)}
.cp-banner .cp-txt{min-width:0;overflow-wrap:anywhere}
.cp-note{margin:6px 0 0}
.plan-compare{display:grid;border:1px solid var(--line);border-radius:14px;overflow:hidden;background:var(--surface)}
.pc-row{display:grid;grid-template-columns:minmax(0,1.25fr) minmax(0,1fr) minmax(0,1.15fr);align-items:center;font-size:.9rem;border-top:1px solid var(--line)}
.pc-row > span{padding:9px 12px;min-width:0;overflow-wrap:anywhere}
.pc-row > span:first-child{font-weight:600;color:var(--ink)}
.pc-row > span:nth-child(2){color:var(--muted)}
.pc-row .pc-pro{align-self:stretch;display:flex;align-items:center;font-weight:700;color:var(--ink);background:color-mix(in srgb,var(--pro-b) 7%,var(--surface))}
.pc-head{border-top:0;font:700 .78rem var(--display);letter-spacing:.04em;text-transform:uppercase}
.pc-head > span:nth-child(2){color:var(--muted)}
.pc-head .pc-pro{background:color-mix(in srgb,var(--pro-b) 11%,var(--surface))}

.plan-free{display:flex;gap:8px;align-items:flex-start;margin:0;line-height:1.45}
.plan-free svg{width:18px;height:18px;flex:none;color:var(--leaf);margin-top:1px}

.plan-usage .fsec{margin:0 0 8px}
.plan-meter{display:grid;gap:5px;margin-bottom:10px}
.pm-top{display:flex;justify-content:space-between;gap:10px;font-weight:600;font-size:.9rem}
.pm-bar{height:8px;border-radius:99px;background:var(--soft);overflow:hidden;border:1px solid color-mix(in srgb,var(--line) 60%,transparent)}
.pm-bar i{display:block;height:100%;min-width:0;border-radius:inherit;background:linear-gradient(90deg,var(--accent),color-mix(in srgb,var(--accent) 60%,var(--pro-b)))}
.plan-meter.hot .pm-bar i{background:linear-gradient(90deg,var(--pro-a),var(--pro-b))}

.plan-prices{display:grid;grid-template-columns:1fr 1fr;gap:12px}
.plan-prices.three{grid-template-columns:repeat(3,minmax(0,1fr))}
@media (max-width:560px){.plan-prices.three{grid-template-columns:1fr 1fr}.plan-prices.three .plan-price.best{grid-column:1/-1}}
.plan-price{position:relative;display:grid;gap:3px;justify-items:start;text-align:left;min-height:96px;padding:14px 14px 12px;border-radius:16px;cursor:pointer;
  border:1.5px solid var(--line);background:var(--surface);color:var(--ink);transition:transform .15s,box-shadow .2s,border-color .2s}
.plan-price:hover{border-color:color-mix(in srgb,var(--accent) 50%,var(--line));transform:translateY(-1px)}
.plan-price:focus-visible{outline:3px solid color-mix(in srgb,var(--accent) 55%,transparent);outline-offset:2px}
.plan-price.best{border-color:transparent;background:linear-gradient(var(--surface),var(--surface)) padding-box,linear-gradient(135deg,var(--pro-a),var(--pro-b)) border-box;
  box-shadow:0 8px 26px var(--pro-glow)}
.pp-name{font:700 .8rem var(--display);letter-spacing:.05em;text-transform:uppercase;color:var(--muted)}
.pp-amt{font:800 1.45rem var(--display);letter-spacing:-.01em}
.pp-amt small{font:600 .82rem var(--display);color:var(--muted)}
.pp-sub{font-size:.8rem;color:var(--muted);line-height:1.3}
.pp-flag{position:absolute;top:-10px;right:12px;font:800 .7rem var(--display);letter-spacing:.04em;color:#fff;padding:3px 8px;border-radius:99px;background:linear-gradient(135deg,var(--pro-a),var(--pro-b))}
.plan-fine{margin:-4px 0 0;text-align:center;line-height:1.45}
.plan-fine .link-btn{font-size:inherit;padding:0}
.plan-actions{display:flex;flex-wrap:wrap;gap:10px}

.plan-devs{list-style:none;margin:0;padding:0;display:grid;gap:8px}
.plan-devs li{display:flex;align-items:center;gap:12px;padding:10px 12px;min-height:44px;border:1px solid var(--line);border-radius:12px;background:var(--surface)}
.plan-devs li > svg{width:24px;height:24px;flex:none;color:var(--muted)}
.pd-name{flex:1;min-width:0;display:grid}
.pd-name b{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}

.menu-list button.plan-row{align-items:center}
.plan-row-ic{display:grid;place-items:center;flex:none;width:30px;height:30px;border-radius:50%;color:#fff;background:linear-gradient(135deg,#FFB443,#FF5C8A);box-shadow:0 3px 12px color-mix(in srgb,#FF5C8A 25%,transparent)}
.plan-row-ic svg{width:17px;height:17px}

@media (max-width:600px){
  .plan-sheet .sheet-body{padding-left:14px;padding-right:14px}
  .pc-row{font-size:.84rem}
  .pc-row > span{padding:8px 9px}
