.sx-types .chip{min-height:36px}
.sx-body{flex:1;min-height:0;overflow:auto;overscroll-behavior:contain;padding:4px 8px 10px}
.sx-gh{display:flex;align-items:center;gap:8px;padding:12px 8px 4px;font-size:.74rem;font-weight:700;letter-spacing:.06em;text-transform:uppercase;color:var(--muted)}
