.sx-num{flex:none;width:28px;height:28px;border-radius:50%;display:grid;place-items:center;font-weight:700;font-size:.85rem;background:var(--soft);color:var(--ink)}
.sx-main{flex:1;min-width:0;display:flex;flex-direction:column;gap:1px}
.sx-t{font-weight:600;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.sx-s{font-size:.85rem;color:var(--muted);display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden;overflow-wrap:anywhere}
