.sx-ans .mi-check{display:flex;gap:10px;align-items:flex-start;margin:10px 0;font-size:.9rem}
.sx-ans .mi-check input{width:20px;height:20px;flex:none;margin-top:1px;accent-color:var(--accent)}
.sx-ans-btns,.sx-ans-row{display:flex;gap:8px;flex-wrap:wrap}
.sx-ans-row{margin:8px}
.sx-cite{display:inline-grid;place-items:center;min-width:22px;height:20px;padding:0 5px;margin:0 1px;border-radius:6px;border:0;background:color-mix(in srgb,#8B5CF6 20%,var(--surface));color:inherit;font-size:.75rem;font-weight:700;vertical-align:1px}
.sx-from{display:flex;flex-wrap:wrap;gap:6px;align-items:center;font-size:.8rem;color:var(--muted)}
.sx-src{display:inline-flex;align-items:center;gap:6px;border:1px solid var(--line);background:var(--surface);border-radius:999px;padding:4px 10px 4px 4px;font-size:.8rem;max-width:100%;min-height:32px}
.sx-src span{display:grid;place-items:center;width:20px;height:20px;border-radius:50%;background:var(--soft);font-weight:700;font-size:.72rem;flex:none}
/* Ask Your Course: scope chips, the conversation, general knowledge, study buttons and Quiz Me */
.sx-ans-t{white-space:pre-line;overflow-wrap:anywhere}
