.sx-study{gap:8px}
.sx-fu .chip{min-height:34px;max-width:100%;white-space:normal;text-align:left}
.sx-err{color:color-mix(in srgb,#DC2626 75%,var(--ink))}
.sx-ans-h .spacer{flex:1}
