.sx-topt.ok{border-color:#16A34A;background:color-mix(in srgb,#16A34A 13%,var(--surface))}
.sx-topt.no{border-color:#DC2626;background:color-mix(in srgb,#DC2626 11%,var(--surface))}
.sx-tin{display:flex;gap:8px;margin:8px 0}
