.ob-bk{width:100%;text-align:left;font:inherit;color:var(--ink);background:var(--surface);border-style:solid;cursor:pointer}.ob-bk:hover,.ob-bk:focus-visible{border-color:var(--accent)}.ob-bk .ob-alt-t{display:grid;gap:2px}.ob-bk .bk-ico{flex:none}
