.ob-chip[aria-pressed="true"]{background:var(--accent);border-color:var(--accent);color:var(--accent-ink)}
/* Reminders, AI, app */
.ob-big{justify-self:center;min-width:220px;min-height:48px;font-size:1rem}
a.ob-big{text-decoration:none!important;display:inline-flex;align-items:center;justify-content:center}
.ob-msbadge{justify-self:center;display:inline-block;line-height:0;border-radius:8px}
.ob-msbadge img{width:auto;height:56px}
.ob-msbadge .on-dark,:root[data-theme="dark"] .ob-msbadge .on-light{display:none}
:root[data-theme="dark"] .ob-msbadge .on-dark{display:inline}
.ob-duo{display:flex;justify-content:center;gap:10px;flex-wrap:wrap}
.ob-duo .btn{min-width:130px;min-height:46px}
.ob-okbox{display:flex;align-items:center;gap:12px;padding:14px 16px;border:1px solid color-mix(in srgb,var(--accent) 35%,var(--line));border-radius:16px;background:color-mix(in srgb,var(--accent) 7%,var(--surface))}
.ob-okbox>svg{flex:none;width:34px;height:34px;padding:7px;border-radius:50%;background:var(--accent);color:var(--accent-ink)}
.ob-okbox>span{flex:1;display:grid;gap:2px;min-width:0}
.ob-okbox .mini{font-size:.85rem;line-height:1.45}
.ob-info{padding:14px 16px;border-radius:16px;background:var(--soft);text-align:center;line-height:1.5}
.ob-info .mini{font-size:.9rem;color:var(--ink)}
#obRMsg{margin:0;text-align:center}
.ob-dev{justify-self:center}
.ob-dev button{min-height:38px;padding:6px 14px}
.ob-tips{list-style:none;margin:0;padding:0;border:1px solid var(--line);border-radius:16px;overflow:hidden}
.ob-tips li{display:flex;align-items:center;gap:12px;padding:12px 14px;font-size:.93rem;line-height:1.45}
.ob-tips li+li{border-top:1px solid var(--line)}
.ob-num{flex:none;width:36px;height:36px;border-radius:11px;display:grid;place-items:center;background:var(--ob-tint);color:var(--accent)}
.ob-num svg{width:20px;height:20px}
/* Done */
.ob-sum{list-style:none;margin:0 auto;padding:0;display:grid;gap:8px;width:min(100%,380px)}
.ob-sum li{display:flex;align-items:center;gap:10px;font-size:.95rem}
.ob-ck{flex:none;width:24px;height:24px;border-radius:50%;border:1.5px solid var(--line);display:grid;place-items:center}
.ob-sum li.ok .ob-ck{background:var(--accent);border-color:var(--accent);color:var(--accent-ink)}
.ob-ck svg{width:13px;height:13px}
.ob-sum li:not(.ok){color:var(--muted)}
.ob-gift{display:flex;gap:14px;align-items:center;padding:14px 16px;border-radius:16px;margin-bottom:12px;border:1px solid color-mix(in srgb,#F5B301 45%,var(--line));background:linear-gradient(135deg,color-mix(in srgb,#FFD166 22%,var(--surface)),color-mix(in srgb,#FF8FB0 14%,var(--surface)))}
.ob-gift > span:last-child{display:grid;gap:4px}
.ob-gift-ic{font-size:2rem;line-height:1}
.ob-hero.pro .ob-gift-ic{font-size:2.2rem}
.ob-pro li > span:last-child .mini{color:var(--muted)}
.ob-h .ob-pro-tag{display:inline-block;vertical-align:middle;position:relative;top:0;margin-left:.3em;font-size:.45em;padding:.27em .7em}
.ob-next{display:grid;gap:6px;padding:14px 16px;border-radius:16px;border:1px solid color-mix(in srgb,var(--accent) 35%,var(--line));background:color-mix(in srgb,var(--accent) 6%,var(--surface))}
.ob-next b{font-family:var(--display)}
.ob-next .mini{font-size:.86rem;line-height:1.45}
.ob-qa{display:flex;align-items:center;gap:10px;margin-top:4px;padding:10px 12px;border:1px solid var(--line);border-radius:12px;background:var(--surface);color:var(--muted);font-size:.92rem}
.ob-qa span{color:var(--accent);font-weight:700;font-size:1.1rem;line-height:1}
.ob-foot .btn{min-height:44px}
.ob-back[hidden]{display:inline-block!important;visibility:hidden}
canvas.ob-fx{position:fixed;inset:0;z-index:5}
.qa-bar.ob-glow{animation:obGlow 1.3s ease-in-out 2}
@keyframes obGlow{0%,100%{box-shadow:0 0 0 0 color-mix(in srgb,var(--accent) 0%,transparent)}50%{box-shadow:0 0 0 5px color-mix(in srgb,var(--accent) 35%,transparent)}}
@media (max-width:600px){
  .ob-top{padding:14px 16px 6px}
  .ob-bar{padding:0 16px 2px;gap:4px}
  .ob .ob-body{padding:12px 16px 18px}
  .ob-h{font-size:1.35rem}
  .ob-hero{width:56px;height:56px;border-radius:18px}
  .ob-hero svg{width:28px;height:28px}
  .ob-themes{grid-template-columns:repeat(2,minmax(0,1fr))}
  .ob-cfields{grid-template-columns:1fr}
  .ob-crow .btn{margin-left:0;flex:1}
  .ob-alt{flex-wrap:wrap}
  .ob-alt .btn{flex:1 1 100%}
  .ob[data-step="done"] .ob-back{display:none!important}
  .ob-foot .btn{padding-left:14px;padding-right:14px}
}
@media (prefers-reduced-motion:reduce){
  .ob-step-in,.ob-hero.done,.ob-clist li{animation:none}
  .ob-theme,.ob-seg::before{transition:none}
  .ob-theme:hover{transform:none}
  .qa-bar.ob-glow{animation:none;box-shadow:0 0 0 3px color-mix(in srgb,var(--accent) 35%,transparent)}
}
@media (max-width:600px){
  .ob[data-step="done"] .ob-foot{flex-direction:column-reverse;align-items:stretch;gap:8px}
  .ob[data-step="done"] .ob-foot .spacer{display:none}
  .ob-foot .btn{white-space:nowrap}
}


/* ===== module: 50-calfeed.css ===== */
/* Calendar Sync sheet (50-calfeed) */
.cs-sheet .cs-tabs{align-self:start;justify-self:start;max-width:100%}
.cs-sheet .cs-tabs button{min-height:40px;padding:6px 16px}
.cs-pane{display:grid;gap:14px;min-width:0}
.cs-pane p{margin:0}
.cs-note{border:1px solid var(--line);border-radius:12px;padding:12px 14px;background:color-mix(in srgb,var(--soft) 55%,transparent);display:grid;gap:10px;font-size:.92rem;min-width:0}
.cs-note.warn{border-color:color-mix(in srgb,var(--late) 45%,var(--line));background:color-mix(in srgb,var(--late) 7%,var(--surface))}
