.cs-row{display:flex;flex-wrap:wrap;gap:10px;align-items:center}
.cs-row .btn,.cs-note .btn{min-height:44px}
.cs-steps{margin:0;padding-left:1.3em;display:grid;gap:8px;font-size:.9rem}
.cs-steps .btn{margin-top:6px;display:block}
.cs-steps code,.cs-note code{font-size:.85em;background:var(--field);border:1px solid var(--line);border-radius:6px;padding:1px 5px;overflow-wrap:anywhere}
.cs-list{margin:0;font-size:.9rem}
.cs-linkbox{display:grid;gap:6px}
.cs-link{display:flex;gap:8px;align-items:center;min-width:0}
