.cs-link .btn{flex:none;min-height:44px}
.cs-add{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:8px}
.cs-add a.btn{display:flex;flex-direction:column;align-items:flex-start;justify-content:center;gap:2px;min-height:52px;text-decoration:none;color:var(--ink)}
.cs-add a.btn .mini{font-weight:500}
.cs-status{display:flex;align-items:flex-start;gap:8px;font-size:.88rem;color:var(--muted)}
