.cs-status.ok .cs-dot{background:#1E9E74;opacity:1}
.cs-how summary{font-size:.9rem;padding:6px 0;min-height:32px}
.cs-how[open] > :not(summary){margin-top:8px}
.cs-courses{display:grid;grid-template-columns:repeat(auto-fill,minmax(180px,1fr));gap:4px 12px}
.cs-sheet .mi-check{min-height:40px;align-items:center}
.cs-sheet .mi-check > span{min-width:0}
.cs-sub{display:block;line-height:1.25}
.cs-course .dot{width:10px;height:10px;border-radius:50%;background:var(--c);flex:none}
.cs-saved:empty{display:none}
.cs-saved{margin:0}
.cs-count{font-size:.92rem;font-weight:600}
@media (max-width:520px){
  .cs-link{flex-wrap:wrap}
  .cs-link input{flex-basis:100%}
  .cs-add{grid-template-columns:1fr}
}
.cs-sheet fieldset{min-width:0;min-inline-size:0}
.cs-sheet .sheet-body > *,.cs-pane > *,.cs-opts .adv-body > *{min-width:0}
.cs-dates{grid-template-columns:minmax(0,1fr) minmax(0,1fr)}
.cs-dates input{min-width:0;width:100%;box-sizing:border-box}
@media (max-width:440px){.cs-dates{grid-template-columns:1fr}}


