.sbw{background:var(--surface);color:var(--ink);border:1px solid var(--line);border-radius:22px;box-shadow:0 10px 30px -12px rgba(15,31,61,.28),0 2px 6px rgba(15,31,61,.06);overflow:hidden;position:relative;z-index:1}
