.sbw-meta{display:block;font-size:.82rem;color:var(--muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.sbw-h{display:flex;align-items:baseline;justify-content:space-between;margin:14px 18px 4px;font:700 .9rem/1.2 var(--display)}
