.sbw-foot{display:flex;gap:8px;flex-wrap:wrap;padding:12px 14px 16px;margin-top:8px;border-top:1px solid var(--line)}
.sbw-chip{display:inline-flex;align-items:center;gap:6px;min-height:44px;padding:6px 14px;border-radius:999px;background:var(--soft);color:var(--ink);text-decoration:none;font-weight:600;font-size:.88rem}
.sbw-chip svg{width:17px;height:17px}
.sbw-set .cap-row .anim-tog{flex:none;min-height:44px;display:inline-flex;align-items:center;gap:6px}
.sbw-set .cap-row .btn{flex:none}
.sbw-set .anim-tog input{width:20px;height:20px;margin:0}
.sbw-set a.btn{text-decoration:none;display:inline-flex;align-items:center;min-height:40px}
.sbw-foot:not(:has(*)){display:none}


