.gk-miss{flex:none;min-width:34px;height:34px;border-radius:50%;display:grid;place-items:center;font:800 .95rem var(--display);background:color-mix(in srgb,var(--late) 14%,var(--surface));color:var(--ink);border:1px solid color-mix(in srgb,var(--late) 40%,var(--line))}
.grp-lb li.none{opacity:.6}
.gk-kind-note{display:grid;gap:8px;margin:0;padding:12px 14px;border-radius:12px;border:1px solid var(--line);background:var(--surface)}
