.gk-kind-note[data-for="project"]{border-color:color-mix(in srgb,#C9702B 45%,var(--line))}
.gk-kind-lead{margin:0;font-weight:600}
.gk-kind-tabs{display:flex;flex-wrap:wrap;gap:6px}
.gk-kind-tabs span{padding:3px 10px;border-radius:999px;font:600 .78rem var(--display);border:1px solid var(--line);background:color-mix(in srgb,var(--accent) 8%,var(--surface))}
.gk-kind-note[data-for="project"] .gk-kind-tabs span{background:color-mix(in srgb,#C9702B 12%,var(--surface))}
.gk-kind-feats{margin:0;padding-left:18px;display:grid;gap:3px;font-size:.88rem;color:var(--muted)}
/* Task board */
.pt-view{display:inline-flex;gap:4px}
.kb{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px;align-items:start}
@media (max-width:760px){.kb{grid-template-columns:1fr}}
.kb-col{background:color-mix(in srgb,var(--surface) 55%,transparent);border:1px solid var(--line);border-radius:16px;padding:10px;min-width:0}
