.kb-col ul{list-style:none;margin:0;padding:0;display:grid;gap:8px}
.kb-card{background:var(--surface);border:1px solid var(--line);border-radius:16px;padding:0 12px 6px;display:grid;gap:2px;min-width:0;box-shadow:var(--shadow);overflow:hidden;transition:border-color .15s}
.kb-card:hover{border-color:color-mix(in srgb,var(--kc) 55%,var(--line))}
