.kb-band{display:flex;align-items:center;gap:6px;margin:0 -12px;padding:4px 10px;min-height:26px;color:#fff;font:800 .72rem/1.2 var(--display);letter-spacing:.04em;background:linear-gradient(120deg,color-mix(in srgb,var(--kc) 88%,#000),color-mix(in srgb,var(--kc) 70%,var(--surface)))}
.kb-band span:last-child{overflow:hidden;text-overflow:ellipsis;white-space:nowrap;min-width:0}
