.mc-me{display:flex;align-items:center;gap:10px;padding:8px 10px;margin:0 0 10px;border:1px solid var(--line);border-radius:12px;background:var(--surface)}
.mc-me .mc-t{flex:1;display:grid;gap:1px;min-width:0}
.mc-dot{width:22px;height:22px;border-radius:50%;background:var(--mc);flex:none;box-shadow:0 0 0 3px color-mix(in srgb,var(--mc) 25%,transparent)}
.mc-grid{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:10px;margin-top:12px}
.gc-grid{display:flex;flex-wrap:wrap;gap:8px;margin:6px 0 4px}
.gc-grid .mc-sw{width:40px;height:40px;min-height:40px;padding:0;aspect-ratio:1;font-size:.8rem;flex:none}
.gc-any{position:relative;width:40px;height:40px;flex:none;border-radius:50%;display:grid;place-items:center;cursor:pointer;background:var(--mc,transparent);border:2px dashed var(--line);color:var(--muted);font:800 1.1rem var(--display)}
.gc-any.on{border:3px solid var(--surface);box-shadow:0 0 0 2px var(--ink);color:#fff}
.gc-any input{position:absolute;inset:0;opacity:0;cursor:pointer;width:100%;height:100%}
.gc-auto{display:flex;align-items:center;gap:8px;margin:6px 0 2px}
.gc-dot{width:22px;height:22px;border-radius:50%;flex:none;box-shadow:0 0 0 2px var(--surface),0 0 0 3px var(--line)}
.mc-sw{aspect-ratio:1;border-radius:50%;border:3px solid var(--surface);background:var(--mc);box-shadow:0 0 0 1px var(--line);color:#fff;font:800 .85rem var(--display);cursor:pointer;display:grid;place-items:center;min-height:44px}
