.kb-none{padding:10px;border:1px dashed var(--line);border-radius:10px;color:var(--muted);font-size:.85rem;text-align:center}

/* ===== module: 90-grades.css ===== */
/* Grade Tracker and Rough Week Rescue */
.gr-card{background:var(--surface);border:1px solid var(--line);border-radius:14px;padding:14px;display:grid;gap:12px}
.gr-card.gr-risk,.gr-card.gr-out{border-color:color-mix(in srgb,var(--late) 40%,var(--line))}
