.mg-list{list-style:none;margin:10px 0 0;padding:0;display:flex;flex-direction:column;gap:8px}
.mg-row{display:flex;gap:10px;align-items:center;justify-content:space-between;flex-wrap:wrap;border:1px solid var(--line);border-radius:12px;padding:10px 12px}
.mg-main{display:flex;flex-direction:column;gap:2px;min-width:0;flex:1 1 220px}
.mg-and{font-size:.8em;color:var(--muted,#888);text-transform:uppercase;letter-spacing:.05em}
.mg-seg{display:flex;gap:6px}
.mg-seg .btn[aria-pressed="true"]{background:var(--accent,#2f6fe4);color:#fff;border-color:var(--accent,#2f6fe4)}
.lms-task{display:flex;flex-direction:column;gap:8px;border:1px solid var(--line);border-radius:12px;padding:10px 12px}
.lms-pills{display:flex;flex-wrap:wrap;gap:6px}
.pill.lms-ok{background:color-mix(in srgb,#1f9d55 16%,transparent);color:inherit}
.pill.lms-warn{background:color-mix(in srgb,#d97706 20%,transparent);color:inherit}
.pill.lms-bad{background:color-mix(in srgb,#dc2626 20%,transparent);color:inherit}
.pill.lms-ext{background:color-mix(in srgb,#2563eb 18%,transparent);color:inherit}
.pill.lms-fbpill{font-size:.72em;vertical-align:middle}
.lms-task summary,.lms-rub summary,.lms-syl summary{cursor:pointer;min-height:32px;display:flex;align-items:center;gap:6px}
.lms-h{margin:10px 0 4px;font-size:.92em}
.lms-mark{margin:4px 0}
.bs-diag{margin-top:4px}.bs-diag summary{cursor:pointer;text-decoration:underline dotted;text-underline-offset:3px}.bs-diag summary::after{content:" \25B8"}.bs-diag[open] summary::after{content:" \25BE"}
.lms-cls{margin:6px 0 4px;padding:8px 10px;border-radius:12px;background:color-mix(in srgb,var(--accent) 8%,var(--surface));border:1px solid var(--line)}.lms-cls ul{list-style:none;margin:4px 0;padding:0;display:flex;flex-wrap:wrap;gap:6px 14px}.lms-cls li b{font-variant-numeric:tabular-nums}
.lms-fb,.lms-ra,.lms-cr,.lms-lv{list-style:none;margin:0;padding:0}
