.bs-sheet .sheet-body{display:grid;gap:10px}
.bs-status{display:flex;gap:12px;align-items:center;padding:12px 14px;border-radius:14px;background:color-mix(in srgb,var(--accent) 8%,var(--surface));border:1px solid color-mix(in srgb,var(--accent) 26%,var(--line))}
.bs-status.warn{background:color-mix(in srgb,var(--late) 9%,var(--surface));border-color:color-mix(in srgb,var(--late) 35%,var(--line))}
.bs-status b{display:block}
.bs-status .mini{display:block}
.bs-ico{flex:none;width:38px;height:38px;border-radius:11px;display:grid;place-items:center;color:var(--accent);background:color-mix(in srgb,var(--accent) 15%,var(--surface))}
.bs-status.warn .bs-ico{color:var(--late)}
.bs-acts{display:flex;flex-wrap:wrap;gap:8px;align-items:center}
.bs-way{display:grid;gap:8px;padding:14px;border:1px solid var(--line);border-radius:14px;background:var(--surface)}
.bs-way.rec{border-color:color-mix(in srgb,var(--accent) 40%,var(--line));box-shadow:0 0 0 3px color-mix(in srgb,var(--accent) 10%,transparent)}
.bs-way p{margin:0}
.bs-facts{margin:0;padding-left:1.1em;font-size:.82rem;display:grid;gap:4px}
.bs-code{max-height:240px;overflow:auto;margin:6px 0 0;padding:8px;border:1px solid var(--line);border-radius:8px;font-size:.68rem;line-height:1.35;white-space:pre-wrap;word-break:break-all}
.bs-way .f{margin:0}
.bs-way-h{display:flex;align-items:center;gap:8px;flex-wrap:wrap}
.bs-pill{font-size:.72rem;font-weight:700;padding:2px 8px;border-radius:99px;color:var(--accent-ink);background:var(--accent)}
.bs-note{padding:8px 10px;border-radius:10px;background:var(--soft)}
.bs-list,.bs-news,.bs-log{list-style:none;margin:0;padding:0;display:grid}
.bs-list li,.bs-news li{display:flex;gap:10px;align-items:center;justify-content:space-between;padding:10px 2px;border-bottom:1px solid var(--line);flex-wrap:wrap}
.bs-main{min-width:0;flex:1 1 220px}
.bs-main b{display:block;overflow-wrap:anywhere}
.bs-main .mini{display:block}
.bs-btns{display:flex;gap:6px;flex-wrap:wrap}
.bs-btns .btn{min-height:36px}
.bs-news-text{margin:4px 0 0;font-size:.88rem;color:var(--ink);opacity:.86;white-space:pre-line;display:-webkit-box;-webkit-line-clamp:4;-webkit-box-orient:vertical;overflow:hidden}
.bs-log li{display:flex;justify-content:space-between;gap:10px;padding:7px 2px 7px 14px;border-bottom:1px solid var(--line);position:relative;font-size:.9rem}
.bs-log li::before{content:"";position:absolute;left:2px;top:14px;width:6px;height:6px;border-radius:50%;background:var(--muted)}
.bs-log li.bsl-new::before{background:var(--accent)}
.bs-log li.bsl-moved::before{background:var(--late)}
.bs-log li.bsl-done::before,.bs-log li.bsl-grade::before{background:#1E9E74}
.bs-log li .mini{flex:none}
.bs-map{display:grid;gap:0}
.bs-maprow{display:flex;align-items:center;justify-content:space-between;gap:10px;padding:10px 2px;border-bottom:1px solid var(--line);flex-wrap:wrap}
.bs-maprow>span{min-width:0;flex:1 1 180px}
.bs-maprow b,.bs-maprow .mini{display:block}
.bs-maprow select{max-width:100%;flex:0 1 240px;min-height:40px}
.bs-opts .gs-opt{align-items:flex-start;padding:10px 4px;border-bottom:1px solid var(--line);min-height:44px}
.bs-opts .gs-opt input{margin-top:2px;flex:none}
.bs-opts .gs-opt span{font-weight:600}
.bs-opts .gs-opt .sub{display:block;font-weight:400;font-size:.8rem;color:var(--muted)}
.bs-opts .cap-row select{min-height:40px}
.bs-steps li{margin-bottom:6px}
.linklike{border:0;background:none;padding:0;color:var(--accent);font:inherit;text-decoration:underline;cursor:pointer}
.bs-course{display:grid;gap:6px;padding:12px 14px;border:1px solid var(--line);border-radius:14px;background:var(--surface);margin-bottom:8px}
.bs-course .fsec{margin:6px 0 0}
.bs-final{margin:0 0 8px;display:flex;align-items:baseline;gap:8px;padding:10px 14px;border:1px solid var(--line);border-radius:14px;background:var(--surface)}
.bs-final b{font:700 1.3rem var(--display)}
.bs-tag{font-size:.64rem;font-weight:800;letter-spacing:.04em;padding:1px 5px;border-radius:5px;color:var(--muted);border:1px solid var(--line);line-height:1.4}
.bs-sheet .cap-row{flex-wrap:wrap}
.bs-sheet .cap-row label{flex:1 1 200px;min-width:0}
.bs-sheet .cap-row label .sub{display:block;font-weight:400;font-size:.8rem;color:var(--muted)}
.bs-sheet .cap-row select{width:auto;flex:0 0 auto;min-width:140px}
.bs-sheet a.btn,.bs-course a.btn,.sec a.btn{text-decoration:none}
.bs-conn{display:grid;gap:8px}
.bs-conn .f{margin:0}
/* Choosing a platform */
.bs-plist{display:grid;gap:8px}
.bs-pcard{display:flex;align-items:center;gap:12px;width:100%;text-align:left;padding:12px 14px;border:1px solid var(--line);border-radius:14px;background:var(--surface);color:var(--ink);font:inherit;cursor:pointer;min-height:64px}
.bs-pcard:hover{border-color:color-mix(in srgb,var(--accent) 45%,var(--line))}
.bs-pcard.on{border-color:color-mix(in srgb,var(--accent) 40%,var(--line));background:color-mix(in srgb,var(--accent) 6%,var(--surface))}
.bs-plogo{flex:none;width:44px;height:44px;border-radius:12px;display:grid;place-items:center;overflow:hidden;font:800 .78rem var(--display);letter-spacing:.04em;color:var(--ink);background:var(--soft);box-shadow:inset 0 0 0 1px var(--line)}
.bs-plogo.long{font-size:.56rem;letter-spacing:0}
.bs-plogo.bs-l-cv{background:#D9302B;color:#fff;box-shadow:none}.bs-plogo.bs-l-bs{background:#E8761A;color:#fff;box-shadow:none}.bs-plogo.bs-l-bb{background:#111;color:#fff;box-shadow:inset 0 0 0 1px rgba(255,255,255,.18)}
.bs-pmain{flex:1;min-width:0}
.bs-pmain b{display:block}
.bs-pmain .mini{display:block;overflow-wrap:anywhere}
.bs-pgo{flex:none;font-weight:700;font-size:.88rem;color:var(--accent);padding:6px 12px;border-radius:99px;background:color-mix(in srgb,var(--accent) 12%,transparent)}


