/* ===== module: 96-tp-zreg.css ===== */
/* Theme Collections */
.tp-sec{display:grid;gap:10px;margin-top:6px}
.tp-group{display:grid;gap:6px;padding-top:8px;border-top:1px solid var(--line)}
.tp-theme{margin:0;font:700 .92rem var(--display);display:flex;align-items:center;gap:8px}
.tp-now{font:700 .68rem var(--body);padding:2px 8px;border-radius:99px;background:var(--accent);color:var(--accent-ink)}
.tp-packs{display:grid;gap:8px}
.env-tp{display:grid;gap:3px;font-size:.75rem;font-weight:700;color:#4A3014}
.sheet.occv{padding:0;overflow:hidden}
.occv-band{display:flex;align-items:center;gap:10px;padding:14px 14px 14px 18px;background:linear-gradient(120deg,color-mix(in srgb,var(--c) 88%,#000),color-mix(in srgb,var(--c) 74%,var(--surface)));color:#fff}
.occv-band b{flex:1;min-width:0;font:800 .82rem/1.2 var(--display);letter-spacing:.06em;text-transform:uppercase;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.occv-ic{display:grid;place-items:center;width:34px;height:34px;flex:none;border-radius:50%;background:#fff;color:var(--c)}
.occv-ic svg{width:70%;height:70%}
.occv-x{color:#fff!important;background:rgba(255,255,255,.16)!important;border-color:transparent!important}
.occv-body{padding:18px 20px 8px!important}
.occv-title{margin:0 0 8px;font:800 1.4rem/1.25 var(--display);color:var(--ink);overflow-wrap:anywhere}
.occv-tags{display:flex;flex-wrap:wrap;gap:6px;margin:0 0 12px}
.occv-tag{padding:4px 10px;border-radius:999px;font:700 .74rem/1.2 var(--display);background:color-mix(in srgb,var(--c) 14%,var(--surface));color:color-mix(in srgb,var(--c) 70%,var(--ink));border:1px solid color-mix(in srgb,var(--c) 28%,transparent)}
.occv-tag.warn{background:color-mix(in srgb,#D9534F 12%,var(--surface));color:#B23B37;border-color:color-mix(in srgb,#D9534F 30%,transparent)}
.occv-rows{list-style:none;margin:0;padding:0;display:grid;gap:2px}
.occv-rows li{display:flex;align-items:flex-start;gap:12px;padding:10px 4px;border-top:1px solid var(--line)}
.occv-rows li:first-child{border-top:0}
.occv-ri{display:grid;place-items:center;width:32px;height:32px;flex:none;border-radius:10px;background:color-mix(in srgb,var(--c) 12%,var(--surface));color:color-mix(in srgb,var(--c) 75%,var(--ink))}
.occv-rows li > div{display:grid;gap:2px;min-width:0;padding-top:5px}
.occv-rows b{font-weight:700;color:var(--ink);overflow-wrap:anywhere}
.occv-rows li > div > span{font-size:.84rem;color:var(--muted)}
.occv-notes{white-space:pre-wrap;font-weight:400}
.sb-dd{box-sizing:border-box;z-index:2147482500;overflow-y:auto;overscroll-behavior:contain;padding:6px;border:1px solid var(--line);border-radius:14px;background:var(--surface);color:var(--ink);box-shadow:0 18px 44px rgba(14,26,52,.22),0 2px 6px rgba(14,26,52,.10);font:500 .9rem/1.3 var(--body);scrollbar-width:thin;inset:auto}
.sb-dd-opt{display:flex;align-items:center;gap:10px;width:100%;padding:8px 12px;border:0;border-radius:9px;background:none;color:inherit;font:inherit;text-align:left;cursor:pointer}
.sb-dd-opt > span{flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.sb-dd-opt:hover,.sb-dd-opt:focus-visible{background:color-mix(in srgb,var(--accent) 10%,transparent);outline:none}
.sb-dd-opt.on{background:color-mix(in srgb,var(--accent) 16%,transparent);font-weight:700}
.sb-dd-opt[disabled]{opacity:.45;cursor:default}
.sb-dd-ck{flex:none;color:var(--accent)}
.sb-dd-grp{padding:10px 12px 4px;font:800 .7rem/1.2 var(--display);letter-spacing:.08em;text-transform:uppercase;color:var(--muted)}
.sb-dd-grp:first-child{padding-top:4px}
.env-tp-btn{display:flex;align-items:center;gap:8px;width:100%;min-height:36px;padding:6px 10px;border-radius:10px;border:1px solid rgba(74,48,20,.28);background:rgba(255,253,247,.85);color:#2A2418;font:600 .8rem/1.2 var(--display);text-align:left;cursor:pointer;box-shadow:0 1px 0 rgba(74,48,20,.06)}
.env-tp-btn:hover{background:#FFFDF7;border-color:rgba(74,48,20,.45)}
.env-tp-btn[aria-expanded="true"]{border-color:#B07A3B;box-shadow:0 0 0 3px rgba(176,122,59,.22)}
.env-tp-btn:focus-visible{outline:2px solid #B07A3B;outline-offset:2px}
.env-tp-cur{flex:1;min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.env-tp-btn > svg{flex:none;opacity:.7;transition:transform .15s}
.env-tp-btn[aria-expanded="true"] > svg{transform:rotate(180deg)}
.env-tp-dot{flex:none;width:12px;height:12px;border-radius:50%;box-shadow:inset 0 0 0 1.5px rgba(255,255,255,.55),0 0 0 1px rgba(42,36,24,.18)}
.env-tp-list{z-index:2147482000;overflow-y:auto;overscroll-behavior:contain;padding:6px;border-radius:14px;background:#FFFCF6;border:1px solid rgba(74,48,20,.18);box-shadow:0 18px 44px rgba(42,30,12,.22),0 2px 6px rgba(42,30,12,.10);scrollbar-width:thin}
.env-tp-opt{display:flex;align-items:center;gap:10px;width:100%;padding:8px 10px;border:0;border-radius:10px;background:none;color:#2A2418;text-align:left;cursor:pointer;font:inherit}
.env-tp-opt:hover,.env-tp-opt:focus-visible{background:rgba(176,122,59,.12);outline:none}
.env-tp-opt.on{background:rgba(176,122,59,.18)}
.env-tp-tx{flex:1;min-width:0;display:grid;line-height:1.25}
.env-tp-tx b{font:700 .84rem var(--display);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.env-tp-tx small{font-size:.74rem;color:#7A6B57;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.env-tp-ck{flex:none;color:#B07A3B}
[data-theme="dark"] .env-tp-list{background:#2A2219;border-color:rgba(255,236,200,.14)}
[data-theme="dark"] .env-tp-opt{color:#F2E8D8}
[data-theme="dark"] .env-tp-tx small{color:#BBA88C}
@media (prefers-color-scheme:dark){:root:not([data-theme="light"]) .env-tp-list{background:#2A2219;border-color:rgba(255,236,200,.14)}:root:not([data-theme="light"]) .env-tp-opt{color:#F2E8D8}:root:not([data-theme="light"]) .env-tp-tx small{color:#BBA88C}}
/* preview gallery (tests only) */
#tpGallery{position:fixed;inset:0;z-index:99999;overflow:auto;background:#F4F1EA;padding:18px 22px;color:#1D2233;font-family:var(--body)}
#tpGallery.tpg-dark{background:#15171F;color:#EEE}
.tpg-row{padding:12px 0 18px;border-bottom:1px solid rgba(0,0,0,.12)}
.tpg-row h2{margin:0 0 10px;font:800 1.1rem var(--display)}
.tpg-row h2 small{font:500 .8rem var(--body);opacity:.65}
.tpg-stk{display:flex;flex-wrap:wrap;gap:14px}
.tpg-stk figure{margin:0;display:grid;justify-items:center;gap:4px}
.tpg-stk .env-stk{width:84px;height:84px}
.tpg-stk figcaption,.tpg-pins figcaption{font-size:.7rem;opacity:.6}
.tpg-more{display:flex;flex-wrap:wrap;gap:24px;align-items:flex-start;margin-top:14px}
.tpg-pins{display:flex;gap:18px}
.tpg-pins figure{margin:0;width:170px}
.tpg-pins .ns-demo{padding-top:18px}
.tpg-cards{display:flex;gap:14px;flex-wrap:wrap}
.tpg-cards .flip{width:340px;margin:0;cursor:default}
.tp-eyebrow{display:flex;align-items:center;gap:6px;font:700 .72rem var(--display);letter-spacing:.03em;text-transform:uppercase;color:var(--muted);margin-bottom:4px}
.tp-pack{margin-top:6px}


/* ===== module: 97-ui-nav.css ===== */
/* ===== 97-ui: a side menu that always fits (desktop only; the phone bar is unchanged) =====
   97-ui-nav.js sets data-fit on nav.tabs to the roomiest level where every button fits:
   1 tighter spacing, 2 tools as a grid of icons, 3 small tab labels, 4 icon-only tabs, 5 smallest windows. */
@media (min-width:980px){
  nav.tabs .in button,nav.tabs .nav-tool{transition:background .15s,color .15s}

  /* 1: a little tighter */
  nav.tabs:is([data-fit="1"],[data-fit="2"],[data-fit="3"],[data-fit="4"],[data-fit="5"]){gap:8px;padding-top:12px}
  nav.tabs:is([data-fit="1"],[data-fit="2"]) .nav-brand img{width:96px}
  nav.tabs:is([data-fit="1"],[data-fit="2"]) .nav-brand{gap:3px}
  nav.tabs:is([data-fit="1"],[data-fit="2"]) .in button{padding:5px 4px 4px;gap:3px}
  nav.tabs:is([data-fit="1"],[data-fit="2"]) .in button svg{width:20px;height:20px}
  nav.tabs[data-fit="1"] .nav-tool{padding:5px 4px;gap:3px}

  /* 2: the tools at the bottom become a 2 by 2 grid of icons */
  nav.tabs:is([data-fit="2"],[data-fit="3"],[data-fit="4"],[data-fit="5"]) .nav-foot{display:grid;grid-template-columns:1fr 1fr;gap:2px;padding-top:6px}
  nav.tabs:is([data-fit="2"],[data-fit="3"],[data-fit="4"],[data-fit="5"]) .nav-sync{grid-column:1/-1;order:-1;display:flex;align-items:center;justify-content:center;gap:5px;padding:1px 2px 3px;font-size:.62rem;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
  nav.tabs:is([data-fit="2"],[data-fit="3"],[data-fit="4"],[data-fit="5"]) .nav-sync::before{margin:0;flex:none;width:7px;height:7px}
  nav.tabs:is([data-fit="2"],[data-fit="3"],[data-fit="4"],[data-fit="5"]) .nav-tool{padding:8px 2px;min-height:38px;justify-content:center}
  nav.tabs:is([data-fit="2"],[data-fit="3"],[data-fit="4"],[data-fit="5"]) .nav-tool span{display:none}

  /* 3: small tab labels, no date */
  nav.tabs:is([data-fit="3"],[data-fit="4"],[data-fit="5"]) .nav-date{display:none}
  nav.tabs[data-fit="3"] .nav-brand img{width:80px}
  nav.tabs[data-fit="3"] .in button{padding:3px 4px 3px;gap:2px;font-size:.66rem!important}
  nav.tabs[data-fit="3"] .in button svg{width:19px;height:19px}
  nav.tabs:is([data-fit="3"],[data-fit="4"],[data-fit="5"]) .in .nav-focus{margin-top:3px}

  /* 4: tabs become icons with tooltips */
  nav.tabs:is([data-fit="4"],[data-fit="5"]) .nav-brand img{width:70px}
  nav.tabs:is([data-fit="4"],[data-fit="5"]) .in button{font-size:0!important;line-height:0!important;gap:0;padding:6px 4px;min-height:max(33px,var(--nb-min,0px))}
  nav.tabs:is([data-fit="4"],[data-fit="5"]) .in button svg{width:21px;height:21px}
  nav.tabs:is([data-fit="4"],[data-fit="5"]) .in button[aria-current="page"]::before{top:7px;bottom:7px}
  nav.tabs:is([data-fit="4"],[data-fit="5"]) .in .nav-focus :is(.nf-m),nav.tabs:is([data-fit="4"],[data-fit="5"]) .in .nav-focus:not(.active) .nf-l{display:none}
  nav.tabs:is([data-fit="4"],[data-fit="5"]) .in .nav-focus.active{gap:3px;flex-direction:row}
  nav.tabs:is([data-fit="4"],[data-fit="5"]) .in .nav-focus.active .nf-l{font:700 .74rem/1 var(--display)!important}
  nav.tabs:is([data-fit="4"],[data-fit="5"]) .in .nav-focus.active svg{width:18px;height:18px}
  nav.tabs:is([data-fit="4"],[data-fit="5"]) .nav-groups .grp-dot{top:1px;right:22px}

  /* 5: the smallest windows */
  nav.tabs[data-fit="5"]{gap:5px;padding-top:8px;padding-bottom:calc(6px + env(safe-area-inset-bottom,0px))}
  nav.tabs[data-fit="5"] .nav-brand img{width:58px}
  nav.tabs[data-fit="5"] .in button{padding:4px;min-height:max(30px,var(--nb-min,0px))}
  nav.tabs[data-fit="5"] .in button svg{width:20px;height:20px}
  nav.tabs[data-fit="5"] .nav-tool{padding:5px 2px;min-height:32px}
  nav.tabs[data-fit="5"] .nav-tool svg{width:19px;height:19px}
  nav.tabs[data-fit="5"] .nav-sync{padding-bottom:1px}
}
/* spare height goes to the upper group (--nb-min and --nb-g are set by 97-ui-nav.js from the free room only) */
@media (min-width:980px){
  nav.tabs .in,nav.tabs:is([data-fit="3"],[data-fit="4"]) .in{gap:calc(2px + var(--nb-g,0px))}
  nav.tabs[data-fit="5"] .in{gap:calc(1px + var(--nb-g,0px))}
  nav.tabs .in > button{min-height:var(--nb-min,0px)}
}
@media (prefers-reduced-motion:reduce){nav.tabs .in button,nav.tabs .nav-tool{transition:none}}


/* ===== module: 97-ui-shop.css ===== */
/* ===== 97-ui: an easier Style Shop ===== */
.ui-shop .sheet-body{gap:12px;align-content:start}
.ui-shop-bar{position:sticky;top:-14px;z-index:4;display:grid;gap:8px;margin:-4px -18px 0;padding:8px 18px 10px;background:var(--surface);border-bottom:1px solid transparent}
.ui-shop-bar .shop-tabs{margin:0;overflow-x:auto;flex-wrap:nowrap;max-width:100%;scrollbar-width:none}
.ui-shop-bar .shop-tabs::-webkit-scrollbar{display:none}
.ui-shop-bar .shop-tabs button{white-space:nowrap;min-height:36px}
.ui-chips{display:flex;gap:6px;overflow-x:auto;scrollbar-width:none;padding:2px 1px}
.ui-chips::-webkit-scrollbar{display:none}
.ui-chip{flex:none;border:1px solid var(--line);background:var(--surface);color:var(--muted);border-radius:99px;padding:5px 13px;min-height:34px;font:600 .82rem var(--display);cursor:pointer;transition:background .15s,color .15s,box-shadow .15s}
.ui-chip:hover{color:var(--ink);border-color:color-mix(in srgb,var(--accent) 40%,var(--line))}
.ui-chip[aria-pressed="true"]{background:color-mix(in srgb,var(--accent) 13%,var(--surface));border-color:color-mix(in srgb,var(--accent) 50%,var(--line));color:var(--ink);box-shadow:0 0 0 3px color-mix(in srgb,var(--accent) 10%,transparent)}
.ui-chip:focus-visible,.ui-sec-btn:focus-visible{outline:2px solid var(--accent);outline-offset:2px}
/* sections */
.ui-sec{display:grid;gap:10px}
.ui-sec[hidden]{display:none}
.ui-sec > h3.shop-sec{margin:0}
.ui-sec-btn{display:flex;align-items:center;gap:8px;width:100%;border:0;background:none;padding:8px 4px;color:var(--ink);font:inherit;text-align:left;cursor:pointer;border-radius:10px;min-height:40px}
.ui-sec-btn:hover{background:color-mix(in srgb,var(--accent) 6%,transparent)}
.ui-sec-t{display:flex;align-items:center;gap:6px;flex:1;min-width:0}
.ui-n{font:600 .74rem var(--display);color:var(--muted);background:var(--field,var(--bg));border:1px solid var(--line);border-radius:99px;padding:1px 9px;min-width:26px;text-align:center}
.ui-chev{width:18px;height:18px;color:var(--muted);flex:none;transition:transform .2s}
.ui-sec.shut .ui-chev{transform:rotate(-90deg)}
.ui-sec.shut > .ui-sec-b{display:none}
.ui-sec-b{display:grid;gap:10px}
.ui-sec + .ui-sec{border-top:1px solid var(--line);padding-top:4px}
.ui-sec-b > .tp-rows{display:grid;gap:10px}
.ui-gone{display:none!important}
.ui-none{margin:20px 0;text-align:center;color:var(--muted)}
/* compact tiles */
.ui-shop .shop-grid{grid-template-columns:repeat(auto-fill,minmax(178px,1fr));gap:10px}
.ui-shop .shop-tile{padding:8px;gap:5px;border-radius:12px}
.ui-shop .skin-prev{height:66px}
.ui-shop .shop-tile p.mini{display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden;line-height:1.35}
.ui-shop .shop-name b{font-size:.92rem}
.ui-shop .shop-tile .cs-demo{transform-origin:top left}
.ui-shop .shop-pack{padding:8px 10px;gap:6px}
.ui-shop .pack-grid{grid-template-columns:repeat(auto-fill,minmax(46px,1fr));gap:8px}
.ui-shop .shop-tile.on{box-shadow:0 0 0 2px color-mix(in srgb,var(--accent) 30%,transparent),0 6px 20px color-mix(in srgb,var(--accent) 14%,transparent)}
/* Collections */
.ui-cols{display:grid;grid-template-columns:repeat(auto-fill,minmax(200px,1fr));grid-auto-flow:row dense;gap:12px}
.ui-col[hidden]{display:none}
.ui-col-prev .skin-prev{height:78px}
.ui-col .tp-now{margin-left:2px}
.ui-col-stk{display:grid;grid-template-columns:repeat(5,1fr);gap:6px;padding:2px 2px 0}
.ui-col-act{display:flex;gap:4px;flex-wrap:wrap;align-items:center;justify-content:space-between}
.ui-col-more{border:0!important;background:none!important;color:var(--accent)!important;box-shadow:none!important;padding-inline:8px!important}
.ui-col-more:hover{text-decoration:underline}
.ui-col.open{grid-column:1/-1}
.ui-col.open .ui-col-stk{display:none}
.ui-col-all{display:grid;gap:12px;border-top:1px dashed var(--line);padding-top:10px;margin-top:2px}
.ui-col-all[hidden]{display:none}
.ui-col-part{display:grid;gap:8px}
.ui-col-row{display:grid;grid-template-columns:repeat(auto-fill,minmax(200px,1fr));gap:12px;align-items:start}
.ui-col-piece{display:grid;gap:6px;justify-items:start;border:1px solid var(--line);border-radius:12px;padding:8px}
.ui-col-piece > :first-child{justify-self:stretch}
.ui-col.open .ui-col-prev .skin-prev{height:96px}
@media (min-width:720px){.ui-col.open{grid-template-columns:minmax(180px,260px) minmax(0,1fr);column-gap:16px;align-items:start}.ui-col.open > *{grid-column:1}.ui-col.open > .ui-col-all{grid-column:2;grid-row:1/span 5;border-top:0;padding-top:0;margin:0}}
@media (max-width:600px){
  .ui-shop .shop-grid{grid-template-columns:repeat(auto-fill,minmax(148px,1fr));gap:8px}
  .ui-shop .skin-prev{height:56px}
  .ui-cols{grid-template-columns:repeat(auto-fill,minmax(160px,1fr));gap:10px}
  .ui-shop .shop-mode{row-gap:6px}
  .ui-shop-bar .shop-tabs{flex-wrap:wrap;overflow:visible}
  .ui-shop-bar .shop-tabs button{flex:1 1 auto;padding-inline:8px}
  .ui-chips{-webkit-mask-image:linear-gradient(to right,#000 85%,transparent);mask-image:linear-gradient(to right,#000 85%,transparent);padding-right:28px}
}
@media (prefers-reduced-motion:reduce){.ui-chev,.ui-chip{transition:none}}
/* Speed: stickers and theme previews are cached bitmaps (the white edge and shadow are baked in, so there are no
   CSS filters to repaint), and each pack's stickers are only added just before it scrolls into view. */
.stk-cell.ui-stk{position:relative;filter:none}
.ui-stk img,.ui-stk > svg{position:absolute;left:-12.5%;top:-12.5%;width:125%;height:125%;display:block;max-width:none;pointer-events:none;user-select:none;-webkit-user-drag:none}

/* Long vertical lists use plain block flow (not grid), so adding one pack doesn't re-measure every other pack */
.ui-shop .sheet-body{display:block}
.ui-shop .sheet-body > * + *,.ui-shop .ui-sec-b > * + *,.ui-shop .tp-rows > * + *{margin-top:12px}
.ui-shop .ui-sec,.ui-shop .ui-sec-b,.ui-shop .ui-sec-b > .tp-rows,.ui-shop .tp-sec{display:block}
.ui-shop .ui-sec > h3.shop-sec{margin-bottom:8px}
.ui-shop .ui-sec[hidden],.ui-shop .ui-sec.shut > .ui-sec-b,.ui-col-all[hidden]{display:none}
.ui-shop .sheet-body > .ui-shop-bar + *{margin-top:12px}
/* Previews are pictures only: skipping them when finding what's under the pointer keeps hovering quick */
.ui-shop .skin-pair,.ui-shop .ui-col-prev,.ui-shop .pack-grid,.ui-shop .ui-col-stk,.ui-shop .ns-demo,.ui-shop .cs-demo,.ui-shop .shop-tile > p.mini{pointer-events:none}
.ui-shop .ui-sec.ui-held > .ui-sec-b,.ui-shop .ui-col.ui-held{display:none}
.ui-cols-more{margin-top:0!important}
.ui-shop .sheet-body{background:var(--surface)}   /* opaque, so the browser can scroll it without repainting */


/* ===== module: 97-ui.css ===== */
/* ===== 97-ui: Settings in categories ===== */
.us-sheet .us-back{display:none}
.us-sheet .sheet-body{display:block}
.us{--us-glow:color-mix(in srgb,var(--accent) 14%,transparent)}
.us-search{display:flex;align-items:center;gap:8px;border:1px solid var(--line);background:var(--field,var(--bg));border-radius:12px;padding:0 10px;min-height:44px;color:var(--muted);transition:border-color .15s,box-shadow .15s}
.us-search:focus-within{border-color:color-mix(in srgb,var(--accent) 55%,var(--line));box-shadow:0 0 0 3px var(--us-glow)}
.us-search svg{width:18px;height:18px;flex:none}
.us-search input{border:0!important;background:none!important;padding:8px 0!important;min-width:0;flex:1;color:var(--ink);box-shadow:none!important;outline:none}
.us-cats{display:grid;gap:4px}
.us-cat{display:flex;align-items:center;gap:12px;border:0;background:none;color:var(--ink);text-align:left;border-radius:12px;padding:10px;cursor:pointer;min-height:44px;width:100%;transition:background .15s,box-shadow .15s}
.us-cat:hover{background:color-mix(in srgb,var(--accent) 7%,transparent)}
.us-cat:focus-visible{outline:2px solid var(--accent);outline-offset:1px}
.us-ic{flex:none;display:grid;place-items:center;width:34px;height:34px;border-radius:10px;color:var(--accent);background:color-mix(in srgb,var(--accent) 11%,var(--surface))}
.us-ic svg{width:19px;height:19px}
.us-ct{flex:1;min-width:0;display:grid;gap:1px}
.us-ct b{font:600 .95rem var(--display)}
.us-cs{font-size:.78rem;color:var(--muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.us-chev{flex:none;color:var(--muted);display:grid;place-items:center}
.us-chev svg{width:16px;height:16px}
.us-pane{display:none}
.us-pane.on{display:block}
.us-title{display:flex;align-items:center;gap:12px;margin:2px 0 8px}
.us-title h3{margin:0;font:700 1.08rem var(--display)}
.us-title p{margin:1px 0 0}
.us-pane .menu-list{gap:2px}
.us-pane .menu-list > button{width:100%;border-radius:0;padding-inline:8px;transition:background .15s}
.us-pane .menu-list > button:hover{background:color-mix(in srgb,var(--accent) 6%,transparent)}
.us-pane .menu-list > .cap-row{padding-inline:8px}
.us-pane .menu-list > :last-child{border-bottom:0}
.us-pane .us-danger{margin-top:14px;border-top:1px solid var(--line)}
.us-subs{display:flex;gap:4px;padding:4px;margin:0 0 10px;background:var(--soft);border:1px solid var(--line);border-radius:12px;overflow-x:auto;scrollbar-width:none}
.us-subs::-webkit-scrollbar{display:none}
.us-sub-tab{flex:1 0 auto;border:0;background:transparent;border-radius:9px;padding:8px 12px;font:600 .86rem var(--display);color:var(--muted);white-space:nowrap;min-height:38px;cursor:pointer}
.us-sub-tab[aria-selected=true]{background:var(--surface);color:var(--ink);box-shadow:var(--shadow)}
.us-sub-tab:focus-visible{outline:2px solid var(--accent);outline-offset:1px}
.us-pane.has-subs .us-sub{display:none}
.us-pane.has-subs .us-sub.on{display:grid}
.us.searching .us-subs{display:none}
.us.searching .us-pane.has-subs .us-sub{display:grid}
.us-pane > p.summary-sub{margin:14px 8px 4px;font-size:.82rem!important;line-height:1.45}
.us-miss{display:none!important}
.us-empty{margin:24px 8px;color:var(--muted);text-align:center}
/* searching: every category with a match, one after another */
.us.searching .us-pane{display:none}
.us.searching .us-pane.us-hit{display:block;margin-bottom:14px}

/* Wide screens: categories on the left, the chosen one on the right */
@media (min-width:720px){
  dialog:has(.us-sheet){width:min(900px,calc(100% - 32px));height:min(680px,90vh)}
  .us-sheet{height:100%}
  .us-sheet .sheet-body{flex:1;min-height:0;overflow:hidden;padding:0}
  .us{display:grid;grid-template-columns:268px minmax(0,1fr);height:100%}
  .us-nav{display:flex;flex-direction:column;gap:12px;padding:14px 12px;border-right:1px solid var(--line);overflow:auto;background:color-mix(in srgb,var(--soft,var(--bg)) 45%,var(--surface))}
  .us-cat{padding:8px 10px}
  .us-cat .us-cs,.us-cat .us-chev{display:none}
  .us-cat[aria-selected="true"]{background:var(--surface);box-shadow:0 1px 2px rgba(8,20,50,.06),0 0 0 1px color-mix(in srgb,var(--accent) 22%,var(--line)),0 4px 16px var(--us-glow)}
  .us-cat[aria-selected="true"] .us-ic{background:var(--accent);color:var(--accent-ink,#fff)}
  .us.searching .us-cat{opacity:.5}
  .us.searching .us-cat.us-has{opacity:1}
  .us.searching .us-cat[aria-selected="true"]{box-shadow:none;background:none}
  .us.searching .us-cat[aria-selected="true"] .us-ic{background:color-mix(in srgb,var(--accent) 11%,var(--surface));color:var(--accent)}
  .us-main{overflow:auto;padding:16px 20px 20px;overscroll-behavior:contain}
}

/* Phones: a list of categories, then a category page with a Back button */
@media (max-width:719px){
  .us-sheet .sheet-body{padding-bottom:calc(16px + env(safe-area-inset-bottom,0px))}
  .us-nav{display:grid;gap:12px}
  .us-cat{padding:10px 8px;border:1px solid var(--line);background:var(--surface);border-radius:14px;min-height:60px}
