  .us[data-view="cat"] .us-nav{display:none}
  .us[data-view="cat"] .us-title{display:none}
  .us-sheet:has(.us[data-view="cat"]:not(.searching)) .us-back{display:grid}
  .us.searching .us-cats{display:none}
  .us.searching .us-main{display:block}
  .us.searching .us-nav{display:grid}
  .us.searching .us-title{display:flex}
  .us-back svg{width:20px;height:20px}
}
@media (prefers-reduced-motion:reduce){.us-cat,.us-search,.us-pane .menu-list > button{transition:none}}


/* ===== module: 98-companion.css ===== */
/* Study Companions: it sits in its own spot just left of the Add Task button, in front of the page (never over content:
   pages keep that bottom corner free for the button). Only the companion itself takes clicks. */
.cp-layer{position:fixed;inset:0;z-index:-1;pointer-events:none}
.cp-front .cp{position:absolute;pointer-events:none;touch-action:none;transition:opacity .2s ease,scale .25s ease}
/* Stepping aside for a toast: it fades and shrinks in place (it never slides, so it is never even briefly off screen) */
.cp-front .cp.cp-duck{opacity:0;scale:.8}
.cp-front .cp.cp-duck .cp-hit,.cp-front .cp-hit.cp-hit-off{pointer-events:none}
/* The placement guard (SBCOMP.clamp) reads the safe area through this probe: env() insets, or --sb-sai-top/right/bottom/left when set (tests, native shells) */
.cp-probe{position:fixed;left:0;top:0;width:0;height:0;box-sizing:content-box;visibility:hidden;pointer-events:none;padding:var(--sb-sai-top,env(safe-area-inset-top,0px)) var(--sb-sai-right,env(safe-area-inset-right,0px)) var(--sb-sai-bottom,env(safe-area-inset-bottom,0px)) var(--sb-sai-left,env(safe-area-inset-left,0px))}
.cp-front .cp-hit{position:absolute;left:10%;right:10%;top:4%;bottom:0;border-radius:46% 46% 40% 40%;pointer-events:auto;cursor:pointer;outline:none;-webkit-tap-highlight-color:transparent;touch-action:none}
.cp-front .cp-hit:focus-visible{box-shadow:0 0 0 3px color-mix(in srgb,var(--accent) 60%,transparent)}
/* Pages keep 120 px free at the bottom for the Add Task button; on phones the button sits higher, so leave room for both */
@media (max-width:639px){body.cp-on .wrap{padding-bottom:170px}}
.cp-front .cp-breathe{animation:cpBreathe 3.6s ease-in-out infinite}
.cp-front .cp.cp-float .cp-breathe{animation:cpFloat 3.4s ease-in-out infinite}
.cp-front .cp.cp-float .cp-shadow{animation:cpShadow 3.4s ease-in-out infinite}
.cp-front .cp.cp-doze .cp-breathe{animation-duration:5.2s}
.cp-front.cp-still .cp-breathe,.cp-front.cp-still .cp-shadow{animation:none!important}
.cp-front.cp-paused *{animation-play-state:paused!important}
html.cp-hover{cursor:pointer}
.cp-move,.cp-breathe{position:absolute;inset:0;display:block;transform-origin:50% 93%;will-change:transform}
.cp-svg{position:absolute;inset:0;width:100%;height:100%;overflow:visible;display:block}
.cp-shadow{position:absolute;left:24%;right:24%;bottom:4%;height:7%;border-radius:50%;background:radial-gradient(closest-side,rgba(28,20,40,.26),rgba(28,20,40,0));display:block}
.cp-float .cp-shadow,.cp-prev.cp-float .cp-shadow{left:32%;right:32%;bottom:2%;opacity:.7}
/* Soft glow that helps it read on busy and dark scenes */
.cp-front .cp-svg{filter:drop-shadow(0 0 1.5px rgba(255,255,255,.85)) drop-shadow(0 2px 5px rgba(30,20,50,.18))}
.cp-front.cp-dark .cp-svg{filter:drop-shadow(0 0 1.5px rgba(255,255,255,.35)) drop-shadow(0 0 9px rgba(255,236,200,.22))}
/* Idle breathing (stand and sit) and hovering (float): the only always-on motion, on a composited layer */
@keyframes cpBreathe{0%,100%{transform:scale(1,1)}50%{transform:scale(1.012,1.028)}}
@keyframes cpFloat{0%,100%{transform:translateY(0)}50%{transform:translateY(-5px)}}
@keyframes cpShadow{0%,100%{transform:scaleX(1);opacity:.7}50%{transform:scaleX(.82);opacity:.5}}
.cp-front .cp-loved .cp-cheeks{opacity:1}
/* Rig states */
.cp-svg .cp-p,.cp-svg .cp-headg,.cp-svg .cp-eye,.cp-svg .cp-page{transform-box:view-box}
.cp-svg .cp-look{transition:transform .28s ease-out}
.cp-svg .cp-cheeks{opacity:.62;transition:opacity .3s}
.cp-svg .cp-e-happy,.cp-svg .cp-e-sleepy,.cp-svg .cp-mouth>g,.cp-svg .cp-prop,.cp-svg .cp-zs{display:none}
.cp-svg[data-e=happy] .cp-eye,.cp-svg[data-e=sleepy] .cp-eye{display:none}
.cp-svg[data-e=happy] .cp-e-happy,.cp-svg[data-e=sleepy] .cp-e-sleepy{display:inline}
.cp-svg[data-e=blink] .cp-eye{transform:scaleY(.1)}
.cp-svg[data-m=neutral] .cp-m-neutral,.cp-svg[data-m=smile] .cp-m-smile,.cp-svg[data-m=open] .cp-m-open,.cp-svg[data-m=sleepy] .cp-m-sleepy{display:inline}
.cp-svg[data-prop=book] .cp-prop{display:inline}
.cp-still .cp-doze .cp-zs{display:inline}
/* Hearts, sparkles and z's */
.cp-fx{position:absolute;inset:0;pointer-events:none;overflow:visible}
.cp-pt{position:absolute;display:block;animation:cpUp 1.5s ease-out both}
.cp-pt svg{width:100%;height:100%;display:block;overflow:visible}
.cp-pt.cp-pt-still{animation:cpFade 1.6s ease-out both}
@keyframes cpUp{0%{opacity:0;transform:translate(0,6px) scale(.4) rotate(0)}18%{opacity:1;transform:translate(calc(var(--dx)*.3),-4px) scale(1.05) rotate(calc(var(--r)*.4))}100%{opacity:0;transform:translate(var(--dx),-34px) scale(.9) rotate(var(--r))}}
@keyframes cpFade{0%{opacity:0}20%{opacity:1}75%{opacity:1}100%{opacity:0}}
/* Speech bubble, in front of the page but it never takes clicks */
.cp-front{position:fixed;inset:0;z-index:7;pointer-events:none}
.cp-bubble{position:absolute;left:0;top:0;box-sizing:border-box;padding:8px 13px;border-radius:16px;background:var(--surface);color:var(--ink);font:600 .86rem/1.3 var(--display);box-shadow:0 6px 20px rgba(20,14,40,.18),0 0 0 1.5px color-mix(in srgb,var(--cp-wear,var(--accent)) 35%,var(--line));opacity:0;transform:translateY(6px) scale(.96);transform-origin:var(--tx,50%) 100%;transition:opacity .22s ease,transform .26s cubic-bezier(.3,1.4,.5,1);text-wrap:balance;width:max-content;text-align:center}
.cp-bubble::after{content:"";position:absolute;left:var(--tx,50%);bottom:-6px;width:12px;height:12px;margin-left:-6px;background:inherit;transform:rotate(45deg);border-radius:0 0 3px 0;box-shadow:1.5px 1.5px 0 0 color-mix(in srgb,var(--cp-wear,var(--accent)) 35%,var(--line))}
.cp-bubble.below{transform-origin:var(--tx,50%) 0}
.cp-bubble.below::after{bottom:auto;top:-6px;border-radius:3px 0 0 0;box-shadow:-1.5px -1.5px 0 0 color-mix(in srgb,var(--cp-wear,var(--accent)) 35%,var(--line))}
.cp-bubble.on{opacity:1;transform:none}
span.cp-ai-face.ai-ic{display:inline-block;position:relative;width:1.45em;height:1.45em;min-width:1.45em;vertical-align:-.38em;flex:none;margin:0 .12em 0 0;line-height:0;color:inherit}
.cp-ai-face>svg.cp-svg{position:absolute;inset:0;width:100%!important;height:100%!important;overflow:visible;display:block;filter:drop-shadow(0 1px 1.5px rgba(30,20,50,.18))}   /* (always fills its space: rules that size a button's icons don't shrink the face inside it) */
/* In a button the companion is a little bigger than the text, centred on it, without making the button taller */
.btn span.cp-ai-face.ai-ic{width:1.7em;height:1.7em;min-width:1.7em;margin:-.3em .24em -.3em -.12em;vertical-align:middle;top:-.2em}
.btn:is([style*="flex"],.f-sum) span.cp-ai-face.ai-ic,.frow > .f-sum span.cp-ai-face.ai-ic{margin:-.3em 0;top:-.14em}
.nu-who{font-weight:600;opacity:.85}
.cp-bubble.right{transform:translateX(-6px) scale(.96);transform-origin:0 var(--ty,50%)}
.cp-bubble.right.on{transform:none}
.cp-bubble.right::after{left:-6px;top:var(--ty,50%);bottom:auto;margin:-6px 0 0 0;border-radius:0 0 0 3px;box-shadow:-1.5px 1.5px 0 0 color-mix(in srgb,var(--cp-wear,var(--accent)) 35%,var(--line))}
.cp-bubble.has-idea.on{pointer-events:auto}
.cp-bubble .cp-b-t{display:block}
.cp-bubble .cp-b-acts{display:flex;gap:6px;justify-content:center;margin-top:8px;flex-wrap:wrap}
.cp-bubble .cp-b-acts .btn{min-height:34px;font-size:.8rem}
.cp-bubble.asking{pointer-events:auto;padding:8px}
.cp-ask{display:flex;gap:6px;align-items:center}
.cp-ask input{flex:1;min-width:0;width:200px;font:500 .86rem var(--body);padding:7px 10px;border-radius:10px;border:1px solid var(--line);background:var(--field,var(--surface));color:var(--ink)}
.cp-ask-hint{display:block;font:500 .7rem var(--body);color:var(--muted);margin-top:5px;text-align:left}
.cp-use{display:block;margin-top:4px;font:600 .78rem var(--display);color:var(--accent)}
.cp-thinking{display:flex;gap:4px;justify-content:center;padding:4px 6px}
