.ph-tall .ph-card{border-radius:6cqw;padding:6cqw;gap:4.5cqw}
.ph-tall .ph-row{font-size:7.2cqw;gap:4cqw}
.ph-tall .ph-ck{width:7cqw;height:7cqw;border-width:1.3cqw}
.ph-tall .ph-btn{font-size:6.5cqw;padding:2.6cqw 6cqw}
.ph-tall .ph-note{width:60cqw;min-height:40cqw;font-size:6.5cqw;padding:6cqw 5cqw;box-shadow:0 3cqw 5cqw rgba(40,25,5,.25)}
.ph-bar{margin-top:auto;height:15cqw;background:var(--spine-bg,var(--spine));display:flex;align-items:center;justify-content:space-around;padding:0 4cqw}
.ph-bar i{width:7cqw;height:7cqw;border-radius:2cqw;background:var(--spine-ink);opacity:.55}
.ph-bar i.on{background:var(--accent);opacity:1}
.ph-prevbar{display:flex;align-items:center;gap:10px;flex-wrap:wrap}
.ph-prevbar .segb button{min-height:36px;min-width:64px}
.ph-read{display:inline-flex;align-items:center;gap:6px;font:600 .82rem var(--display);color:var(--ink);background:var(--soft);border:1px solid var(--line);border-radius:99px;padding:4px 12px}
.ph-read i{font-style:normal;color:#1C8C4E;font-weight:800}
.ph-tip{font-weight:500;color:var(--muted);padding-left:8px;margin-left:2px;border-left:1px solid var(--line)}
.ph-focus-wrap.f{margin:0}
.ph-sheet div.f{display:grid;gap:5px;font-size:.88rem;font-weight:600}
.ph-sheet div.f .lh{display:flex;flex-wrap:wrap;align-items:baseline;gap:0 6px}
.ph-sheet div.f .hint{font-weight:400;color:var(--muted)}
.ph-made .mini{margin-right:2px;font-weight:500}
.ph-card{background:color-mix(in srgb,var(--surface) var(--ph-gl,100%),transparent);-webkit-backdrop-filter:blur(var(--ph-glb,0px));backdrop-filter:blur(var(--ph-glb,0px))}
.ph-fx{display:grid;gap:8px}
.ph-grp{border:1px solid var(--line);border-radius:12px;background:var(--surface)}
.ph-grp>summary{cursor:pointer;list-style:none;padding:10px 14px;font:700 .92rem var(--display);display:flex;align-items:center;gap:8px;min-height:44px;border-radius:12px}
.ph-grp>summary::-webkit-details-marker{display:none}
.ph-grp>summary::after{content:"";margin-left:auto;width:8px;height:8px;border:solid var(--muted);border-width:0 2px 2px 0;transform:rotate(45deg);transition:transform .15s}
.ph-grp[open]>summary::after{transform:rotate(-135deg)}
.ph-grp>summary:focus-visible{outline:2px solid var(--accent);outline-offset:-2px}
.ph-grp>summary .hint{font:400 .8rem var(--body);color:var(--muted)}
.ph-grp-b{display:grid;gap:12px;padding:2px 14px 14px}
.ph-grp-b .f{display:grid;gap:5px;font-size:.88rem;font-weight:600;margin:0}
.ph-grp-b .f .hint{font-weight:400;color:var(--muted)}
.ph-grp-b input[type=range]{min-height:32px}
.ph-own{display:flex;gap:8px;align-items:center;flex-wrap:wrap}
.ph-own input[type=color],.ph-stops input[type=color],.ph-tintrow input[type=color]{width:44px;height:40px;padding:2px;border-radius:10px;border:1px solid var(--line);background:var(--field,var(--surface));cursor:pointer}
.ph-own input[type=text]{width:7.5em;min-height:40px;border-radius:10px;border:1px solid var(--line);background:var(--field,var(--surface));color:var(--ink);padding:0 10px;font:600 .88rem ui-monospace,monospace;text-transform:uppercase}
.ph-own input[type=text][aria-invalid=true]{border-color:var(--late)}
.ph-gprev{height:54px;border-radius:12px;box-shadow:inset 0 0 0 1px rgba(0,0,0,.12)}
.ph-presets{display:flex;flex-wrap:wrap;gap:8px}
.ph-cps{display:grid;gap:8px;max-height:min(440px,60vh);overflow:auto;padding:2px;overscroll-behavior:contain}
.ph-cpmine{display:flex;flex-wrap:wrap;align-items:center;gap:6px;font-size:.8rem}
.ph-cpmine b{font:700 .8rem var(--display)}
.ph-cpmine .chip{display:inline-flex;align-items:center;gap:4px;padding:3px 10px;border-radius:999px;background:var(--soft);border:1px solid var(--line)}
.ph-cpg{content-visibility:auto;contain-intrinsic-size:auto 46px;border:1px solid var(--line);border-radius:12px;background:var(--surface)}
.ph-cpg>summary{display:flex;align-items:center;gap:8px;padding:9px 12px;min-height:44px;cursor:pointer;font:700 .88rem var(--display);list-style:none}
.ph-cpg>summary::-webkit-details-marker{display:none}
.ph-cpg>summary::after{content:"▾";margin-left:auto;color:var(--muted);transition:transform .2s}
.ph-cpg[open]>summary::after{transform:rotate(180deg)}
.ph-cpg .n{font:600 .72rem var(--body);color:var(--muted)}
.ph-cpgrid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px;padding:0 10px 10px}
.ph-cp{display:grid;justify-items:center;gap:2px;padding:6px 4px;border:1px solid var(--line);border-radius:12px;background:var(--surface);color:var(--ink);cursor:pointer;font:inherit;min-width:0}
.ph-cp.on{border-color:var(--accent);box-shadow:0 0 0 2px var(--accent)}
.ph-cp.locked{opacity:.6}
.ph-cp-art{position:relative;width:56px;height:56px;display:block}.ph-cp-art img{width:100%;height:100%;display:block;pointer-events:none}.ph-cp-art svg,.ph-cp-art .cp-svg{position:relative;inset:auto;width:100%;height:100%;display:block;overflow:visible}
.ph-cp-n{font-size:.78rem;font-weight:600;line-height:1.15;text-align:center;max-width:100%;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.ph-cp-t{font-size:.66rem;opacity:.7;text-align:center;max-width:100%;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.ph-pre{width:44px;height:44px;border-radius:12px;border:3px solid var(--surface);box-shadow:0 0 0 1px var(--line);cursor:pointer;padding:0}
.ph-pre:hover{transform:scale(1.06)}
.ph-pre:focus-visible{outline:2px solid var(--accent);outline-offset:3px}
.ph-stops,.ph-tintrow{display:flex;gap:8px;align-items:center;flex-wrap:wrap}
.ph-tintrow select{min-height:40px;border-radius:10px;border:1px solid var(--line);background:var(--field,var(--surface));color:var(--ink);padding:0 10px;font:600 .88rem var(--body)}
.ph-grp-b .segb button{min-height:38px}
.ph-grp-b [hidden],.ph-stops [hidden]{display:none!important}
.ph-sug{display:flex;flex-wrap:wrap;gap:8px;align-items:center}
@media (prefers-reduced-motion:reduce){.ph-grp>summary::after,.ph-pre:hover{transition:none;transform:none}}
.ph-ctl{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:18px;align-items:start}
.ph-focus-wrap{display:grid;gap:8px;justify-items:center}
.ph-focus-wrap > .lh{justify-self:start}
.ph-focus{position:relative;width:100%;max-height:260px;border-radius:10px;overflow:hidden;touch-action:none;cursor:crosshair;user-select:none;-webkit-user-select:none;background:var(--soft);box-shadow:0 0 0 1px var(--line)}
.ph-focus img{position:absolute;inset:0;width:100%;height:100%;display:block;pointer-events:none;-webkit-user-drag:none}
.ph-crop{position:absolute;box-sizing:border-box;pointer-events:none;border-radius:3px;transition:left .08s,top .08s}
.ph-crop.wide{border:2px solid #fff;box-shadow:0 0 0 1px rgba(0,0,0,.45),0 0 0 9999px rgba(0,0,0,.28)}
.ph-crop.tall{border:2px dashed #FFD84D;box-shadow:0 0 0 1px rgba(0,0,0,.45)}
.ph-dot{position:absolute;width:24px;height:24px;margin:-12px 0 0 -12px;border-radius:50%;background:rgba(255,255,255,.25);border:3px solid #fff;box-shadow:0 0 0 1.5px rgba(0,0,0,.55),0 2px 8px rgba(0,0,0,.4);cursor:grab}
.ph-dot::after{content:"";position:absolute;left:50%;top:50%;width:6px;height:6px;margin:-3px 0 0 -3px;border-radius:50%;background:#fff}
.ph-dot:focus-visible{outline:3px solid var(--accent);outline-offset:3px}
.ph-legend{display:flex;gap:14px;margin:0;justify-self:start;font-weight:500}
.ph-legend span{display:inline-flex;align-items:center;gap:6px}
.ph-legend .k{display:inline-block;width:18px;height:11px;border-radius:2px;background:rgba(0,0,0,.28)}
.ph-legend .k.wide{border:2px solid #fff;box-shadow:0 0 0 1px rgba(0,0,0,.5)}
.ph-legend .k.tall{border:2px dashed #E0B400;background:none}
.ph-fields{display:grid;gap:12px}
.ph-fields .f{margin:0}
.ph-fields input[type=range]{min-height:32px}
.ph-sw{display:flex;flex-wrap:wrap;gap:8px;align-items:center;margin-top:4px}
.ph-swb{min-width:40px;min-height:40px;border-radius:50%;border:3px solid var(--surface);box-shadow:0 0 0 1px var(--line);cursor:pointer;padding:0}
.ph-swb.c{width:40px;height:40px;background:var(--c)}
.ph-swb.auto{border-radius:99px;padding:0 14px;background:var(--field,var(--surface));color:var(--ink);font:600 .82rem var(--display);border-width:1px;border-color:var(--line);box-shadow:none}
.ph-swb[aria-pressed="true"]{box-shadow:0 0 0 2.5px var(--ink)}
.ph-swb.auto[aria-pressed="true"]{background:var(--sel);color:var(--sel-ink,#fff);border-color:var(--sel)}
.ph-swb:focus-visible{outline:2px solid var(--accent);outline-offset:3px}
.ph-made{display:flex;gap:6px;align-items:center;flex-wrap:wrap}
.ph-mk{width:26px;height:26px;border-radius:7px;box-shadow:inset 0 0 0 1px rgba(0,0,0,.1)}
.ph-mk.acc{background:var(--accent);border-radius:50%}
.ph-mk.btn{width:44px;background:var(--btn-bg,var(--accent));border-radius:var(--btn-r,8px)}
.ph-mk.nt{width:22px;height:22px;border-radius:3px;transform:rotate(-3deg)}
.ph-mk.fc{width:32px;background:var(--tc-bg);border:2px solid var(--tc-bd)}
@media (max-width:640px){
  .ph-ctl{grid-template-columns:1fr;gap:14px}
  .ph-stage{gap:8px}
  .ph-focus{max-height:220px}
}


/* ===== module: 98-rooms.css ===== */
/* Study Together rooms (98-rooms) */
.room-sec{position:relative;margin:18px 0 4px}
.room-card{position:relative;background:var(--surface);border:1px solid var(--line);border-radius:16px;box-shadow:var(--shadow);padding:14px 16px;overflow:hidden}
.room-card.is-live,.room-card.is-in,.room-card.is-moment{border-color:color-mix(in srgb,var(--accent) 38%,var(--line));background:linear-gradient(180deg,color-mix(in srgb,var(--accent) 7%,var(--surface)),var(--surface) 70%)}
.room-idle{display:flex;align-items:center;gap:12px;flex-wrap:wrap}
.room-ic{flex:none;display:grid;place-items:center;width:40px;height:40px;border-radius:12px;background:color-mix(in srgb,var(--accent) 14%,var(--surface));color:var(--accent)}
.room-ic svg{width:22px;height:22px}
.room-idle-txt{flex:1 1 220px;min-width:0;display:flex;flex-direction:column;gap:2px}
.room-idle-txt b{font:700 1.02rem var(--display)}
.room-idle-txt .mini{display:flex;align-items:center;gap:6px}
.room-err{margin:10px 0 0;color:var(--late);font-size:.88rem}
.room-sec .mini{color:var(--muted);font-size:.8rem}

/* Live (not joined) */
.room-top{display:flex;align-items:center;gap:8px;flex-wrap:wrap}
.room-top b{font:700 1rem var(--display)}
.room-top .spacer{flex:1}
.room-left-sm{font-size:.86rem;color:var(--muted)}
.room-left-sm b{font:700 1.05rem var(--display);font-variant-numeric:tabular-nums;color:var(--ink)}
.room-dot{flex:none;width:9px;height:9px;border-radius:50%;background:#1E9E74;box-shadow:0 0 0 0 color-mix(in srgb,#1E9E74 55%,transparent);animation:roomPulse 2.4s ease-out infinite}
@keyframes roomPulse{0%{box-shadow:0 0 0 0 color-mix(in srgb,#1E9E74 55%,transparent)}70%,100%{box-shadow:0 0 0 7px transparent}}
.room-goal{margin:8px 0 0;font-size:.92rem;overflow-wrap:anywhere}
.room-goal .mini{display:inline-block;margin-right:6px;font-weight:600;text-transform:uppercase;letter-spacing:.05em;font-size:.68rem}
.room-join{display:flex;gap:8px;margin-top:12px}
.room-join input{flex:1;min-width:0;min-height:44px}
.room-join .btn{min-height:44px;min-width:92px}
.room-seats{margin:8px 0 0}
.room-none{margin:10px 0 0;color:var(--muted);font-size:.88rem}

/* People */
.room-people{list-style:none;margin:10px 0 0;padding:0;display:flex;flex-wrap:wrap;gap:6px 8px}
.room-person{display:flex;align-items:center;gap:7px;min-width:0;background:color-mix(in srgb,var(--soft) 70%,transparent);border-radius:999px;padding:3px 10px 3px 3px;font-size:.86rem}
.room-person.more{padding:3px}
.room-person.is-me{background:color-mix(in srgb,var(--accent) 14%,transparent)}
.room-pn{display:flex;flex-direction:column;min-width:0;line-height:1.2}
.room-pn b{font-weight:600;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:14em}
.room-pg{color:var(--muted);font-size:.78rem;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:16em}
.room-av{flex:none;display:inline-grid;place-items:center;width:32px;height:32px;border-radius:50%;background:var(--c,#8A94A6);color:#fff;font:700 .74rem var(--display);letter-spacing:.02em;overflow:hidden}
.room-av.more{background:var(--soft);color:var(--muted)}
.room-av.is-comp{background:color-mix(in srgb,var(--accent) 12%,var(--surface));border:1px solid var(--line)}
.room-av.is-comp{position:relative;overflow:hidden}
.room-av.is-comp > svg{position:absolute;left:4%;top:12%;width:92%;height:92%;display:block;overflow:visible;filter:none}
.room-people.big{flex-direction:column;flex-wrap:nowrap;gap:6px}
.room-people.big .room-person{border-radius:14px;padding:5px 12px 5px 5px}
.room-people.big .room-av{width:44px;height:44px;font-size:.9rem}
.room-people.big .room-pn b{max-width:none}
.room-people.big .room-pg{white-space:normal;max-width:none}

/* In the room */
.room-main{display:flex;gap:22px;align-items:center}
.room-dial{position:relative;flex:none;width:170px;height:170px}
.room-dial svg{width:100%;height:100%;transform:rotate(-90deg)}
.room-dial .track{fill:none;stroke:color-mix(in srgb,var(--accent) 14%,var(--line));stroke-width:7}
.room-dial .bar{fill:none;stroke:var(--accent);stroke-width:7;stroke-linecap:round;transition:stroke-dashoffset 1s linear}
.room-read{position:absolute;inset:0;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center}
.room-time{font:700 2.3rem/1 var(--display);font-variant-numeric:tabular-nums;color:var(--ink)}
.room-lbl{margin-top:6px;font-size:.76rem;color:var(--muted);font-weight:600}
.room-side{flex:1;min-width:0}
.room-title{margin:0;display:flex;flex-direction:column;gap:2px}
.room-title b{font:700 1.15rem var(--display)}
.room-cheers{display:flex;justify-content:center;gap:8px;margin-top:14px;flex-wrap:wrap}
.room-cheer{width:48px;height:48px;border-radius:50%;border:1px solid var(--line);background:var(--surface);font-size:1.35rem;line-height:1;display:grid;place-items:center;box-shadow:0 1px 2px rgba(0,0,0,.06);transition:transform .15s ease,background .15s ease}
.room-cheer:hover{background:color-mix(in srgb,var(--accent) 10%,var(--surface));transform:translateY(-2px)}
.room-cheer:active{transform:scale(.92)}
.room-foot{display:flex;align-items:center;gap:10px;margin-top:14px;flex-wrap:wrap}
.room-foot .spacer{flex:1}
.room-end{color:var(--late)}
.room-note{margin:10px 0 0}

/* Floating cheers */
.room-floats{position:absolute;inset:0;pointer-events:none;overflow:hidden;border-radius:16px}
.room-float{position:absolute;left:var(--x,50%);bottom:40px;display:flex;flex-direction:column;align-items:center;gap:2px;animation:roomFloat 2.9s cubic-bezier(.2,.7,.3,1) forwards}
.room-float .e{font-size:1.9rem;line-height:1;filter:drop-shadow(0 2px 4px rgba(0,0,0,.15))}
.room-float small{font:600 .7rem var(--display);color:var(--ink);background:color-mix(in srgb,var(--surface) 85%,transparent);border-radius:999px;padding:1px 7px;white-space:nowrap}
@keyframes roomFloat{0%{transform:translate(0,10px) scale(.6);opacity:0}12%{opacity:1;transform:translate(0,0) scale(1.05)}100%{transform:translate(var(--dx,0),-190px) scale(1);opacity:0}}
.room-float.still{animation:roomFade 2.6s ease forwards;bottom:70px}
@keyframes roomFade{0%{opacity:0}12%,75%{opacity:1}100%{opacity:0}}
@media (prefers-reduced-motion:reduce){.room-float{animation:roomFade 2.6s ease forwards}.room-dot{animation:none}.room-dial .bar{transition:none}.room-spark{animation:none}}

/* The shared moment */
.room-moment{text-align:center;padding:8px 4px 4px}
.room-moment h3{margin:4px 0 6px;font:700 1.35rem/1.25 var(--display)}
.room-names{margin:0 0 6px;font-weight:600;overflow-wrap:anywhere}
.room-moment .mini{margin:4px 0}
.room-spark{display:inline-block;font-size:2rem;animation:roomSpark 2.4s ease-in-out infinite}
@keyframes roomSpark{0%,100%{transform:scale(1) rotate(0)}50%{transform:scale(1.12) rotate(8deg)}}
.room-break{margin:10px 0 4px;font-size:.92rem;color:var(--muted)}
.room-break b{font:700 1.05rem var(--display);color:var(--ink);font-variant-numeric:tabular-nums;margin-left:4px}
.room-moment .row-actions{justify-content:center;margin-top:10px}

/* Groups list: banner and card pill */
.room-banners{display:flex;flex-direction:column;gap:8px;margin:12px 0 4px}
.room-banner{display:flex;align-items:center;gap:10px;background:color-mix(in srgb,var(--accent) 8%,var(--surface));border:1px solid color-mix(in srgb,var(--accent) 30%,var(--line));border-radius:12px;padding:8px 10px 8px 12px}
.room-banner-txt{flex:1;min-width:0;font-size:.9rem}
.room-banner .btn{flex:none}
.room-live-pill{display:inline-flex;align-items:center;gap:6px;margin-top:4px;font-size:.76rem;font-weight:700;color:#177A5A;background:color-mix(in srgb,#1E9E74 14%,transparent);border-radius:999px;padding:2px 9px 2px 7px;width:max-content}
:root[data-theme="dark"] .room-live-pill{color:#6FD3AE}

/* A small chip while you're in a session (phones and tablets), and the time on the Groups button (desktop sidebar) */
.room-pill{position:fixed;left:14px;bottom:calc(98px + env(safe-area-inset-bottom,0px));z-index:30;height:44px;display:flex;align-items:center;gap:6px;padding:0 12px 0 10px;border:1px solid color-mix(in srgb,var(--accent) 45%,var(--line));background:color-mix(in srgb,var(--accent) 12%,var(--surface));border-radius:999px;color:var(--accent);font:700 .9rem var(--display);font-variant-numeric:tabular-nums;box-shadow:var(--shadow)}
.room-pill svg{width:19px;height:19px;flex:none}
.room-pill span{color:var(--ink)}
@media (min-width:980px){.room-pill{display:none}}
.nav-groups .room-navtime{display:block;font:700 .7rem var(--display);font-variant-numeric:tabular-nums;opacity:.9}

.room-lens .is-locked span{opacity:.6}
.room-lens .is-locked .pro-badge{margin-left:3px;vertical-align:1px}
.room-lens label span{display:inline-flex;align-items:center;justify-content:center;gap:4px;white-space:nowrap}
.room-lens .is-locked .pro-badge{margin-left:0;vertical-align:0}

@media (max-width:600px){
  .room-card{padding:12px}
  .room-main{flex-direction:column;align-items:stretch;gap:12px}
  .room-dial{width:150px;height:150px;margin:0 auto}
  .room-time{font-size:2rem}
  .room-join{flex-direction:column}
  .room-join .btn{width:100%}
  .room-cheer{width:46px;height:46px}
  .room-lens span{font-size:.8rem}
}


/* ===== module: 98-scrapbook.css ===== */
/* Term Scrapbook (module 98-scrapbook) */
.sbk{--sbk-side:340px}
.sbk-head .sbk-pick select{font:600 .9rem var(--body,inherit);padding:7px 30px 7px 10px;border-radius:10px;border:1px solid var(--line);background:var(--field,var(--surface));color:var(--ink);min-height:36px;max-width:60vw}
.sbk-tools{display:flex;flex-wrap:wrap;gap:8px;margin:12px 0 10px}
.sbk-tools .btn{display:inline-flex;align-items:center;gap:6px}
.sbk-tools .pro-badge{font-size:.55rem;padding:1px 5px}
.sbk-tools .sbk-mbtn,.sbk-tools .sbk-zoombtn{display:none}
.sbk-main{display:grid;grid-template-columns:minmax(0,1fr) var(--sbk-side);gap:18px;align-items:start}
.sbk-stage{position:relative;min-width:0}
.sbk-scroll{border-radius:10px}
.sbk-paper{position:relative;width:100%;max-width:820px;margin:0 auto;container-type:inline-size;background-color:#FBF3E1;background-size:100% 100%;background-repeat:no-repeat;border-radius:6px;box-shadow:0 1px 0 rgba(255,255,255,.5) inset,0 2px 4px rgba(40,25,5,.12),0 14px 34px rgba(40,25,5,.18);overflow:hidden;touch-action:pan-y;user-select:none;-webkit-user-select:none}
.sbk.dark .sbk-paper{filter:brightness(.93);box-shadow:0 2px 4px rgba(0,0,0,.4),0 16px 40px rgba(0,0,0,.45)}
.sbk-title{position:absolute;left:0;right:0;top:4.2cqw;text-align:center;pointer-events:none;padding:0 21cqw;min-height:15cqw;display:flex;flex-direction:column;justify-content:center}
.sbk-title b{display:block;font-weight:800;font-family:var(--display);line-height:1.12;letter-spacing:-.01em;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.sbk-title span{display:block;font:600 2.5cqw/1.3 var(--display);margin-top:1.4cqw}
.sbk-empty{position:absolute;top:24cqw;left:14%;right:14%;text-align:center;font:600 2.5cqw/1.45 var(--display);margin:0;pointer-events:none;opacity:.85}
.sbk-it{position:absolute;transform:translate(-50%,-50%) rotate(var(--r,0deg));touch-action:none;cursor:grab;border-radius:10px;outline:none;-webkit-tap-highlight-color:transparent;transition:filter .15s}
.sbk-it img{width:100%;height:100%;display:block;pointer-events:none;-webkit-user-drag:none}
.sbk-f{z-index:1}.sbk-s{z-index:2}.sbk-c{z-index:3}.sbk-w{z-index:4}
.sbk-w img{opacity:.92}
.sbk-it.sel{outline:2px dashed var(--accent,#7C8CF8);outline-offset:2px;z-index:6}
.sbk-it:focus-visible{outline:3px solid var(--accent,#7C8CF8);outline-offset:3px}
.sbk-it.drag{cursor:grabbing;z-index:8;filter:drop-shadow(0 10px 12px rgba(40,25,5,.28))}
.sbk-it.hl{animation:sbkHl 1.2s ease-in-out 2}
@keyframes sbkHl{0%,100%{filter:none}50%{filter:drop-shadow(0 0 10px #FFD23F) drop-shadow(0 0 4px #FFB443)}}
.sbk-it.new img{animation:sbkPop .7s cubic-bezier(.2,.9,.3,1.35) both}
@keyframes sbkPop{0%{transform:scale(.3);opacity:0}100%{transform:none;opacity:1}}
.sbk-f.st-polaroid img{filter:drop-shadow(0 4px 6px rgba(40,25,5,.22))}
.sbk-cap-t{position:absolute;top:0;bottom:0;left:calc(4cqw * var(--s,1));right:calc(1.2cqw * var(--s,1));display:flex;align-items:center;justify-content:center;font:700 calc(2.4cqw * var(--s,1))/1 var(--display);color:#4A3522;white-space:nowrap;overflow:hidden;pointer-events:none;padding:0 2%}
.sbk-selbar{position:fixed;left:50%;bottom:18px;transform:translateX(-50%);width:min(700px,calc(100vw - 24px));z-index:60;display:flex;align-items:center;flex-wrap:wrap;gap:6px 10px;margin:0;padding:8px 10px;background:var(--surface);color:var(--ink);border:1px solid var(--line);border-radius:14px;box-shadow:0 8px 24px rgba(10,20,40,.16)}
.sbk-selbar[hidden]{display:none}
@media (min-width:720px){.sbk-selbar{left:calc(50% + 68px)}}
.sbk-selname{flex:1;min-width:120px;font-size:.92rem}
.sbk-selname .mini{margin-left:6px}
.sbk-selbtns{display:flex;flex-wrap:wrap;gap:6px;align-items:center}
.sbk-selbtns .icon-btn{min-width:44px;min-height:44px;font-size:1.15rem;font-weight:700;border:1px solid var(--line);border-radius:10px}
.sbk-sum{display:flex;flex-direction:column;gap:2px;max-width:820px;margin:0 0 12px;padding:10px 14px;border-radius:12px;background:var(--surface);border:1px solid var(--line);color:var(--ink)}
.sbk-sum span{color:var(--muted);font-size:.88rem}
.sbk-next{position:absolute;transform:translate(-50%,-50%);width:15cqw;display:flex;flex-direction:column;align-items:center;gap:.6cqw;padding:0;border:0;background:none;cursor:pointer;z-index:1;font:inherit}
.sbk-next .sbk-ghost{width:12cqw;height:12cqw;border-radius:50%;border:.35cqw dashed currentColor;opacity:.45;display:grid;place-items:center}
.sbk-next .sbk-ghost img{width:9cqw;height:9cqw;filter:grayscale(1) brightness(1.1);opacity:.5}
.sbk-next .sbk-nl{font:700 max(9px,1.7cqw)/1.2 var(--display);text-align:center;opacity:.8;white-space:nowrap}
.sbk-next:focus-visible{outline:2px solid var(--accent);outline-offset:4px;border-radius:8px}
/* Milestones list */
.sbk-side{position:sticky;top:12px;max-height:calc(100vh - 40px);overflow:auto;background:var(--surface);color:var(--ink);border:1px solid var(--line);border-radius:14px;padding:12px 12px 6px;overscroll-behavior:contain}
.sbk-side.in-sheet{position:static;max-height:none;border:0;border-radius:0;background:none;overflow:auto}
.sbk-side.in-sheet .sbk-mhead b{display:none}
.sbk-mhead{display:flex;align-items:baseline;justify-content:space-between;gap:8px;margin:0 2px 4px}
.sbk-mhead b{font:700 1rem var(--display)}
.sbk-cat{font:700 .78rem var(--display);letter-spacing:.06em;text-transform:uppercase;color:var(--muted);margin:14px 2px 6px}
.sbk-ml{list-style:none;margin:0;padding:0;display:flex;flex-direction:column;gap:4px}
.sbk-m{display:flex;gap:10px;align-items:center;padding:6px;border-radius:12px}
.sbk-m.flash{animation:sbkFlash 1.4s ease-out}
@keyframes sbkFlash{0%,40%{box-shadow:0 0 0 3px var(--accent)}100%{box-shadow:0 0 0 3px transparent}}
.sbk-m.got{background:var(--soft,rgba(0,0,0,.03))}
.sbk-mi{flex:none;width:54px;height:54px;padding:0;border:0;background:none;border-radius:12px;cursor:pointer}
.sbk-mi img{width:100%;height:100%;display:block}
.sbk-m.locked .sbk-mi{cursor:default}
.sbk-m.locked .sbk-mi img{filter:grayscale(1) contrast(.7) brightness(1.12);opacity:.38}
.sbk.dark .sbk-m.locked .sbk-mi img,html[data-theme=dark] .sbk-m.locked .sbk-mi img{opacity:.3;filter:grayscale(1) brightness(1.4)}
.sbk-mt{display:flex;flex-direction:column;gap:2px;min-width:0;flex:1}
.sbk-mt b{font-size:.92rem;line-height:1.25}
.sbk-goal{font-size:.8rem;color:var(--muted);line-height:1.3}
.sbk-pt{font-size:.78rem;color:var(--ink);opacity:.85}
.sbk-m.got .sbk-pt{color:var(--accent-2,var(--accent));opacity:1;font-weight:600}
.sbk-pbar{display:block;height:6px;border-radius:4px;background:var(--line);overflow:hidden;margin:3px 0 1px}
.sbk-pbar i{display:block;height:100%;border-radius:4px;background:linear-gradient(90deg,var(--accent,#7C8CF8),var(--accent-2,#FF8FB0))}
.sbk-paths{list-style:none;margin:6px 0 0;padding:0;display:grid;gap:5px}
.sbk-paths li{display:grid;gap:1px;font-size:.74rem}
.sbk-paths .sbk-pn{font-weight:700}
.sbk-paths li.ok .sbk-pn:after{content:" \2713";color:var(--accent-2,var(--accent))}
.sbk-paths .sbk-pbar{height:4px;margin:1px 0}
/* Sheets */
.sbk-caprow{display:flex;gap:8px}
.sbk-caprow input{flex:1;min-width:0}
.sbk-tiles{display:grid;grid-template-columns:repeat(auto-fill,minmax(132px,1fr));gap:10px}
.sbk-tiles.frames{grid-template-columns:repeat(auto-fill,minmax(104px,1fr))}
.sbk-tile{display:flex;flex-direction:column;align-items:center;gap:6px;padding:10px 8px;border:1px solid var(--line);border-radius:12px;background:var(--field,var(--surface));color:var(--ink);cursor:pointer;min-height:44px;font:inherit}
.sbk-tile:hover{border-color:var(--accent)}
.sbk-tile.on{border:2px solid var(--accent);padding:9px 7px}
.sbk-tile img{width:100%;max-height:70px;object-fit:contain}
.sbk-tiles.frames .sbk-tile img{height:70px}
.sbk-pp{display:block;width:100%;aspect-ratio:4/3;border-radius:6px;background-size:cover;box-shadow:0 2px 6px rgba(0,0,0,.15)}
.sbk-tn{display:flex;align-items:center;gap:5px;font-size:.82rem;font-weight:600;text-align:center;flex-wrap:wrap;justify-content:center}
.sbk-tn .pro-badge{font-size:.52rem;padding:1px 4px}
/* Streak card button and the Archive */
.sbk-qod{display:inline-flex;align-items:center;gap:6px}
.sbk-n{font:800 .7rem var(--display);background:var(--accent);color:var(--accent-ink,#fff);border-radius:10px;padding:1px 7px}
.sbk-arch{display:grid;grid-template-columns:repeat(auto-fill,minmax(180px,1fr));gap:12px}
.sbk-acard{display:flex;flex-direction:column;gap:8px;padding:8px;border:1px solid var(--line);border-radius:14px;background:var(--surface);color:var(--ink);cursor:pointer;text-align:left;font:inherit}
.sbk-acard:hover{border-color:var(--accent)}
.sbk-athumb{position:relative;display:block;aspect-ratio:5/4;border-radius:8px;background-size:cover;background-position:top;overflow:hidden;box-shadow:0 2px 6px rgba(40,25,5,.15)}
.sbk-athumb img{position:absolute;width:32%;top:14%;left:2%;transform:rotate(-6deg)}
.sbk-athumb img:nth-child(2){left:34%;transform:rotate(5deg)}.sbk-athumb img:nth-child(3){left:66%;transform:rotate(-3deg)}
.sbk-athumb img:nth-child(4){top:50%;left:10%;transform:rotate(7deg)}.sbk-athumb img:nth-child(5){top:50%;left:42%;transform:rotate(-8deg)}.sbk-athumb img:nth-child(6){top:50%;left:68%;transform:rotate(4deg)}
.sbk-aname{display:flex;flex-direction:column;gap:2px;padding:0 4px 4px}
@media (max-width:1099px){
  .sbk-main{grid-template-columns:minmax(0,1fr)}
  .sbk-side{display:none}
  .sbk-side.in-sheet{display:block}
  .sbk-tools .sbk-mbtn{display:inline-flex}
}
@media (max-width:719px){
  .sbk-tools .sbk-zoombtn{display:inline-flex}
  .sbk-tools{gap:6px;flex-wrap:nowrap;overflow-x:auto;scrollbar-width:none;margin-left:-16px;margin-right:-16px;padding:2px 16px}
  .sbk-tools::-webkit-scrollbar{display:none}
  .sbk-tools .btn{flex:none}
  .sbk-tools .btn{padding-left:10px;padding-right:10px}
  .sbk-stage.zoom .sbk-scroll{overflow-x:auto;-webkit-overflow-scrolling:touch;padding-bottom:6px}
  .sbk-stage.zoom .sbk-paper{width:185%;max-width:none;margin:0}
  .sbk-selbar{bottom:calc(88px + env(safe-area-inset-bottom,0px))}
  .sbk-selname{flex-basis:100%}
}
@media (prefers-reduced-motion:reduce){.sbk-it.new img,.sbk-it.hl{animation:none}.sbk-it{transition:none}}


/* ===== module: 98-sounds.css ===== */
/* Focus Sounds (98-sounds): the card in the Focus Timer sheet, its panel, the Settings sheet and the small speaker button */
.snd-card{border:1px solid var(--line);border-radius:14px;background:color-mix(in srgb,var(--soft) 45%,transparent);padding:4px 6px 4px 4px}
.snd-top{display:flex;align-items:center;gap:4px}
.snd-head{flex:1;min-width:0;display:flex;align-items:center;gap:10px;min-height:48px;padding:4px 6px;border:0;border-radius:10px;background:none;color:var(--ink);font:inherit;text-align:left;cursor:pointer}
div.snd-head{cursor:default}
button.snd-head:hover{background:color-mix(in srgb,var(--ink) 5%,transparent)}
.snd-ic{flex:none;width:36px;height:36px;border-radius:50%;display:grid;place-items:center;background:color-mix(in srgb,var(--accent) 13%,var(--surface));color:var(--accent);transition:background .25s,color .25s}
.snd-ic svg{width:19px;height:19px}
.snd-card:not(.on) .snd-ic{background:var(--field);color:var(--muted)}
.snd-card.live .snd-ic{background:var(--accent);color:var(--accent-ink)}
.snd-txt{display:flex;flex-direction:column;min-width:0;gap:1px}
.snd-txt b{font:600 .95rem var(--display)}
.snd-txt .sub{font-size:.8rem;color:var(--muted);line-height:1.3}
.snd-chev{flex:none;display:grid;place-items:center;color:var(--muted)}
.snd-chev svg{width:18px;height:18px;transition:transform .2s}
.snd-head[aria-expanded="true"] .snd-chev svg{transform:rotate(180deg)}
/* switch: a 44px tall touch target with a small track inside */
.snd-sw{flex:none;position:relative;width:54px;height:44px;border:0;background:none;padding:0;cursor:pointer;border-radius:12px}
.snd-sw::before{content:"";position:absolute;left:5px;right:5px;top:10px;bottom:10px;border-radius:999px;background:color-mix(in srgb,var(--muted) 40%,var(--field));transition:background .2s}
.snd-sw i{position:absolute;top:13px;left:8px;width:18px;height:18px;border-radius:50%;background:#fff;box-shadow:0 1px 3px rgba(0,0,0,.25);transition:transform .2s}
.snd-sw[aria-checked="true"]::before{background:var(--accent)}
.snd-sw[aria-checked="true"] i{transform:translateX(20px)}
.snd-sw:focus-visible{outline:2px solid var(--accent);outline-offset:1px}
/* little equalizer shown while sound plays */
.snd-eq{display:flex;align-items:flex-end;gap:2px;height:14px}
.snd-eq i{width:3px;height:100%;border-radius:2px;background:currentColor;transform:scaleY(.4);transform-origin:50% 100%;will-change:transform;animation:snd-eq 1.3s ease-in-out infinite alternate}
.snd-eq i:nth-child(2){animation-duration:1.7s;animation-delay:-.6s}
.snd-eq i:nth-child(3){animation-duration:1.1s;animation-delay:-.3s}
@keyframes snd-eq{0%{transform:scaleY(.25)}100%{transform:scaleY(1)}}
/* the panel */
.snd-panel{display:grid;gap:14px;margin:4px 4px 6px;padding-top:12px;border-top:1px solid var(--line)}
.snd-h{display:block;font:600 .82rem var(--display);color:var(--muted);margin:0 0 7px}
.snd-chips{display:flex;flex-wrap:wrap;gap:6px}
.snd-chip{display:inline-flex;align-items:center;gap:6px;min-height:40px;padding:6px 12px;border:1px solid var(--line);border-radius:999px;background:var(--surface);color:var(--ink);font:500 .85rem var(--display, inherit);cursor:pointer}
.snd-chip:hover{border-color:color-mix(in srgb,var(--accent) 45%,var(--line))}
.snd-chip[aria-pressed="true"]{background:var(--sel);color:var(--sel-ink);border-color:var(--sel)}
.snd-chip svg{width:16px;height:16px}
.snd-chip .pro-badge{font-size:.54rem;padding:1px 4px;border-radius:5px}
.snd-note{margin:8px 0 0;line-height:1.4}
.snd-mix{display:grid;gap:4px;margin-top:8px}
.snd-lv{display:grid;grid-template-columns:minmax(7.5em,34%) 1fr;align-items:center;gap:10px;font-size:.86rem;min-height:36px}
.snd-vol{display:grid;gap:2px}
.snd-mode{display:flex}
.snd-mode button{flex:1;min-height:38px}
.snd-after{margin-top:10px}
.snd-sec .mi-check{margin-top:10px}
.snd-card.fixed .snd-panel{border-top:0;padding-top:4px}
.snd-sheet .sheet-body{display:grid;gap:12px}
/* the speaker button beside the timer pill in the header, only while a session is active */
.snd-quick{color:var(--muted)}
.snd-quick[hidden]{display:none}
.snd-quick svg{width:20px;height:20px}
.snd-quick.on{color:var(--accent);background:color-mix(in srgb,var(--accent) 12%,var(--surface));border-color:color-mix(in srgb,var(--accent) 40%,var(--line))}
/* desktop: a small round badge on the corner of the sidebar Focus pill */
.snd-quick-nav{display:none}
@media (min-width:980px){
  nav.tabs .in .snd-quick-nav:not([hidden]){display:grid;place-items:center;align-self:flex-end;position:relative;z-index:2;width:28px;height:28px;min-height:0;margin:-18px -3px 0 0;padding:0;border-radius:50%;border:1px solid rgba(255,255,255,.22);background:var(--spine,#0E2A56);color:rgba(255,255,255,.75);box-shadow:0 2px 6px rgba(0,0,0,.25)}
  nav.tabs .in .snd-quick-nav svg{width:15px;height:15px}
  nav.tabs .in .snd-quick-nav.on{background:var(--accent);color:var(--accent-ink);border-color:transparent}
  nav.tabs .in .snd-quick-nav:hover{filter:brightness(1.12)}
}
@media (pointer:coarse){.snd-chip{min-height:44px}}
/* narrow phones: the header has no room beside the timer pill, so the switch lives in the Focus Timer sheet only */
@media (max-width:479px){#sndQuick{display:none}}
@media (max-width:420px){.snd-lv{grid-template-columns:1fr;gap:0}}
@media (prefers-reduced-motion:reduce){.snd-eq i{animation:none;transform:none;will-change:auto}.snd-eq i:nth-child(1){height:55%}.snd-eq i:nth-child(2){height:100%}.snd-eq i:nth-child(3){height:70%}.snd-sw i,.snd-sw::before,.snd-chev svg{transition:none}}

/* ===== Release polish (1.13.0): contrast, focus, motion and touch targets ===== */
.skip-link{position:fixed;left:12px;top:-60px;z-index:100000;padding:10px 16px;border-radius:10px;background:var(--surface);color:var(--ink);border:2px solid var(--accent);font-weight:700;text-decoration:none;transition:top .12s}
.skip-link:focus{top:max(12px,env(safe-area-inset-top,0px))}
