}
:root[data-theme="dark"] .soon{background:color-mix(in srgb,var(--mark) 85%,#000)}
@media (prefers-color-scheme:dark){:root:not([data-theme="light"]) .soon{background:color-mix(in srgb,var(--mark) 85%,#000)}}
:root[data-theme="dark"] .soon.late{background:var(--late)}
@media (prefers-color-scheme:dark){:root:not([data-theme="light"]) .soon.late{background:var(--late)}}
.legal{font-size:.95rem;line-height:1.55;max-height:min(68vh,640px);overflow:auto}
.legal:focus-visible{outline:2px solid var(--accent);outline-offset:2px}
.legal h3{font:700 1rem/1.3 var(--display);margin:1.2rem 0 .3rem}
.legal p{margin:.4rem 0}
.legal ul,.legal-list{margin:.4rem 0 .4rem 1.1rem;padding:0}
.legal li{margin:.25rem 0}
.legal-meta{color:var(--muted);font-size:.85rem}
.legal-line{margin-top:.5rem}
.about-top{display:flex;flex-direction:column;gap:2px;margin-bottom:.5rem}
.about-name{font:800 1.5rem/1.2 var(--display)}
.about-ver{color:var(--muted)}
.about-credits{margin:.3rem 0 .6rem 1.1rem;padding:0}
.about-credits li{margin:.35rem 0}
.about-lic{margin:.2rem 0 .6rem}.about-lic summary{cursor:pointer;font-size:.85rem}
.about-lic pre{white-space:pre-wrap;font-size:.72rem;max-height:240px;overflow:auto;padding:8px 10px;border:1px solid var(--line);border-radius:10px;background:var(--surface)}
.link-btn:focus-visible,.btn:focus-visible,.icon-btn:focus-visible,[role="tab"]:focus-visible,[role="switch"]:focus-visible,[data-act]:focus-visible,summary:focus-visible{outline:2px solid var(--accent);outline-offset:2px}
@media (prefers-reduced-motion:reduce){
