  [data-act="plan-view"],[data-act="cf-view"],[data-act="bview"],[data-act="tl-mode"],[data-act="tl-zoom"],[data-act="f-sort"],.env-head,.pf-link,.plan .btn.small.fh-hide,.est-btn{min-height:max(40px,2.5rem)}
