/* ===== module: 96-semester.css ===== */
/* Set up your semester */
:root{--sem-ok:#17805F}
@media (prefers-color-scheme:dark){:root:not([data-theme="light"]){--sem-ok:#5FD3A8}}
:root[data-theme="dark"]{--sem-ok:#5FD3A8}
.sem-sheet{position:relative}
.sem-main{display:contents}
.sem-top{flex:none;padding:6px 18px 0;display:grid;gap:6px}
.sem-count{margin:0}
.sem-steps{list-style:none;margin:0;padding:0;display:flex;gap:4px}
.sem-steps li{flex:1;min-width:0}
.sem-st{width:100%;min-height:44px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:2px;padding:4px 2px;border:0;border-radius:10px;background:none;color:var(--muted);font-size:.72rem;font-weight:600}
.sem-st:hover{background:var(--soft)}
.sem-n{display:grid;place-items:center;width:24px;height:24px;border-radius:50%;border:2px solid var(--line);font:700 .78rem var(--display);background:var(--surface)}
.sem-n svg{width:14px;height:14px}
.sem-st.cur{color:var(--ink)}
.sem-st.cur .sem-n{border-color:var(--accent);background:var(--accent);color:var(--accent-ink)}
.sem-st.done .sem-n{border-color:var(--sem-ok);color:var(--sem-ok)}
