.mt-tx{display:-webkit-box;-webkit-box-orient:vertical;-webkit-line-clamp:4;line-clamp:4;overflow:hidden;overflow-wrap:anywhere;max-width:100%}
.mt-tile.s1{font-size:.9rem}
.mt-tile.s2{font-size:.8rem}.mt-tile.s2 .mt-tx{-webkit-line-clamp:5;line-clamp:5}
.mt-tile.s3{font-size:.72rem;line-height:1.2}.mt-tile.s3 .mt-tx{-webkit-line-clamp:6;line-clamp:6}
.mt-tile.hit{border-color:var(--leaf);background:color-mix(in srgb,var(--leaf) 18%,var(--surface));animation:mtHit .32s ease-in forwards;pointer-events:none}
@keyframes mtHit{0%{transform:scale(1)}35%{transform:scale(1.06)}100%{transform:scale(.6);opacity:0}}
.mt-tile.gone{visibility:hidden}
.mt-tile.miss{border-color:var(--late);background:color-mix(in srgb,var(--late) 14%,var(--surface));animation:mtShake .42s ease}
@keyframes mtShake{0%,100%{transform:none}20%{transform:translateX(-6px)}40%{transform:translateX(6px)}60%{transform:translateX(-4px)}80%{transform:translateX(3px)}}
.mt-peek{position:absolute;left:0;right:0;bottom:0;z-index:2;margin:0;padding:10px 12px;border-radius:12px;background:var(--surface);border:1px solid var(--accent);box-shadow:0 8px 24px rgba(0,0,0,.18);font-size:.95rem;line-height:1.35;overflow-wrap:anywhere;max-height:60%;overflow:auto}
.mt-res{display:flex;flex-direction:column;align-items:center;gap:6px;text-align:center;padding:12px 8px;border-radius:16px;background:var(--soft);border:1px solid var(--line)}
.mt-big{font:800 2.6rem/1.05 var(--display);font-variant-numeric:tabular-nums;color:var(--ink)}
.mt-new{display:inline-block;padding:3px 12px;border-radius:999px;background:var(--leaf);color:#fff;font:700 .9rem var(--display);animation:mtPop .5s cubic-bezier(.22,1.6,.36,1)}
@keyframes mtPop{from{transform:scale(.5);opacity:0}to{transform:none;opacity:1}}
.mt-recent{display:flex;flex-wrap:wrap;align-items:center;gap:6px 8px;justify-content:center}
