.mt-lb .nm{flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.mt-lb b{flex:none;font-variant-numeric:tabular-nums}
@media (max-width:600px){
  .mt-grid{grid-template-columns:repeat(3,minmax(0,1fr));grid-auto-rows:minmax(88px,1fr);gap:8px}
  .mt-tile{padding:8px 6px;font-size:.9rem;border-radius:12px}
