html[data-motion="static"] .mt-tile.on{transform:none}
.mt-still .mt-tile,.mt-still .mt-tile.hit,.mt-still .mt-tile.miss,.mt-still .mt-new,.mt-still .mt-pen.show{animation:none;transition:none}
.mt-still .mt-pen.show{opacity:1}
/* ===== module: 97-pinpicker.css ===== */
.pp-native{position:absolute!important;width:1px!important;height:1px!important;opacity:0!important;pointer-events:none!important;overflow:hidden}
