.pp-btn{display:inline-flex;align-items:center;gap:6px;min-width:0;max-width:100%;min-height:36px;padding:4px 8px;font:inherit;font-size:.8125rem;background:rgba(255,255,255,.55);border:1px solid rgba(42,36,24,.2);border-radius:8px;color:#2A2418;cursor:pointer;text-align:left}
