/* ===== module: 99-motion-a11y-tz.css ===== */
/* Text size: everything in rem scales with the root. Default follows the browser or device; iOS gets Dynamic Type. */
html{font-size:100%;-webkit-text-size-adjust:100%;text-size-adjust:100%}
html[data-ts="s"]{font-size:87.5%}
html[data-ts="l"]{font-size:112.5%}
html[data-ts="xl"]{font-size:125%}
@supports (font:-apple-system-body) and (-webkit-touch-callout:none){html:not([data-ts]){font:-apple-system-body}}
.cap-row.sb-wide{flex-wrap:wrap;gap:8px}
.cap-row.sb-wide .segb{flex-wrap:wrap}
/* Animations: Off, and Auto when the device asks for less motion. Ends every animation and transition at once. */
html[data-motion="static"] *,html[data-motion="static"] *::before,html[data-motion="static"] *::after{animation-duration:.01ms!important;animation-delay:0s!important;animation-iteration-count:1!important;transition-duration:.01ms!important;transition-delay:0s!important;scroll-behavior:auto!important}
html[data-motion="calm"] .plan-orb{animation:none}
html[data-motion="calm"] *,html[data-motion="calm"] *::before,html[data-motion="calm"] *::after{scroll-behavior:auto!important}
#sbFlash{position:fixed;inset:0;z-index:2147483000;pointer-events:none;box-shadow:inset 0 0 0 5px var(--accent);background:color-mix(in srgb,var(--accent) 8%,transparent)}
/* Time zone notice */
.tz-note{position:fixed;left:12px;right:12px;bottom:calc(76px + env(safe-area-inset-bottom,0px));z-index:60;max-width:540px;margin:0 auto;background:var(--surface);color:var(--ink);border:1px solid var(--line);border-radius:14px;padding:12px 14px;box-shadow:0 8px 28px rgba(0,0,0,.25)}
.tz-note p{margin:0 0 10px;font-size:.92rem;line-height:1.4}
.tz-note .tz-act{display:flex;flex-wrap:wrap;gap:8px}
/* High contrast and calm backgrounds: scenery dimmed and blurred, cards and text stronger. Also on by itself for prefers-contrast: more. */
html[data-hc="1"] #sceneArt{filter:blur(6px) saturate(.55);opacity:.4}
html[data-hc="1"] body{background-image:none!important}
html[data-hc="1"]{--muted:color-mix(in srgb,var(--ink) 82%,var(--bg));--line:color-mix(in srgb,var(--ink) 38%,var(--bg))}
html[data-hc="1"] .card,html[data-hc="1"] .task,html[data-hc="1"] header.top,html[data-hc="1"] nav.tabs,html[data-hc="1"] .sheet{background-color:var(--surface)!important;opacity:1}
/* Text that sits straight on theme artwork gets a soft plate in the page colour, so it stays readable on every scene. --scrim is the plate's strength. */
html.sc-on :is(.board-sec-head > h2,.board-ctl .mini,.hint-line,.tl-controls > h2,.view-head > h2,.fcrumb,.sec > .t,.sec > .n,.term-bar,.nudge,header.top .today){background:color-mix(in srgb,var(--paper) var(--scrim,92%),transparent);-webkit-box-decoration-break:clone;box-decoration-break:clone;border-radius:8px;padding-inline:.5rem;text-shadow:0 0 6px var(--paper)}
html[data-hc="1"].sc-on{--scrim:96%}
/* Big text: the header may wrap instead of overlapping, tap targets grow with the text, the side bar's sync line ellipsizes */
.top-row{flex-wrap:wrap;row-gap:6px}
.top-row > div:first-child{min-width:min(100%,8rem)!important}
.head-actions{margin-left:auto}
.icon-btn{width:max(40px,2.5rem);height:max(40px,2.5rem)}
nav.tabs:is([data-fit="2"],[data-fit="3"],[data-fit="4"],[data-fit="5"]) .nav-sync{display:block;text-align:center;text-overflow:ellipsis}
nav.tabs:is([data-fit="2"],[data-fit="3"],[data-fit="4"],[data-fit="5"]) .nav-sync::before{display:inline-block;margin:0 5px 0 0;vertical-align:middle}
@media (forced-colors:active){#sceneArt,.confetti,#sbFlash{display:none!important}}
/* Optical centring of button labels: the fonts' ascent is taller than the descent, so a label with no descenders ("New Deck", "Add")
   sat about 1px above the middle. 0.8px more padding on top than at the bottom moves the label down by 0.8px. */
.btn{padding-top:10.8px;padding-bottom:9.2px}
.btn.small,.segb button,.ann-tab,.ai-chip,.av-chip{padding-top:6.8px;padding-bottom:5.2px}
.btn.big{padding-top:14.8px;padding-bottom:13.2px}
.pview-tabs button{padding-top:10.8px;padding-bottom:9.2px}
.fab{padding-top:14.8px;padding-bottom:13.2px}
.plan-sheet .sheet-foot .btn{padding-top:10.8px;padding-bottom:9.2px}
/* ===== module: 100-phone.css ===== */
/* Phone and tablet bar (the desktop side menu is untouched).
   Bottom tabs run Board to Groups like the desktop menu, with no More button; the top right holds Focus, Search and Announcements, and the
   three dots hold light/dark, style and settings. */
@media (max-width:979px){
  nav.tabs .in .nav-more{display:none!important}
  nav.tabs .in .nav-groups{display:flex}
  nav.tabs .in{grid-template-columns:none!important;grid-auto-flow:column;grid-auto-columns:minmax(0,1fr)}
  nav.tabs{left:6px;right:6px;padding:6px 3px}
  nav.tabs .in button{min-width:0;padding-left:1px;padding-right:1px;font-size:clamp(.45rem,2.25vw,.66rem)!important;letter-spacing:-.01em;white-space:nowrap}
  nav.tabs .in button svg{width:22px;height:22px}
  .nav-groups .grp-dot{right:50%;margin-right:-22px;top:2px}
  header.top .theme-btn{display:none}
  .head-actions .pomo-btn{order:1}
  .head-actions [data-act="search"]{order:2}
  .head-actions .ann-btn{order:3}
  .head-actions [data-act="menu"]{order:4}
}
@media (max-width:979px){html[data-ts="l"] nav.tabs .in button{font-size:clamp(.42rem,2.05vw,.6rem)!important}html[data-ts="xl"] nav.tabs .in button{font-size:clamp(.4rem,1.9vw,.55rem)!important}}
/* Companion page on a phone: the companion scrolls with its name and description, so it passes under the top bar */
.cp-front.cp-under{z-index:4}
/* Notes on a phone: a little smaller (same centre, same spacing, same tilt); the sticker envelope sits at the left so it never covers the Add button,
   and while a sticker is being dragged it steps aside so the whole board shows. */
@media (max-width:700px){
  .note{transform:rotate(var(--rot)) scale(.88)}
  .note.dragging{transform:rotate(calc(var(--rot) + 3deg)) scale(.92)}
  .note.editing{transform:none}
  .env.closed{left:14px;right:auto}
  .env:not(.closed){max-height:min(300px,40dvh)}
  .env:not(.closed) .env-body{overflow-y:auto}
  .nb-wrap:has(.env:not(.closed)) .nb-main{padding-bottom:min(300px,40dvh)}
  .env{transition:opacity .15s}
  body.stk-dragging .env{opacity:0}
}
/* Crunch Forecast on a phone: seven day cells fit the width, each week's label sits on its own line above them, and each cell keeps just the date and the count
   (the paper and exam breakdown is in the week details). Prefixed with .cr so it wins over the stylesheet the Crunch page adds itself. */
@media (max-width:600px){
  .cr .cr-scroll{padding:8px}
  .cr .cr-grid{min-width:0;gap:2px}
  .cr .cr-row,.cr .cr-dow{grid-template-columns:repeat(7,minmax(0,1fr));gap:3px}
  .cr .cr-dow span:first-child{display:none}
  .cr .cr-wk{grid-column:1/-1;flex-direction:row;align-items:center;gap:8px;min-height:28px;padding:8px 2px 0;border-radius:6px}
  .cr .cr-wk .cr-bar{flex:1;margin:0;min-width:24px}
  .cr .cr-d{min-height:46px}
  .cr .cr-d .mk,.cr .cr-d .td{display:none}
}
/* Board notices: one shows, the rest wait behind a "N more" button (see the Board notices script) */
.bn-shut{display:none!important}
.bn-more{display:inline-flex;align-items:center;gap:6px;margin:8px 0 0;padding:6px 12px;min-height:36px;border:1px dashed var(--line);border-radius:999px;background:var(--surface);color:var(--muted);font:600 .85rem var(--display);cursor:pointer}
.bn-more:hover{color:var(--ink);border-style:solid}
.bn-more svg{width:14px;height:14px;transition:transform .15s}
.bn-more{margin:0 0 10px;border-style:solid;color:var(--ink)}
.bn-n{display:inline-grid;place-items:center;min-width:20px;height:20px;padding:0 6px;border-radius:999px;background:var(--late,#D93B3B);color:#fff;font:800 .74rem/1 var(--display);box-shadow:0 0 0 2px var(--surface)}
.bn-more[aria-expanded="true"] svg{transform:rotate(180deg)}
/* Heavy week and Rough week folded into one card */
.rw-banner.rw-crunch{border-left:6px solid var(--cr3,#F29A4A)}
.rw-banner.rw-crunch.lv4{border-left-color:var(--cr4,#D3352A)}
.rw-banner .cc-t{display:block;margin-bottom:4px}
.rw-banner .cc-t b{font-family:var(--display)}
.rw-banner .cc-t .mini{display:block;color:var(--muted)}
/* Courses: as wide as the other pages, cards side by side when there is room */
body.wide .course-list{grid-template-columns:repeat(2,minmax(0,1fr))}
@media (max-width:719px){body.wide .course-list{grid-template-columns:1fr}}
/* Grades: course rows two across too */
@media (min-width:720px){.gp-list{grid-template-columns:repeat(2,minmax(0,1fr))}}
.course-card .next{font-size:.92rem;color:var(--muted);margin-top:2px}
.course-card .next b{color:var(--ink);font-weight:600}
.course-card .next .late{color:var(--late);font-weight:600}
/* Deck Archive: the same folder icon as the notes Archive */
.deck-actions .deck-arch svg{display:block}
/* Phones: the header frosts over the page once it scrolls; the Add button (and the companion beside it) step aside while the
   quick-add bar passes under them, and pages leave room at the bottom for both */
@media (max-width:639px){
  header.top{transition:background-color .2s,box-shadow .2s,border-color .2s}
  body.sb-scrolled header.top{background:color-mix(in srgb,var(--paper) 72%,transparent);-webkit-backdrop-filter:blur(20px) saturate(1.5);backdrop-filter:blur(20px) saturate(1.5);border-bottom-color:var(--line);box-shadow:0 8px 18px -14px rgba(8,20,50,.45)}
  .wrap{padding-bottom:170px}
  .fab{transition:opacity .18s,transform .18s}
  body.fab-yield .fab{opacity:0;transform:translateY(12px) scale(.94);pointer-events:none}
  body.fab-yield .cp-front .cp{opacity:0;scale:.8}
  body.fab-yield .cp-front .cp-hit{pointer-events:none}
}
/* ===== Groups, Direction 1: a band in the course colour, the group's icon in a ring, section cards tinted with the group's colour ===== */
.grp-grid{grid-template-columns:repeat(auto-fill,minmax(250px,1fr));gap:20px}
.grp-card.g2-card{border:1px solid var(--line);border-top:1px solid var(--line);border-radius:18px!important;overflow:hidden;box-shadow:0 2px 8px rgba(14,42,86,.08)}
