.g2-band{display:block;align-self:stretch;background:linear-gradient(135deg,color-mix(in srgb,var(--c) 88%,#000),color-mix(in srgb,var(--c) 70%,var(--surface)));color:#fff;text-align:left}
.g2-card .g2-band{height:64px;padding:10px 12px}
.g2-kick{font:800 .74rem/1.2 var(--display);letter-spacing:.06em;text-transform:uppercase;text-shadow:0 1px 2px rgba(0,0,0,.25)}
.g2-ring{display:grid;place-items:center;flex:none;border-radius:50%;background:color-mix(in srgb,var(--c) 14%,var(--surface));color:var(--c);box-shadow:0 0 0 4px var(--surface),0 0 0 6px var(--c),0 4px 10px rgba(0,0,0,.16);overflow:hidden}
.g2-ring > svg{width:72%;height:72%;display:block;overflow:visible}
.g2-sym{display:grid;place-items:center;width:100%;height:100%}
.g2-sym svg{width:52%;height:52%}
.g2-card .g2-ring{width:70px;height:70px;margin-top:-35px}
.g2-card .grp-name{margin:12px 14px 2px;font:800 1.15rem/1.25 var(--display)}
.g2-meta{font-size:.84rem;color:var(--muted)}
.g2-card .g2-meta{margin:0 14px}
.g2-card .gc-foot{justify-content:center;border-top:0;padding:12px 14px 0;margin-top:auto}
.g2-pill{font:700 .76rem/1.2 var(--display);padding:4px 10px;border-radius:999px;background:color-mix(in srgb,var(--c) 16%,var(--surface));color:color-mix(in srgb,var(--c) 60%,var(--ink))}
.g2-pill.due{background:color-mix(in srgb,#F5A524 22%,var(--surface));color:color-mix(in srgb,#8A5300 80%,var(--ink))}
/* The group's page header */
.grp-head.g2-head{margin-top:14px;padding:0;border:1px solid var(--line);border-radius:18px!important;box-shadow:0 2px 8px rgba(14,42,86,.08);background:var(--surface)}
.g2-head .g2-band{display:flex;align-items:flex-start;justify-content:space-between;gap:12px;flex-wrap:wrap;min-height:88px;padding:14px 18px;border-radius:17px 17px 0 0}
.g2-head .row-actions{margin:0;gap:8px;flex-wrap:wrap}
.g2-head .g2-band .btn{min-height:38px;background:rgba(255,255,255,.18);border-color:rgba(255,255,255,.45);color:#fff;box-shadow:none}
.g2-head .g2-band summary.btn{color:#fff}
.g2-head .g2-band .btn.primary{background:#fff;border-color:#fff;color:color-mix(in srgb,var(--c) 70%,#000)}
.g2-head .grp-more{position:relative}
.g2-low{display:flex;align-items:flex-start;gap:18px;padding:0 20px;margin-top:-44px}
.g2-head .g2-ring{width:96px;height:96px}
.g2-txt{padding-top:52px;min-width:0;display:grid;gap:6px;justify-items:start}
.g2-txt h2{margin:0;font:800 1.75rem/1.15 var(--display);overflow-wrap:anywhere}
.g2-head .g2-meta{display:flex;align-items:center;gap:10px;flex-wrap:wrap;font-size:.9rem}
.g2-code{font:800 .7rem/1 var(--display);letter-spacing:.05em;color:#fff;background:var(--c);padding:4px 8px;border-radius:6px}
.g2-head .grp-avs{margin:0}
.g2-head .grp-chips{margin:4px 0 0}
.g2-head .grp-tabs{margin:14px 0 0;padding:0 16px 12px;border:0;gap:6px;flex-wrap:wrap}
.g2-head .grp-tabs button{border:0!important;border-radius:999px;padding:8px 14px;min-height:38px}
.g2-head .grp-tabs button.on{background:color-mix(in srgb,var(--c) 15%,var(--surface));color:color-mix(in srgb,var(--c) 62%,var(--ink))}
/* Start a Session sits in the header; the separate Study Together card only shows while a session is live (or needs attention) */
#grpDetail .room-sec.is-idle:not(:has(.room-err)){display:none}
#grpDetail:not(:has(.room-sec.is-idle)) .g2-session{display:none}
/* Sections are cards with a round icon in the group's colour; ones with nothing in them yet sit side by side */
#grpDetail .grp-pane{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));grid-auto-flow:row dense;gap:16px;margin-top:16px;align-items:stretch}
#grpDetail .grp-pane > *{grid-column:1/-1;min-width:0}
#grpDetail .grp-pane[data-pane="study"] > .grp-sec:has(> .grp-none){grid-column:auto}
#grpDetail .grp-pane > :empty{display:none}
#grpDetail .grp-sec{margin:0;padding:14px 16px 16px;background:var(--surface);border:1px solid var(--line);border-radius:18px;box-shadow:0 2px 8px rgba(14,42,86,.06)}
#grpDetail .grp-sec > h3.fsec{margin-top:0}
#grpDetail .grp-sec > h3.fsec > svg:first-child{box-sizing:border-box;width:30px;height:30px;padding:6px;border-radius:50%;background:color-mix(in srgb,var(--c) 15%,var(--surface));color:var(--c);flex:none}
#grpDetail .grp-none{border:0;background:color-mix(in srgb,var(--c) 6%,var(--surface));border-radius:12px}
#grpDetail .score-bar i,#grpDetail .grp-lb .bar i{background:var(--c)}
#grpDetail .grp-lb .bar{background:color-mix(in srgb,var(--c) 12%,var(--surface))}
.g2-mm summary.g2-dots{width:32px;height:32px;justify-content:center;border:1px solid var(--line);border-radius:10px;color:var(--muted);font:700 1rem/1 var(--display);background:var(--surface)}
.g2-mm .grp-menu{left:auto;right:0}
.g2-mm .grp-menu .btn{justify-content:flex-start;white-space:nowrap}
#grpMembers .grp-av{box-shadow:0 0 0 2px var(--surface),0 0 0 4px color-mix(in srgb,var(--c) 70%,transparent)}
@media (max-width:719px){
  #grpDetail .grp-pane{grid-template-columns:1fr}
  #grpDetail .grp-pane[data-pane="study"] > .grp-sec:has(> .grp-none){grid-column:1/-1}
  .g2-head .g2-band{min-height:0;padding:12px 14px 50px}
  .g2-head .g2-band .btn{min-height:34px;padding:6px 11px;font-size:.84rem}
  .g2-low{padding:0 14px;gap:12px}
  .g2-head .g2-ring{width:76px;height:76px}
  .g2-low{margin-top:-38px}
  .g2-txt{padding-top:42px}
  .g2-txt h2{font-size:1.4rem}
  .g2-head .grp-tabs{flex-wrap:nowrap;overflow-x:auto;scrollbar-width:none;padding:0 10px 10px}
  .g2-head .grp-tabs button{flex:none}
}
/* ===== Courses, Direction 1: band in the course colour, initials in a ring, the grade and one status pill ===== */
.course-card.c2-card{display:flex;flex-direction:column;gap:0;padding:0;margin-top:0;border-radius:18px!important;overflow:hidden;box-shadow:0 2px 8px rgba(14,42,86,.08)}
.course-list{margin-top:18px}
.course-card.c2-card::before{display:none}
.c2-band{display:flex;justify-content:space-between;align-items:flex-start;gap:10px;height:62px;padding:10px 14px;background:linear-gradient(135deg,color-mix(in srgb,var(--c) 88%,#000),color-mix(in srgb,var(--c) 70%,var(--surface)));color:#fff}
.c2-sched{font:700 .76rem var(--display);opacity:.95;text-shadow:0 1px 2px rgba(0,0,0,.25);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;min-width:0}
.c2-top{display:flex;align-items:flex-end;gap:12px;padding:0 16px;margin-top:-30px}
.c2-ring{width:64px;height:64px;font:800 .95rem var(--display);letter-spacing:.02em}
.c2-card h3{font:800 1.3rem/1.2 var(--display)!important;margin:0 0 4px!important;overflow-wrap:anywhere}
.c2-card .body{padding:8px 16px 14px;gap:6px!important}
.c2-card .body > .prog{margin-top:6px!important;padding-top:0!important}
.c2-foot{display:flex;align-items:center;justify-content:space-between;gap:10px;flex-wrap:wrap;margin-top:8px;padding-top:10px;border-top:1px solid var(--line);font-size:.88rem;color:var(--muted)}
.c2-grade{display:inline-flex;align-items:center;gap:6px;margin:0;font-size:inherit}
.c2-grade .gt-spark svg{stroke:var(--c)}.c2-grade .gt-spark circle{fill:var(--c)}
.c2-grade b{color:var(--ink);font:800 1rem var(--display)}
.c2-letter{display:inline-grid;place-items:center;min-width:24px;height:22px;padding:0 5px;border-radius:6px;font:800 .78rem var(--display);background:color-mix(in srgb,var(--c) 16%,var(--surface));color:color-mix(in srgb,var(--c) 65%,var(--ink))}
.g2-pill.late{background:color-mix(in srgb,var(--late) 16%,var(--surface));color:var(--late)}
/* A course's page */
.detail-head.c2-head{padding:0;border:1px solid var(--line);border-radius:18px;box-shadow:0 2px 8px rgba(14,42,86,.08);background:var(--ph-surf,var(--surface));margin-top:14px;overflow:visible}
.detail-head.c2-head::before{display:none}
.c2-head .g2-band{display:flex;align-items:flex-start;justify-content:space-between;gap:12px;flex-wrap:wrap;min-height:88px;padding:14px 18px;border-radius:17px 17px 0 0}
.c2-head .row-actions{margin:0;gap:8px}
.c2-head .g2-band .btn{min-height:36px;background:rgba(255,255,255,.18);border-color:rgba(255,255,255,.45);color:#fff;box-shadow:none}
.c2-head .g2-band .btn:last-child{background:#fff;border-color:#fff;color:color-mix(in srgb,var(--c) 70%,#000)}
.c2-head .g2-ring{width:96px;height:96px;font:800 1.35rem var(--display)}
.c2-head h2{font:800 1.75rem/1.15 var(--display);margin:0}
.c2-head .g2-meta{display:flex;align-items:center;gap:10px;flex-wrap:wrap;font-size:.9rem}
.c2-head .g2-code{color:#fff;font-size:.7rem}
.c2-head .cd-tabs{margin:14px 16px 12px;max-width:420px}
.c2-cols{display:grid;grid-template-columns:minmax(0,1.7fr) minmax(0,1fr);gap:0 22px;align-items:start}
.c2-side > :first-child,.c2-main > :first-child{margin-top:18px}
.c2-card2{margin-top:18px;padding:14px 16px 16px;background:var(--surface);border:1px solid var(--line);border-radius:18px;box-shadow:0 2px 8px rgba(14,42,86,.06)}
.c2-card2 h2.sec{margin-top:0}
.c2-big{display:flex;align-items:center;gap:8px;font:800 2.2rem/1.1 var(--display);margin:4px 0 8px}
.c2-side .c2-card2 .prog .track i,.c2-head ~ .c2-cols .c2-card2 .prog i{background:var(--c,var(--accent))}
@media (max-width:899px){.c2-cols{grid-template-columns:1fr}}
@media (max-width:719px){
  .c2-head .g2-band{min-height:0;padding:12px 14px 50px}
  .c2-head .g2-band .btn{min-height:34px;padding:6px 11px;font-size:.84rem}
  .c2-head .g2-ring{width:76px;height:76px;font-size:1.1rem}
  .c2-head .g2-low{margin-top:-38px;padding:0 14px;gap:12px}
  .c2-head .g2-txt{padding-top:42px}
  .c2-head h2{font-size:1.4rem}
}
/* ===== Grades, Direction 1 (Grades B): a hero card with the average and a colour bar per course, then marks and a calculator ===== */
.gp-hero{margin-top:14px;background:var(--surface);border:1px solid var(--line);border-radius:18px;box-shadow:0 2px 8px rgba(14,42,86,.08);overflow:hidden}
.gp-hero-band{--c:var(--accent);display:flex;align-items:center;gap:18px;flex-wrap:wrap;padding:18px 20px;background:linear-gradient(120deg,color-mix(in srgb,var(--accent) 92%,#000),color-mix(in srgb,var(--accent) 74%,var(--surface)));color:#fff}
.gp-cap{width:76px;height:76px;background:var(--surface);color:var(--accent);box-shadow:0 0 0 4px rgba(255,255,255,.35)}
.gp-cap svg{width:46%;height:46%}
.gp-hero-t{display:grid;gap:2px;flex:1;min-width:180px}
.gp-avg{font:800 2.6rem/1.05 var(--display)}
.gp-avg.gr-none{font-size:1.6rem}
.gp-hero-sub{font:600 .9rem var(--display);opacity:.95}
.gp-hero .gp-sum{display:flex;gap:10px;flex-wrap:wrap;margin:0}
.gp-hero .gp-tile{min-width:120px;padding:10px 12px;border-radius:14px;background:rgba(255,255,255,.16);border:1px solid rgba(255,255,255,.35);color:#fff;box-shadow:none}
.gp-hero .gp-tile .gr-v{font:800 1.4rem/1.1 var(--display);color:#fff}
.gp-hero .gp-tile .gr-k{color:#fff;opacity:.92;font-size:.78rem;text-transform:none;letter-spacing:0}
.gp-hero .gp-tile.gr-bad{background:rgba(255,120,110,.3)}
.gp-hero .gp-list{display:block;list-style:none;margin:0;padding:6px 16px 10px}
.gp-hero .gp-course{display:flex;align-items:center;gap:8px;border:0;border-bottom:1px solid var(--line);border-radius:0;background:none;box-shadow:none;padding:6px 0;margin:0}
.gp-hero .gp-course:last-child{border-bottom:0}
.gp-hero .gp-course::before{display:none}
.gp-hero .gp-main{flex:1;min-width:0;display:grid;grid-template-columns:46px minmax(0,240px) minmax(0,1fr) 120px;grid-template-areas:"ring who bar grade" "ring line line line";align-items:center;gap:2px 16px;padding:8px 4px;background:none;border:0;text-align:left;color:inherit}
.gp-ring{grid-area:ring;width:46px;height:46px;font:800 .8rem var(--display)}
.gp-ring.sm{width:30px;height:30px;font-size:.62rem;box-shadow:0 0 0 2px var(--surface),0 0 0 3.5px var(--c)}
.gp-who{grid-area:who;display:grid;min-width:0}
.gp-who .gp-name{font:800 1rem/1.25 var(--display);overflow-wrap:anywhere;white-space:normal;overflow:visible;text-overflow:clip}
.gp-hero .gp-bar{grid-area:bar;position:relative;display:block;height:12px;border-radius:99px;background:color-mix(in srgb,var(--c) 14%,var(--surface));overflow:visible}
.gp-hero .gp-bar .gp-fill{position:absolute;left:0;top:0;bottom:0;border-radius:99px;background:var(--c)}
.gp-hero .gp-bar .gp-pass{position:absolute;top:-4px;bottom:-4px;width:2px;margin-left:-1px;background:var(--ink);border-radius:2px;opacity:.75}
.gp-hero .gp-bar .gp-goal{position:absolute;top:-5px;bottom:-5px;width:8px;margin-left:-4px;border:2px solid var(--c);border-radius:4px;background:var(--surface)}
.gp-hero .gp-grade{grid-area:grade;display:inline-flex;align-items:center;gap:6px;justify-self:end}
.gp-hero .gp-grade b{font:800 1.35rem var(--display)}
.gp-hero .gp-line{grid-area:line}
.gp-hero .gp-course .rk-pill,.gp-hero .gp-course .pill{justify-self:start}
.gp-low{display:grid;grid-template-columns:minmax(0,1.5fr) minmax(0,1fr);gap:18px;align-items:start}
.gp-low .fsec{display:flex;align-items:center;gap:8px;margin-top:0}
.gp-low .fsec .spacer{flex:1}
.gp-calc select{width:100%;margin:6px 0 10px}
.gp-calc .gp-need{display:block;margin:0 0 10px;padding:0;border:0;background:none;box-shadow:none;font-size:.9rem}
.gp-calc .gp-need .gr-k{display:none}
.gp-calc-t{display:flex;flex-wrap:wrap;gap:6px;margin-bottom:10px}
.gp-calc-t .chip[aria-pressed="true"]{background:color-mix(in srgb,var(--c) 18%,var(--surface));border-color:var(--c);color:var(--ink)}
.gp-calc-out{display:grid;gap:2px;padding:12px 14px;border-radius:14px;background:color-mix(in srgb,var(--c) 9%,var(--surface));border:1px solid color-mix(in srgb,var(--c) 30%,var(--line));font-size:.9rem}
.gp-calc-big{font:800 2rem/1.1 var(--display);color:color-mix(in srgb,var(--c) 75%,var(--ink))}
@media (max-width:799px){
  .gp-low{grid-template-columns:1fr}
  .gp-hero .gp-main{grid-template-columns:46px minmax(0,1fr) auto;grid-template-areas:"ring who grade" "ring bar bar" "ring line line";gap:4px 12px}
  .gp-hero .gp-tile{min-width:0;flex:1}
  .gp-avg{font-size:2.1rem}
}
/* Course icons: the picker in Edit Course, and the icon inside a course's ring */
.ci-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(46px,1fr));gap:6px}
.ci-grid label{position:relative;display:block;cursor:pointer}
.ci-grid input{position:absolute;opacity:0;inset:0;margin:0;cursor:pointer}
.ci-grid label > span{display:grid;place-items:center;aspect-ratio:1;border-radius:50%;border:1px solid var(--line);background:var(--surface);color:var(--c);transition:background .12s,border-color .12s}
.ci-grid .ci-t{font:800 .62rem var(--display);letter-spacing:.02em}
.ci-grid svg{width:58%;height:58%}
.ci-grid label:hover > span{border-color:var(--c)}
.ci-grid input:checked + span{background:color-mix(in srgb,var(--c) 16%,var(--surface));border:2px solid var(--c);box-shadow:0 0 0 2px var(--surface),0 0 0 4px color-mix(in srgb,var(--c) 35%,transparent)}
.ci-grid input:focus-visible + span{outline:2px solid var(--accent);outline-offset:2px}
.g2-ring > svg.ci-svg{width:56%;height:56%;overflow:visible}
/* Course icons as stickers: coloured fills, a white die-cut edge and a little tilt */
.ci-svg{--ci-ink:color-mix(in srgb,var(--c) 40%,#0E1424);stroke:var(--ci-ink);stroke-width:1.6;filter:drop-shadow(1.3px 0 0 #fff) drop-shadow(-1.3px 0 0 #fff) drop-shadow(0 1.3px 0 #fff) drop-shadow(0 -1.3px 0 #fff) drop-shadow(0 1.5px 1.5px rgba(10,20,40,.28));transform:rotate(-7deg)}
.ci-svg .a{fill:var(--c)}
.ci-svg .b{fill:color-mix(in srgb,var(--c) 26%,#fff)}
.ci-svg .w{fill:#fff;stroke:none}
.ci-svg .y{fill:#FFC93C}
.ci-svg .g{fill:#3DBE6A}
.ci-svg .r{fill:#F25C54}
.ci-svg .sa{stroke:var(--c);stroke-width:3}
.ci-svg .sb{stroke:color-mix(in srgb,var(--c) 45%,#fff);stroke-width:3}
.ci-svg .ws{stroke:#fff;stroke-width:1.8}
.g2-ring > svg.ci-svg{width:64%;height:64%}
.ci-grid svg{width:70%;height:70%}
@media (prefers-reduced-motion:no-preference){.ci-grid label:hover svg{transform:rotate(0) scale(1.08);transition:transform .15s}}
/* ===== Crunch R2 ===== */
.cr2 .cr-head{display:flex;align-items:center;gap:12px;flex-wrap:wrap}
.cr2 .cr-head h2{flex:1}
.cr2-range button[disabled]{opacity:1;cursor:default}
.cr2-top{display:grid;grid-template-columns:minmax(260px,1fr) minmax(0,2.3fr);gap:18px;margin-top:14px;align-items:stretch}
.cr2-now,.cr2-chart{background:var(--surface);border:1px solid var(--line);border-radius:18px;box-shadow:0 2px 8px rgba(14,42,86,.08)}
.cr2-now{--c:var(--cr2,#9DDBA8);display:flex;flex-direction:column;overflow:hidden;padding:0 0 16px;margin:0}
.cr2-now.lv0{--c:#4C9BE8}.cr2-now.lv1{--c:#3FA866}.cr2-now.lv2{--c:#D9A21B}.cr2-now.lv3{--c:#E8833A}.cr2-now.lv4{--c:#D3352A}
.cr2-band{height:64px;padding:12px 16px;background:linear-gradient(135deg,color-mix(in srgb,var(--c) 92%,#000),color-mix(in srgb,var(--c) 74%,var(--surface)));color:#fff}
.cr2-id{display:flex;align-items:flex-start;gap:12px;padding:0 16px;margin-top:-30px}
.cr2-id > div{padding-top:34px}
.cr2-ring{width:66px;height:66px;color:var(--c)}
.cr2-ring svg{width:46%;height:46%}
.cr2-id > div{display:grid;padding-bottom:2px}
.cr2-lv{font:800 1.35rem/1.15 var(--display)}
.cr2-big{padding:14px 16px 6px;color:var(--muted);font-size:.95rem}
.cr2-big > b{font:800 2.4rem/1 var(--display);color:var(--ink)}
.cr2-big span b{color:var(--ink)}
.cr2-meter{margin:0 16px;height:10px;border-radius:99px;background:color-mix(in srgb,var(--c) 15%,var(--surface));overflow:hidden}
.cr2-meter i{display:block;height:100%;border-radius:99px;background:var(--c)}
.cr2-over{margin:6px 16px 10px}.cr2-over b{color:var(--late)}
/* one grid for every row (each row a subgrid), so the hours line up in one column and the bars all start and end together */
.cr2-courses{list-style:none;margin:0 16px;padding:0;display:grid;grid-template-columns:fit-content(140px) 1fr auto;gap:8px 10px}   /* (the name column is only as wide as the longest code, so the bars start right after it) */
.cr2-courses li{grid-column:1/-1;display:grid;grid-template-columns:subgrid;align-items:center;font:700 .82rem var(--display)}
.cr2-courses li span:first-child{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.cr2-cb{height:8px;border-radius:99px;background:color-mix(in srgb,var(--c) 15%,var(--surface));overflow:hidden}
.cr2-cb i{display:block;height:100%;border-radius:99px;background:var(--c)}
.cr2-go{margin:16px 16px 0;justify-content:center}
.cr2-chart{padding:16px 16px 12px;display:flex;flex-direction:column;min-width:0}
.cr2-plot{position:relative;flex:1;min-height:260px;margin:10px 0 0 34px}
.cr2-grid{position:absolute;inset:0 0 34px 0;pointer-events:none}
.cr2-grid span{position:absolute;left:0;right:0;border-top:1px solid color-mix(in srgb,var(--line) 70%,transparent)}
