.cr3-due{font-size:.66rem;font-weight:700;color:var(--dc)!important}
.cr3-box{border:1px solid var(--line)!important;border-radius:16px!important;background:var(--surface)!important;padding:14px!important;display:grid;gap:10px}
.cr3-bh{display:flex;align-items:center;gap:10px;flex-wrap:wrap}
.cr3-bh h3{margin:0;flex:1;font:800 1.05rem var(--display)}
.cr3-chg{display:inline-flex;align-items:center;gap:6px;color:var(--muted)}
.cr3-moves{list-style:none;margin:0;padding:0;display:grid;gap:8px}
.cr3-moves li{display:grid;gap:2px;padding:8px 12px;border-radius:12px;border-left:4px solid var(--c);background:color-mix(in srgb,var(--c) 7%,var(--surface))}
.cr3-moves b{font-size:.92rem;overflow-wrap:anywhere}
.cr3-h{margin:4px 0 0;font:800 1.05rem var(--display)}
.cr3 .cr-items{display:grid;gap:8px}
.cr3 .cr-items > li{border:1px solid var(--line);border-left:4px solid var(--c,var(--line));border-radius:12px;padding:10px 12px;background:var(--surface)}
.cr3 .cr-items .ttl .link-btn{font-weight:700;color:var(--ink);text-align:left}
/* Companion ring a little smaller so the companion fills it */
.cpt3-ring{width:116px!important;height:116px!important;margin-top:-58px!important}
.cpt3-ring .cpt-face{width:98px!important;height:98px!important}
/* Change Companion: other themes in a drop-down */
.cp-oth-d{border:1px solid var(--line);border-radius:14px;padding:0 12px;background:var(--surface)}
.cp-oth-d > summary{cursor:pointer;min-height:46px;display:flex;align-items:center;font:700 .95rem var(--display)}
.cp-oth-d[open]{display:grid;gap:10px;padding-bottom:12px}
.cp-oth-g h4{margin:6px 0;font:700 .88rem var(--display);display:flex;align-items:center;gap:6px}
.cp-oth-list{display:grid;grid-template-columns:repeat(auto-fill,minmax(96px,1fr));gap:8px}
.cp-oth{display:grid;justify-items:center;gap:4px;padding:8px 4px;border:1px solid var(--line);border-radius:12px;background:var(--surface);color:inherit;font:600 .78rem var(--display);cursor:pointer}
.cp-oth:hover{border-color:var(--accent)}
/* Edit Task: the label sits in the band, the task's name is the big title; bigger pencil */
.g2-sheet-head .sh-ring svg{width:50%!important;height:50%!important}
.sh-big .sh-kick{position:absolute;left:116px;top:16px;color:#fff;font:800 1.3rem var(--display);letter-spacing:.02em;text-shadow:0 1px 2px rgba(0,0,0,.25)}
.sh-big h2.sh-name{font:800 1.45rem/1.2 var(--display);overflow-wrap:anywhere;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}
@media (max-width:600px){.sh-big .sh-kick{left:96px;top:22px}.sh-big h2.sh-name{font-size:1.2rem}}
/* Sheets without a task name: the title sits in the colour band, larger and centred in it */
.g2-sheet-head:not(.sh-big) .sh-t h2{position:absolute;left:116px;right:64px;top:0;height:62px;display:flex;align-items:center;color:#fff;font:800 1.5rem/1.1 var(--display);text-shadow:0 1px 2px rgba(0,0,0,.25);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.g2-sheet-head:not(.sh-big):not(:has(.sh-t .mini)){min-height:104px;padding-top:62px!important}
/* A sheet whose title sits in the band: the ring rides higher, about half over the band, and the title sits a little below the band's middle, nearer the ring's */
.g2-sheet-head:not(.sh-big) .sh-t h2{top:6px!important}
.g2-sheet-head:not(.sh-big) .sh-ring{top:12px}
@media (max-width:600px){.g2-sheet-head:not(.sh-big) .sh-ring{top:14px}}
@media (max-width:600px){.g2-sheet-head:not(.sh-big) .sh-t h2{left:96px;font-size:1.3rem}}
.pomo-sheet .g2-sheet-head .sh-ring svg{width:66%!important;height:66%!important}
/* ===== Timeline, Direction 1 (A): course bands, due-date dots with their icons and dates ===== */
.tl-scroll{border-radius:18px!important;box-shadow:0 2px 8px rgba(14,42,86,.08)}
.tl-row.tl-group{z-index:1;height:42px;background:linear-gradient(120deg,color-mix(in srgb,var(--c) 90%,#000),color-mix(in srgb,var(--c) 74%,var(--surface)))!important;color:#fff}
.tl-group .tl-label{background:color-mix(in srgb,var(--c) 90%,#000)!important;color:#fff;gap:10px!important;border-right-color:transparent!important;font:800 .9rem var(--display)!important}
.tl-gic{display:grid;place-items:center;width:28px;height:28px;flex:none;border-radius:50%;background:#fff}
.tl-gic svg{width:70%;height:70%;display:block}
.tl-group .tl-track{display:flex;align-items:center;justify-content:space-between;padding:0 14px;font:600 .8rem var(--display);color:#fff}
.tl-gname{opacity:.9;position:sticky;left:240px}
.tl-gn{position:sticky;right:14px;font-weight:800}
.tl-dl{position:absolute;top:50%;transform:translateY(-50%);display:inline-flex;align-items:center;gap:6px;font:700 .74rem var(--display);color:var(--muted);white-space:nowrap;pointer-events:none}
.tl-dl.late{color:var(--late)}
.tl-dl em{font-style:normal;font:800 .66rem var(--display);padding:2px 7px;border-radius:999px;background:color-mix(in srgb,var(--late) 14%,var(--surface));color:var(--late)}
.tl-label small{color:var(--muted)}
.tl-controls .segb,.tl-controls .btn{border-radius:999px}
/* Pill toggles: the selected segment follows the pill's curve instead of sitting square inside it */
.tl-controls .segb button,.cr2-range button,.segb:has(> [data-act="f-sort"]) button{border-radius:999px}
.cr2-range,.segb:has(> [data-act="f-sort"]){border-radius:999px}
/* Page-heading buttons (Review, Archive, Recently Deleted) are pills too */
.view-head > .btn{border-radius:999px}
/* Every button is a pill (menu rows inside a More menu stay square-ish) */
.btn,.btn.big,:root[data-skin] .btn.primary{border-radius:999px}
/* Every segmented selector (Status, Priority, view switchers, sub-page tabs) is a pill, and so is its selected segment */
.seg,.seg span,.segb,.segb button,.bview-tabs,.bview-tabs button,.pview-tabs,.pview-tabs button,.us-subs,.us-sub-tab{border-radius:999px}
/* ===== Schedule, Direction 1: tinted class blocks with a course-colour edge, a calmer grid ===== */
.sch-wrap{border-radius:18px!important;box-shadow:0 2px 8px rgba(14,42,86,.08)!important}
.sch-head{background:var(--surface)!important;min-height:58px;padding:10px 8px!important}
.sch-dn span{font-size:.72rem!important;font-weight:700!important}
.sch-dn b{font:800 1.2rem var(--display)!important}
.sch-head.is-today{background:color-mix(in srgb,var(--accent) 8%,var(--surface))!important}
.sch-head.is-today .sch-dn span{color:var(--accent)}
.sch-head.is-today .sch-dn b{background:var(--accent)!important;color:#fff;border-radius:999px!important;padding:0 8px!important}
.sch-col{background-image:repeating-linear-gradient(to bottom,transparent 0 55px,color-mix(in srgb,var(--line) 60%,transparent) 55px 56px)!important}
.sch-col.is-today{background-color:color-mix(in srgb,var(--accent) 5%,transparent)}
.sch-b{container-type:size;border-radius:10px!important;padding:6px 9px 6px 10px!important;background:color-mix(in srgb,var(--c) 16%,var(--surface))!important;color:var(--ink)!important;border:0!important;border-left:4px solid var(--c)!important;box-shadow:0 1px 3px rgba(8,20,50,.12)!important;gap:2px!important}
.sch-b b{color:color-mix(in srgb,var(--c) 72%,var(--ink));font:800 .8rem/1.2 var(--display)!important}
.sch-b span{opacity:1!important;color:var(--muted)}
.sch-b:hover{filter:none!important;background:color-mix(in srgb,var(--c) 24%,var(--surface))!important}
.sch-b.k-lab{background:repeating-linear-gradient(135deg,color-mix(in srgb,var(--c) 18%,var(--surface)) 0 8px,color-mix(in srgb,var(--c) 26%,var(--surface)) 8px 16px)!important}
.sch-b.k-officehours{background:color-mix(in srgb,var(--c) 6%,var(--surface))!important;border:1.5px dashed color-mix(in srgb,var(--c) 70%,transparent)!important;border-left:4px solid var(--c)!important;box-shadow:none!important}
.sch-b.k-discussion{background:color-mix(in srgb,var(--c) 10%,var(--surface))!important}
/* class meetings: a card like the board's task cards: a band in the course colour with its icon and code, then the details */
.sch-b:has(> .sch-band){display:flex!important;flex-direction:column;padding:0!important;gap:0!important;background:var(--surface)!important;color:var(--ink)!important;border:1px solid color-mix(in srgb,var(--c) 35%,var(--line))!important;border-radius:12px!important;box-shadow:0 2px 8px rgba(8,20,50,.14)!important}
.sch-b:has(> .sch-band):hover{background:color-mix(in srgb,var(--c) 6%,var(--surface))!important}
.sch-b > .sch-band{flex:none;display:flex;align-items:center;gap:6px;min-width:0;padding:4px 8px;background:linear-gradient(120deg,color-mix(in srgb,var(--c) 88%,#000),color-mix(in srgb,var(--c) 74%,var(--surface)));color:#fff}
.sch-b > .sch-band .cc-ic{width:16px;height:16px}
.sch-b > .sch-band b{min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;color:#fff!important;font:800 .72rem/1.2 var(--display)!important;letter-spacing:.04em}
.sch-b > .sch-bd{display:grid;gap:1px;align-content:start;min-height:0;padding:4px 8px 5px}
.sch-b > .sch-bd span{white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.sch-b > .sch-bd span:first-child{color:var(--ink)!important;font-weight:600}
.sch-b > .sch-bd .sch-t{font:700 .78rem/1.25 var(--display)}
.sch-b.k-lab:has(> .sch-band){background:repeating-linear-gradient(135deg,color-mix(in srgb,var(--c) 5%,var(--surface)) 0 8px,color-mix(in srgb,var(--c) 12%,var(--surface)) 8px 16px)!important}
.sch-b.k-other,.sch-b.k-event{background:color-mix(in srgb,var(--c) 12%,var(--surface))!important}
.sch-b.sch-exam{background:color-mix(in srgb,var(--late) 10%,var(--surface))!important;border-left-color:var(--late)!important}
.sch-b.sch-exam b{color:var(--late)}
/* short classes: name and time only, nothing clipped */
@container (max-height:44px){.sch-b span:nth-of-type(2),.sch-b span:nth-of-type(3){display:none}}
@container (max-height:24px){.sch-b span{display:none}}
.sch-chip{border-radius:8px!important;border-left-width:4px!important;padding:4px 7px!important;background:color-mix(in srgb,var(--c) 12%,var(--surface))!important;font-weight:700!important}
.sch-nav .btn,.view-head .sch-nav .btn{border-radius:999px}
.sch-now{height:2px!important}
.sch-now::before{content:"";position:absolute;left:-5px;top:-4px;width:10px;height:10px;border-radius:50%;background:var(--late)}
/* ===== Notes, Direction 1: the cork and stickers stay; the frame around them matches the rest of the app ===== */
.nb-boards{gap:6px!important;padding:4px;border:1px solid var(--line);border-radius:999px;background:var(--surface);width:max-content;max-width:100%}
.nb-tab{border:0!important;background:none!important;box-shadow:none!important;min-height:36px!important;padding:6px 14px!important;font-weight:700!important;color:var(--muted)!important}
.nb-tab.on{background:color-mix(in srgb,var(--c,var(--accent)) 16%,var(--surface))!important;color:color-mix(in srgb,var(--c,var(--accent)) 65%,var(--ink))!important}
.nb-tab .n{background:color-mix(in srgb,var(--line) 70%,transparent)!important}
.nb-tab.add{color:var(--accent)!important}
.nb-boards{align-items:center}
.nb-boards :is([data-act="nb-edit"],[data-act="wb-opts"]){flex:none;width:34px!important;height:34px!important;min-width:0!important;min-height:0!important;padding:0!important;border:0!important;border-radius:50%!important;background:color-mix(in srgb,var(--line) 55%,transparent)!important;box-shadow:none!important;color:var(--ink)!important}
.nb-boards :is([data-act="nb-edit"],[data-act="wb-opts"]):hover{background:var(--line)!important}
.nb-main{padding:10px;border:1px solid var(--line);border-radius:18px;background:var(--surface);box-shadow:0 2px 8px rgba(14,42,86,.08)}
.nb-scroll{border-radius:12px!important;border:0!important}
.nb-targets{gap:8px!important}
.nb-target{width:auto!important;height:auto!important;flex-direction:row!important;gap:6px!important;padding:8px 14px!important;border-radius:999px!important;border:1px solid var(--line)!important;background:var(--surface)!important;box-shadow:0 2px 8px rgba(14,42,86,.14)!important;font:700 .8rem var(--display)!important}
.nb-target svg{width:18px!important;height:18px!important}
/* Desktop: the board and the sticker envelope run further down the page (less empty space under them), bottoms aligned */
@media (min-width:721px){
  .nb-scroll{height:calc(100dvh - 270px)!important}
  .env{margin-top:11px;height:calc(100dvh - 270px);max-height:none!important}
}
/* Rings at 1x: one solid ring hugging the white disc (no dark gap ring), so there are fewer hard edges to stair-step */
.g2-ring{box-shadow:0 0 0 3px var(--c),0 3px 9px rgba(0,0,0,.18)!important}
.gp-ring.sm,.pr-ring,.card-ring{box-shadow:0 0 0 2px var(--c)!important}
.cpt3-ring{box-shadow:0 0 0 4px var(--c),0 6px 14px rgba(0,0,0,.18)!important}
.ci-svg{stroke-width:1.5!important;--ci-ink:color-mix(in srgb,var(--c) 52%,#071022)!important}
/* Small course icons: a white disc behind the inline icon on rows, heavier lines on the tiny white glyphs, so they hold up at 1x */
/* The course icon on Do This Next and plan rows: the icon alone (like the Task Board's), in the course colour; white in dark mode */
.nu-ic{width:24px!important;height:24px!important;border-radius:0;background:none;box-shadow:none;vertical-align:-5.5px!important}
/* the check circle, the icon and the title's first line share one centre line */
.next-up .nu-row > .check{position:relative;top:-2px}
/* Deck previews (Review > Flashcards): the plain card edge, never the theme's coloured card outline (that stays on the cards you study) */
.deck .face,.deck .deck-lay .face{border:0!important;outline:0!important;box-shadow:0 0 0 1px var(--line),0 12px 30px rgba(14,42,86,.14)!important}
.deck .deck-lay .face{box-shadow:0 0 0 1px var(--line)!important}   /* drawn as a ring outside the card (not a border inside it), so the coloured band reaches the outline with no light sliver between */
.deck .deck-lay{border:0!important;outline:0!important;box-shadow:none!important;background:none!important}
/* The cards behind sit 6px lower and right, less than the 8px corner, so their light tops peeked into the front card's rounded
   corners (a white sliver, most visible when zoomed out). Each is cut off at the top only, just below the corner of the card in front
   of it, except at the right, where it shows past the front card: there its own rounded top corner stays (the clip sits 4px outside
   its edges, past the outline). */
/* A little shorter deck cards: less padding around the band, the name and the buttons (same text and button sizes) */
.deck.deck-fc .fc-band{padding-top:7px!important;padding-bottom:7px!important}
.deck.deck-fc .deck-main{padding-top:10px!important;padding-bottom:6px!important;gap:6px!important}
.deck.deck-fc .deck-actions{padding-bottom:10px!important}
/* a little taller again, and all the same height: the extra room goes between the name and the buttons */
.deck.deck-fc > .deck-face{height:188px;min-height:0}
/* every deck the same size: a long name stops after two lines with "...", a long course code after one */
.deck.deck-fc .deck-name{display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden;overflow-wrap:anywhere}
.deck.deck-fc .fc-band .g2-kick{flex:1;min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.deck.deck-fc .deck-main{min-height:0;overflow:hidden}
.deck.deck-fc .deck-lay.l2 .face{clip-path:polygon(-4px 8px,calc(100% - 14px) 8px,calc(100% - 14px) -4px,calc(100% + 4px) -4px,calc(100% + 4px) calc(100% + 4px),-4px calc(100% + 4px))}
.deck.deck-fc .deck-lay.l3 .face{clip-path:polygon(-4px 10px,calc(100% - 20px) 10px,calc(100% - 20px) -4px,calc(100% + 4px) -4px,calc(100% + 4px) calc(100% + 4px),-4px calc(100% + 4px))}
/* and just slightly rounded corners, like the flashcard itself when it's open (the preview is about half its size) */
.deck .face,.deck .deck-face,.deck .deck-lay,.deck .deck-lay .face,.deck.deck-fc > .deck-face,.deck.deck-fc .deck-lay .face{border-radius:8px!important;border-top-left-radius:8px!important}
/* an icon's lines may reach a little past its frame: never cut them off */
svg.ci-svg{overflow:visible!important}
/* Small course icons (Task Board cards, Do This Next, schedule blocks): lines drawn exactly 2 screen pixels wide, whatever the icon's
   size, instead of a fraction of a pixel (1.7px at 18px), which looked rough at 100% display scaling */
:is(.cc-ic,.nu-ic,.fc-ic) svg.ci-svg :is(path,circle,ellipse,rect,line,polyline,polygon){vector-effect:non-scaling-stroke}
:is(.cc-ic,.nu-ic,.fc-ic) svg.ci-svg{stroke-width:2!important;shape-rendering:geometricPrecision}
.nu-ic svg.ci-svg{width:100%!important;height:100%!important;stroke-width:2!important;stroke:var(--c);--ci-ink:var(--c)}
.nu-ic svg .a,.nu-ic svg .b,.nu-ic svg .y,.nu-ic svg .g,.nu-ic svg .r{fill:color-mix(in srgb,var(--c) 22%,transparent)}
.nu-ic svg .sa,.nu-ic svg .sb{stroke:var(--c)}
:root[data-theme="dark"] .nu-ic svg.ci-svg,:root[data-theme="dark"] .nu-ic svg .sa,:root[data-theme="dark"] .nu-ic svg .sb{stroke:#fff;--ci-ink:#fff}
:root[data-theme="dark"] .nu-ic svg .a,:root[data-theme="dark"] .nu-ic svg .b,:root[data-theme="dark"] .nu-ic svg .y,:root[data-theme="dark"] .nu-ic svg .g,:root[data-theme="dark"] .nu-ic svg .r{fill:rgba(255,255,255,.3)}
@media (prefers-color-scheme:dark){
  :root:not([data-theme="light"]) .nu-ic svg.ci-svg,:root:not([data-theme="light"]) .nu-ic svg .sa,:root:not([data-theme="light"]) .nu-ic svg .sb{stroke:#fff;--ci-ink:#fff}
  :root:not([data-theme="light"]) .nu-ic svg .a,:root:not([data-theme="light"]) .nu-ic svg .b,:root:not([data-theme="light"]) .nu-ic svg .y,:root:not([data-theme="light"]) .nu-ic svg .g,:root:not([data-theme="light"]) .nu-ic svg .r{fill:rgba(255,255,255,.3)}
}
.cc-ic svg.ci-svg,.fc-ic svg.ci-svg{stroke-width:2.1!important}
.tl-gic svg.ci-svg{stroke-width:1.8!important}
/* Sticker art in rings: a softer, slightly finer outline than on the note board, where it is drawn much bigger */
.g2-ring > svg:not(.ci-svg){width:80%!important;height:80%!important}
.g2-ring > svg:not(.ci-svg) [stroke="#2B2233"]{stroke:#4A4058;stroke-width:2.1}
/* Colour bands: one recipe everywhere, made only from the band's own colour, so the same colour looks the same in light and dark.
   Bands with no course or group colour use the theme's main colour as it is in light mode (--accent-band), in both modes. */
:root{--accent-band:#1A60D0}
.g2-band,.c2-band,.gp-hero-band,.cr2-band,.next-up .nu-top,.g2-sheet-head,.cpt3-band,.tl-row.tl-group,.card.has-tab > .card-course,.fc-band,.sch-b > .sch-band{background:linear-gradient(120deg,color-mix(in srgb,var(--c) 88%,#000),color-mix(in srgb,var(--c) 74%,var(--surface)))!important}
/* Timeline course rows: the sticky name column and the long track are separate boxes. The name column is the band's deep colour, and the
   track starts at exactly that colour where it comes out from under the name column (--tls, kept equal to how far the timeline is scrolled)
   and fades across the visible width (--tlv), so there is no jump where they meet at any scroll position. */
.tl-scroll .tl-row.tl-group{--ba:color-mix(in srgb,var(--c) 88%,#000);--bb:color-mix(in srgb,var(--c) 74%,var(--surface));background:none!important}
.tl-scroll .tl-group .tl-label{background:var(--ba)!important;border-right:0!important;box-shadow:none!important}
.tl-scroll .tl-group .tl-track{background:linear-gradient(90deg,var(--ba) var(--tls,0px),var(--bb) calc(var(--tls,0px) + var(--tlv,1000px)))!important}
/* sheet heads: the band is only the top strip; the title below sits on the sheet */
.g2-sheet-head{background-size:100% 62px!important;background-repeat:no-repeat!important;background-position:top!important}
.gp-hero-band{--c:var(--accent-band)!important}
.gp-cap{color:var(--accent-band)!important}
/* Side bar icons: drawn at their native 24px on whole pixels in the roomy layout, so each 2px line lands on the pixel grid (21px blurred
   every line). The compact layouts (data-fit) keep their sizes, with lines held at exactly 2px. */
nav.tabs svg :is(path,rect,circle,line,polyline,polygon,ellipse){vector-effect:non-scaling-stroke}
@media (min-width:980px){
  nav.tabs:is([data-fit="0"],:not([data-fit]),[data-fit="1"],[data-fit="2"]) .in button svg,nav.tabs:is([data-fit="0"],:not([data-fit]),[data-fit="1"]) .nav-foot button svg{width:24px!important;height:24px!important}
  nav.tabs:is([data-fit="0"],:not([data-fit]),[data-fit="1"],[data-fit="2"]) .in button:not(.nav-focus){font-size:12px!important;line-height:14px!important;padding:0 4px!important;height:52px;min-height:0!important;flex:none!important;gap:4px!important}
  nav.tabs:is([data-fit="1"],[data-fit="2"]) .in button:not(.nav-focus){height:46px}
  nav.tabs:is([data-fit="1"],[data-fit="2"]) .nav-brand img{height:64px;width:94px!important}
  nav.tabs[data-fit="1"] .nav-foot .nav-tool{height:44px!important;padding:1px 4px!important}
  nav.tabs:is([data-fit="0"],:not([data-fit]),[data-fit="1"],[data-fit="2"]) .in{gap:2px!important}
  nav.tabs:is([data-fit="0"],:not([data-fit]),[data-fit="1"],[data-fit="2"]) .nav-brand img{height:72px;width:106px!important}
