.cs-demo .face-label{font-size:min(.72rem,7cqi)!important}
.cs-demo.cs-ticket .face-text{font-size:min(1rem,7.2cqi)!important}
.cc-sw{gap:8px}
.cc-sw span{width:32px;height:32px}
.cc-custom span{background:conic-gradient(from 0deg,#ef4444,#f59e0b,#eab308,#22c55e,#06b6d4,#3b82f6,#8b5cf6,#ec4899,#ef4444)!important;position:relative}
.cc-custom span::after{content:"";position:absolute;inset:7px;border-radius:50%;background:var(--c);box-shadow:0 0 0 2px var(--surface)}
