.gp-hero .gp-course{flex-wrap:wrap}
.gp-tog svg{transition:transform .2s}
.gp-tog[aria-expanded="true"] svg{transform:rotate(180deg)}
.gp-drop{flex-basis:100%;display:grid;grid-template-columns:minmax(0,1.3fr) minmax(0,1fr);gap:14px;margin:6px 0 10px 58px;padding:14px;border:1px solid var(--line);border-left:4px solid var(--c);border-radius:14px;background:color-mix(in srgb,var(--soft) 50%,var(--surface))}
.gp-drop[hidden]{display:none}
.gp-drop > section{min-width:0;margin:0;padding:0;border:0;background:none;box-shadow:none}
.gp-d-h{display:flex;align-items:center;gap:8px;margin:0 0 8px;font:800 .8rem var(--display);letter-spacing:.06em;text-transform:uppercase;color:var(--muted)}
.gp-d-h .spacer{flex:1}
.gp-d-calc .gp-calc-out{margin-top:10px}
@media (max-width:760px){.gp-drop{grid-template-columns:1fr;margin-left:0}}
/* Files, Direction 1: band header with the course ring, course rings in the folder list, pill buttons on rows */
.fhead.g2-head{margin:0 0 10px;padding:0;border:1px solid var(--line);border-radius:18px;background:var(--surface);box-shadow:0 2px 8px rgba(14,42,86,.08);overflow:hidden}
.fhead .g2-band{border-radius:17px 17px 0 0}
.fhead .fcrumb{margin:0;font:800 1.35rem/1.2 var(--display)}
.fhead .g2-ring svg:not(.ci-svg){width:46%;height:46%;color:var(--c)}
/* A primary button on a course-coloured band is white with course-coloured text: the glass layer under it must be white too, not the theme's
   button gradient (that made Study on a deck's page unreadable: dark gold text on a pink and purple gradient) */
html #view :is(.g2-head,.c2-head) .g2-band .btn.primary::before,html dialog :is(.g2-head,.c2-head) .g2-band .btn.primary::before{background:#fff}
.dk2 > .g2-band:has(> .row-actions){padding-bottom:36px}
/* On a wide screen the deck's buttons sit to the right of the ring, so the band only needs as much space under them as above them */
@media (min-width:720px){.dk2 > .g2-band:has(> .row-actions){padding-bottom:10px}}
/* Course, Files and deck headers: a shorter band, the ring's top third over it, and the title centred beside the ring */
.g2-head .g2-band,.c2-head .g2-band{min-height:58px;padding:10px 18px}
.g2-head .g2-low,.c2-head .g2-low{margin-top:-32px}
.g2-head .g2-txt,.c2-head .g2-txt{padding-top:42px}
/* The ring sits a little lower than the low row so it has room under the course code at the top of the band */
.g2-head .g2-low > .g2-ring,.c2-head .g2-low > .g2-ring{margin-top:10px}
.fhead .fcrumb{font-size:1.75rem;line-height:1.15}
@media (max-width:719px){
  .g2-head .g2-band,.c2-head .g2-band{min-height:0;padding:10px 14px 30px}
  .g2-head .g2-low,.c2-head .g2-low{margin-top:-26px}
  .g2-head .g2-txt,.c2-head .g2-txt{padding-top:36px}
  .fhead .fcrumb{font-size:1.4rem}
}
/* Files header: the title sits on the card, so no scenic-theme legibility box behind it; a smaller ring, and the title a touch higher */
html .fhead .fcrumb{background:none!important;padding-inline:0!important;text-shadow:none!important;box-shadow:none!important}
.fhead.g2-head .g2-low > .g2-ring{width:66px;height:66px}
.fhead .g2-ring > svg:not(.ci-svg){width:56%!important;height:56%!important}
.fhead .g2-ring > svg.ci-svg{width:60%!important;height:60%!important}
.fhead.g2-head .g2-txt{padding-top:36px;gap:0}   /* (the item count moves up with the title) */
@media (max-width:719px){.fhead.g2-head .g2-low > .g2-ring{width:54px;height:54px}.fhead.g2-head .g2-txt{padding-top:30px}}
.fn-ring{display:grid!important;place-items:center;width:24px!important;height:24px!important;flex:0 0 24px!important;padding:0!important;border-radius:50%;background:#fff;box-shadow:0 0 0 1.5px var(--c,var(--line))}
.fn-ring svg{width:68%;height:68%;display:block}
.fn-ring.fn-all svg{color:var(--c);width:60%;height:60%}
.fnode .fn-name{flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
@media (max-width:820px){.fnode .fn-name{overflow:visible;flex:none}}
.fnode.on{background:color-mix(in srgb,var(--c,var(--accent)) 14%,var(--surface))!important;border-color:color-mix(in srgb,var(--c,var(--accent)) 40%,transparent)!important}
.fnode.sub{padding-left:42px}
.flist{border-radius:16px!important;overflow:hidden}
.frow{transition:background .15s}
.frow:hover{background:color-mix(in srgb,var(--soft) 50%,var(--surface))}
.frow > a.btn{text-decoration:none!important;border-radius:999px;padding-inline:14px}
.frow > .f-sum{border-radius:999px;padding-inline:12px;gap:6px;display:inline-flex;align-items:center}
.frow > .f-sum svg{width:14px;height:14px}
@media (max-width:640px){.frow > .f-sum{padding-inline:9px}.frow > .f-sum .f-sum-l{display:none}}
.fpane .fsec{padding:4px 12px;border-radius:999px;background:color-mix(in srgb,var(--soft) 70%,var(--surface));border:1px solid var(--line);width:max-content;font-size:.85rem}
.gt-dot{display:inline-block;border-style:dashed!important;opacity:.7;pointer-events:none}
.gt-chip{background:color-mix(in srgb,#C9702B 18%,var(--surface))!important;color:color-mix(in srgb,#C9702B 70%,var(--ink))!important}
.sort-ghost{position:fixed!important;z-index:200;pointer-events:none;margin:0!important;transform:rotate(1.5deg) scale(1.02);box-shadow:0 18px 40px rgba(0,0,0,.35);opacity:.95;transition:none!important}
.sort-hole{opacity:.25;outline:2px dashed var(--line);outline-offset:4px;border-radius:18px}
body.sorting,body.sorting *{cursor:grabbing!important;user-select:none!important;-webkit-user-select:none!important}
[data-sortable] > [data-sort-id]{-webkit-touch-callout:none}
.ci-ai-btn{display:grid;place-items:center;align-content:center;gap:2px;aspect-ratio:1;border:2px dashed var(--line);border-radius:50%;background:none;color:var(--accent);font:800 .62rem var(--display);cursor:pointer;position:relative;padding:0}
.ci-ai-btn svg{width:26px;height:26px}
.ci-ai-btn .cp-ai-face.ai-ic{width:32px;height:32px;min-width:32px;margin:0;vertical-align:0;justify-self:center;display:grid;place-items:center}   /* the companion's face, big and centred over Create */
.ci-ai-btn .cp-ai-face > svg.cp-svg{inset:0!important;width:100%!important;height:100%!important;display:block}
.ci-ai-btn > span:not(.cp-ai-face){display:block;text-align:center;line-height:1.1}
.ci-ai-btn .pro-badge{position:absolute;top:-6px;right:-8px;transform:scale(.8)}
.ci-ai{margin-top:12px;padding:12px;border:1px solid var(--line);border-radius:14px;background:color-mix(in srgb,var(--soft) 50%,var(--surface))}
.ci-ai-row{display:flex;align-items:center;gap:10px;flex-wrap:wrap;margin-top:8px}
.ci-ai-prev{display:inline-flex;align-items:center;gap:10px;font-weight:700}
.ci-ai-ring{width:56px;height:56px}
.beta-sym{display:inline-grid;place-items:center;width:17px;height:17px;margin-left:5px;border-radius:50%;background:linear-gradient(135deg,#FFB443,#FF5C8A);color:#fff;font:700 .7rem/1 var(--body);vertical-align:2px}
.ci-cand{display:grid;justify-items:center;gap:4px;border:2px solid transparent;border-radius:14px;background:none;padding:6px 8px;font:700 .78rem var(--display);color:var(--ink);cursor:pointer;max-width:110px;text-align:center}
.ci-cand.on{border-color:var(--accent);background:color-mix(in srgb,var(--accent) 8%,var(--surface))}
.ci-ai-prev:has(.ci-cand){flex-wrap:wrap;gap:6px}
.ci-src{flex-basis:100%}
/* Style Shop S2: themed band header, category rail on the left (a strip on phones) */
.sheet.shop .sheet-head.shop-band{position:relative;display:block;padding:16px 64px 16px 20px!important;background:linear-gradient(135deg,color-mix(in srgb,var(--accent-band,var(--accent)) 86%,#000),var(--accent-band,var(--accent)))!important;color:#fff;border-bottom:0!important}
.shop-band h2{color:#fff!important;margin:0;font:800 1.35rem var(--display)!important}
.shop-band .shop-sub{margin:3px 0 0;font-size:.84rem;opacity:.92;display:flex;align-items:center;gap:6px;flex-wrap:wrap}
.shop-band > .icon-btn{position:absolute;right:14px;top:50%;transform:translateY(-50%);background:rgba(255,255,255,.18)!important;border-color:rgba(255,255,255,.5)!important;color:#fff!important}
.shop-wrap{display:grid;grid-template-columns:220px minmax(0,1fr);min-height:0;flex:1}
.shop-wrap > .sheet-body{min-height:0;overflow:auto}
.shop-rail{display:grid;gap:4px;align-content:start;padding:14px 12px;border-right:1px solid var(--line);background:color-mix(in srgb,var(--soft) 40%,var(--surface));overflow:auto}
.shop-rail .sr-item{display:flex;align-items:center;gap:10px;width:100%;min-height:44px;padding:7px 10px;border:0;border-radius:12px;background:none;color:var(--muted);font:700 .92rem var(--display);text-align:left;cursor:pointer}
.shop-rail .sr-item:hover{color:var(--ink);background:color-mix(in srgb,var(--soft) 70%,transparent)}
.shop-rail .sr-item[aria-selected="true"]{background:color-mix(in srgb,var(--accent-band,var(--accent)) 18%,var(--surface));color:var(--ink)}
.sr-ic{display:grid;place-items:center;width:30px;height:30px;flex:none;border-radius:50%;background:#fff;color:var(--accent-band,var(--accent));box-shadow:0 0 0 1.5px color-mix(in srgb,var(--accent-band,var(--accent)) 45%,transparent)}
.sr-ic svg{width:17px;height:17px}
.sr-t{flex:1;min-width:0}
.sr-n{font-style:normal;font-size:.72rem;opacity:.75;white-space:nowrap}
@media (max-width:720px){
  .shop-wrap{grid-template-columns:1fr;grid-template-rows:auto minmax(0,1fr)}
  .shop-rail{display:flex;gap:6px;padding:8px 12px;border-right:0;border-bottom:1px solid var(--line);overflow-x:auto;scrollbar-width:none}
  .shop-rail::-webkit-scrollbar{display:none}
  .shop-rail .sr-item{width:auto;flex:none;min-height:40px;padding:5px 12px 5px 6px;border-radius:999px}
  .shop-rail .sr-n{display:none}
  .sheet.shop .sheet-head.shop-band{padding:12px 60px 12px 16px!important}
  .shop-band .shop-sub{font-size:.74rem;line-height:1.35}
  .sr-ic{width:26px;height:26px}
}
/* ===== module: 101-phone-v2.css ===== */
/* Saving is automatic, so the header says nothing about it unless there's a problem. Guests save to an account from Settings. */
#guestBadge,#guestBadgeSide{display:none!important}
.sync:is([data-state="ok"],[data-state="busy"]){display:none!important}   /* (the desktop side bar keeps its green Saved dot, .nav-sync) */
/* The page area takes focus after a page change (so screen readers start there); it is not a control, so no outline around the whole page */
#view:focus,#view:focus-visible,main[tabindex="-1"]:focus{outline:none!important;box-shadow:none!important}
/* Phones and tablets: the page itself never slides sideways or rubber-bands (iOS lets a touch drag the whole page around when anything
   is a hair wider than the screen); it scrolls up and down, and the parts that scroll sideways (board columns, chips) still do, inside themselves. */
@media (max-width:979px){
  header.top .today{font-size:.78rem!important;line-height:1.2}   /* the date under the logo (tablets; phones show it small over the page title) */
  html{overflow-x:hidden;overscroll-behavior:none}
  body{overflow-x:clip;overscroll-behavior:none;max-width:100vw}
}
/* Phones (under 640 px wide): laid out as a phone app, not the desktop rearranged. Tablets and computers are unchanged.
   - The top bar names the page you are on (with the date over Today) and keeps three round tools: Focus, Search and Settings.
   - Seven tabs at the bottom, the companion's round seat in the middle: Board, Calendar, Review | companion | Notes, Courses, Groups.
     Small labels (icons only on the narrowest phones). The companion stands in its seat (dockSpot in 98-companion.js); tapping it
     opens its page.
   - The Add button is a round + in the corner above the bar (its name stays for screen readers).
   - Each page's switcher sits right under the title, full width; a heading that only repeats it or the title is hidden. */
.ph-title{display:none}
@media (max-width:639px){
  /* Top bar */
  /* the logo with the date under it (the bottom bar already says which page this is) */
  .top-row > div:first-child{justify-content:flex-end;min-width:0!important}
  header.top .brand{margin:0;line-height:0;min-width:0}
  header.top .brand img.logo{width:min(172px,44vw);height:auto;max-width:100%}
  /* the logo block hugs the logo so the date centres under it; the saved dot and buttons sit to the right */
  header.top .top-row > div:first-child{flex:0 1 auto!important;align-items:center!important;padding-top:6px}
  header.top .top-row > .sync{margin-left:auto}
  header.top .top-row{align-items:center!important}
  header.top .top-row > .head-actions{align-self:center!important;margin-top:0!important;margin-bottom:0!important}
  header.top .today{text-align:center;margin-top:1px!important}   /* snug under the logo */
  html header.top .today{background:none!important;padding-inline:0!important;border-radius:0!important;text-shadow:none!important}   /* no backing pill behind the date (the header is frosted already) */
  header.top .top-row > div:first-child{gap:0!important}
  /* a sync problem shows as a small amber dot (tap Settings for details) */
  header.top .top-row .sync:not([data-state="ok"]){margin-right:4px}
  header.top .today{font-size:.68rem!important;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:100%}
  .ph-title{display:none!important}
  .ph-title-unused{display:flex;flex-direction:column;min-width:0;max-width:100%;align-self:stretch;min-height:42px;justify-content:flex-end}
  .ph-k{font:700 .72rem/1.25 var(--display);letter-spacing:.05em;text-transform:uppercase;color:var(--muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
  .ph-title.ph-long .ph-t{font-size:1.42rem}
  .ph-t{font:800 1.7rem/1.1 var(--display);letter-spacing:-.015em;color:var(--ink);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
  .top-row{flex-wrap:nowrap!important;align-items:flex-end}
  .head-actions{gap:6px;align-items:center}
  .head-actions > .icon-btn,.head-actions > .pomo-btn:not(.run){width:40px;height:40px;min-width:40px;padding:0;border-radius:50%;justify-content:center}
  .head-actions > .pomo-btn.run{height:40px;padding:0 12px}
  .sync-guest{align-self:center;padding:7px 11px;font-size:.74rem}
  /* Bottom tabs: five, with the companion's seat in the middle */
  /* the bar sits low, partly in the home-indicator area; the plus keeps the same gap above it */
  :root{--ph-bar-b:max(6px,calc(var(--sb-sai-bottom,env(safe-area-inset-bottom,0px)) - 8px))}
  nav.tabs{left:10px;right:10px;padding:6px 4px;bottom:var(--ph-bar-b)}
  nav.tabs .in > :is(.nav-focus,.nav-more){display:none!important}
  nav.tabs .in > .nav-groups{display:flex}
  nav.tabs .in [data-tab="board"]{order:1}
  nav.tabs .in [data-tab="plan"]{order:2}
  nav.tabs .in [data-tab="flashcards"]{order:3}
  nav.tabs .in [data-tab="companion"]{order:4}
  nav.tabs .in [data-tab="notes"]{order:5}
  nav.tabs .in [data-tab="courses"]{order:6}
  nav.tabs .in [data-tab="groups"]{order:7}
  nav.tabs .in{grid-auto-columns:minmax(0,1fr)!important;gap:0}
  nav.tabs .in button{font-size:.62rem!important;padding:8px 0 6px;letter-spacing:-.01em;gap:4px;white-space:nowrap}
  nav.tabs .in button svg{width:22px;height:22px}
  html[data-ts="l"] nav.tabs .in button{font-size:.56rem!important}
  html[data-ts="xl"] nav.tabs .in button{font-size:.52rem!important}
  /* the companion's seat speaks for itself: its name stays for screen readers, not on the bar */
  nav.tabs .in [data-tab="companion"]{position:relative;overflow:visible;justify-content:flex-end;font-size:0!important;line-height:0!important}
  html[data-ts] nav.tabs .in [data-tab="companion"]{font-size:0!important;line-height:0!important}
  nav.tabs .in [data-tab="companion"]::after{content:"";position:absolute;left:50%;top:-16px;width:56px;height:56px;margin-left:-28px;border-radius:50%;background:color-mix(in srgb,var(--accent-band,var(--accent)) 14%,#fff);box-shadow:0 0 0 3px var(--accent-band,var(--accent)),0 0 0 6px color-mix(in srgb,var(--spine-bg,var(--spine)) 94%,transparent),0 8px 18px rgba(8,20,50,.28);z-index:-1;pointer-events:none}   /* the same ringed circle as on the Companion page */
  nav.tabs .in [data-tab="companion"] svg{position:absolute;left:50%;top:-3px;margin-left:-14px;width:28px;height:28px;color:var(--accent)}   /* the centre of the seat (top -16px, 56px across) */
  nav.tabs .in [data-tab="companion"][aria-current="page"]{background:transparent}
  nav.tabs,nav.tabs *{-webkit-tap-highlight-color:transparent}   /* no grey tap box from iOS (it flashed over the companion's old tab spot); the selected state shows the tap */
  /* the tabs either side of the seat: their "selected" box curves around the seat instead of running over it
     (seat centre: half a tab past the box's edge, 12px down; 34px across with its ring, plus a small gap) */
  /* shapes: seatCut() in 101-phone-v2.js, kept on the bar so a freshly drawn button has its shape from the first frame */
  nav.tabs.ph-seatcut .in [data-tab="flashcards"][aria-current="page"]{border-radius:0;-webkit-mask:var(--ph-selm-l) 0 0/100% 100% no-repeat;mask:var(--ph-selm-l) 0 0/100% 100% no-repeat}
  nav.tabs.ph-seatcut .in [data-tab="notes"][aria-current="page"]{border-radius:0;-webkit-mask:var(--ph-selm-r) 0 0/100% 100% no-repeat;mask:var(--ph-selm-r) 0 0/100% 100% no-repeat}
  nav.tabs .in [data-tab="companion"][aria-current="page"]::after{box-shadow:0 0 0 4px var(--accent-band,var(--accent)),0 0 0 7px color-mix(in srgb,var(--spine-bg,var(--spine)) 94%,transparent),0 8px 18px rgba(8,20,50,.28)}
  body.cp-docked nav.tabs .in [data-tab="companion"] svg{visibility:hidden}
  /* The Add button: a round + above the bar */
  .fab{width:56px;height:56px;padding:0!important;border-radius:50%!important;justify-content:center;right:16px;bottom:calc(var(--ph-bar-b) + 74px)}   /* round in every theme (some give it square-ish corners) */
  .fab span{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap}
  .fab svg{width:26px;height:26px}
  /* Page switchers: full width, right under the title */
  #view > .pview-tabs,#view > .bview-row .bview-tabs{max-width:none;width:100%;margin:2px 0 12px}
  #view > .pview-tabs button,#view > .bview-row .bview-tabs button{padding:8px 6px;font-size:1.04rem;min-height:42px;white-space:nowrap}
  #view > .bview-row{margin-top:0}
  .ph-dup{display:none!important}
  #view .view-head:not(:has(> :not(h2.ph-dup))){display:none}   /* a header with nothing left in it */
  #view > .view-head:has(> h2.ph-dup){justify-content:flex-end;min-height:0;margin-top:0}
  #view > .tl-controls:has(> h2.ph-dup){margin-top:0}
  /* Notices: one compact card, actions on one line */
  .wkr-card{padding:12px 14px}
  .wkr-acts{display:flex;flex-wrap:wrap;gap:8px}
  .wkr-acts .btn{min-height:44px;padding:6px 14px;font-size:.86rem;flex:0 0 auto}
  .wkr-acts .btn:not(.primary):last-child{border-color:transparent;background:none;box-shadow:none;color:var(--muted);text-decoration:underline;padding-inline:6px}
  /* Sheets: the main action easy to reach */
  dialog#dlg > .sheet{border-radius:22px 22px 0 0}
  dialog#dlg .sheet-foot{flex-wrap:wrap;gap:8px}
  dialog#dlg .sheet-foot > .btn.primary:last-child,dialog#dlg .sheet-foot > [data-submit].primary{flex:1 1 140px}
}
@media (min-width:640px){#view .cf-row{display:none!important}}   /* the course and board dropdowns are for phones; wide screens keep the chips */
@media (max-width:639px){
  /* Course filter: one button that opens the list of courses; on the Board, Group By sits at the other end of the same line */
  .cf-chips{display:none!important}
  .cf-row{display:flex;align-items:center;justify-content:space-between;gap:8px;margin:4px 0 12px;padding:0!important;border:0!important;background:none!important;box-shadow:none!important}
  .cf-pick{position:relative;display:inline-flex;align-items:center;gap:8px;min-height:40px;flex:0 1 auto;min-width:0;max-width:62%;padding:0 12px;border-radius:999px;background:var(--navy,var(--ink));color:#fff;font:600 .92rem var(--display);cursor:pointer}
  .cf-pick.on{background:var(--surface);color:var(--ink);border:1px solid color-mix(in srgb,var(--c) 55%,var(--line))}
  .cf-pick .dot{width:9px;height:9px;border-radius:50%;background:var(--c);flex:none}
  .cf-pick .cf-l{white-space:nowrap;overflow:hidden;text-overflow:ellipsis;min-width:0}
  .cf-pick svg{width:16px;height:16px;flex:none;opacity:.85}
  .cf-pick select{position:absolute;inset:0;width:100%;height:100%;opacity:0;cursor:pointer;font-size:16px;border:0;appearance:none}
  .cf-pick:has(select:focus-visible){outline:2px solid var(--accent);outline-offset:2px}
  .cf-row .board-ctl{margin:0;flex:none;gap:6px}
  /* Schedule: week selector and Options on one line, right above the days */
  #view > .view-head.ph-sch{margin:0 0 10px}
  .ph-sch .sch-nav{display:flex;flex-wrap:nowrap;align-items:center;gap:6px;width:100%}
  .ph-sch .sch-range{flex:1;min-width:0;text-align:center;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
  .ph-more{position:relative;flex:none;margin-left:4px}
  .ph-more > summary{list-style:none;display:inline-flex;align-items:center;gap:6px;min-height:40px;padding:0 12px;cursor:pointer}
  .ph-more > summary::-webkit-details-marker{display:none}
  .ph-more > summary svg{width:14px;height:14px;transition:transform .15s}
  .ph-more[open] > summary svg{transform:rotate(180deg)}
  .ph-menu{position:absolute;right:0;top:calc(100% + 6px);z-index:8;display:grid;gap:4px;min-width:200px;padding:6px;border:1px solid var(--line);border-radius:14px;background:var(--ph-surf,var(--surface));box-shadow:0 12px 28px rgba(8,20,50,.22)}
  .ph-menu .btn{justify-content:flex-start;width:100%;min-height:44px;border:0;box-shadow:none;background:transparent;border-radius:10px;text-align:left}
  .ph-menu .btn:hover,.ph-menu .btn:focus-visible{background:var(--soft)}
  /* Companion page: everything on one screen (a compact header, the AI notice on one line, three suggestions in a row) */
  .cpt-head.cpt3{padding-bottom:10px}
  .cpt3-band{height:58px!important;min-height:0!important}
  .cpt3-band .cpt3-acts .btn{min-height:34px;padding:4px 14px;font-size:.86rem}
  .cpt3-ring{width:96px!important;height:96px!important;margin-top:-50px!important}
  .cpt3-ring .cpt-face{width:82px!important;height:82px!important}
  .cpt-id{margin-top:4px!important}
  .cpt-id h2{font-size:1.35rem!important;line-height:1.15!important;margin:0!important}
  .cpt-id .cpt-bio{font-size:.82rem!important;line-height:1.3!important;margin:2px 12px 0!important}   /* the whole description shows, however long */
  .cpt3-tabs{margin-top:8px!important;gap:4px!important}
  .cpt3-tabs button{min-height:34px!important;padding:4px 14px!important;font-size:.9rem!important}
  .cpt-pane{gap:8px!important}
  .cpt-gate{display:flex!important;flex-wrap:nowrap!important;align-items:center;gap:10px;padding:10px 12px!important}
  .cpt-log{min-height:0!important}
  .cpt-gate p{margin:0!important;flex:1;font-size:.84rem;line-height:1.35}
  .cpt-gate .btn{flex:none;margin:0!important;min-height:38px}
  .cpt-empty{padding:6px 4px!important;min-height:0!important;gap:8px!important}
  .cpt-empty > p{font-size:.88rem;line-height:1.35;margin:0 0 8px!important}
  .cpt-empty .cpt-chips{display:flex!important;flex-wrap:wrap;justify-content:center;gap:6px!important}
  .cpt-empty .cpt-chips .chip{min-height:36px;padding:4px 12px;font-size:.82rem}
  .cpt-empty .cpt-chips .chip:nth-child(n+4){display:none}
  .cpt-priv{font-size:.7rem!important;line-height:1.3;margin-top:4px!important}
  .cf-acts{display:flex;gap:6px;flex:none}
  /* Review's buttons above the course dropdown: they share the full width, each as wide as its words allow */
  #view > .view-head.ph-fill{display:flex!important;flex-wrap:wrap;gap:8px;width:100%;justify-content:stretch}
  #view > .view-head.ph-fill > :not(h2){flex:1 1 auto;min-width:0;justify-content:center;white-space:nowrap;margin:0!important}
  #view > .view-head.ph-fill + .cf-chips + .cf-row,#view > .view-head.ph-fill + .cf-row{margin-top:12px}
  #view > .tl-controls + .cf-chips + .cf-row{margin-top:12px}
  .cf-acts .btn.small{min-height:40px;min-width:40px;border-radius:999px;padding:0 13px;gap:6px;justify-content:center;white-space:nowrap}
  .cf-acts-wide .btn.small{border-radius:999px;padding:0 14px;font-size:.9rem}
  #view > .view-head.ph-moved,#view > .tl-controls.ph-moved,#view .ftree.ph-moved{display:none}
  .f-row .segb{flex:none}
  .f-row .segb button{min-height:36px;padding:4px 12px;font-size:.86rem}
  #view > .nb-boards{display:none}
  .nb-row .nb-opts{min-height:40px;min-width:40px;border-radius:50%;padding:0;display:inline-flex;align-items:center;justify-content:center;flex:none;margin-right:auto}
  .nb-row .cf-pick{max-width:55%}
  .cf-row .board-ctl .mini{font-size:.72rem;white-space:nowrap}
  .cf-row .board-ctl .segb{padding:2px;gap:2px}
  .cf-row .board-ctl .segb button{min-height:36px;padding:4px 10px;font-size:.8rem}
  .bview-row .board-ctl{display:none}
}
@media (max-width:639px) and (prefers-reduced-motion:no-preference){nav.tabs .in button{transition:background .15s,color .15s}}
@media (max-width:639px){
  /* Calendar and Notes controls: one row that scrolls sideways instead of wrapping onto two or three */
  #view > .tl-controls{flex-wrap:nowrap;overflow-x:auto;scrollbar-width:none;margin-inline:-16px;padding:2px 16px;gap:8px}
  #view > .tl-controls::-webkit-scrollbar{display:none}
  #view > .tl-controls > *{flex:none}
  #view > .tl-controls .segb button,#view > .tl-controls > .btn.small{min-height:40px;padding-block:5px;font-size:.98rem}
  /* with only its switchers left (Today moved down beside the course list), they share the width */
  #view > .tl-controls:not(:has(> :not(h2,.segb))){overflow:visible;margin-inline:0;padding:0}
  #view > .tl-controls:not(:has(> :not(h2,.segb))) > .segb{flex:2 1 0;min-width:0}
  #view > .tl-controls:not(:has(> :not(h2,.segb))) > .segb + .segb{flex-grow:3}
  #view > .tl-controls:not(:has(> :not(h2,.segb))) > .segb button{flex:1 1 0;min-width:0;padding-inline:2px;font-size:.94rem}
  /* Today's Plan: the four numbers as one strip */
  .plan .pt-stats{display:flex;flex-wrap:wrap;gap:6px}   /* tiles share the row, whether 3 or 4 are shown; each is at least as wide as what it shows, and when they can't all fit they wrap to a second row instead of cutting anything off */
  .plan .pt-stat{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:3px;min-height:64px;padding:8px 6px;border-radius:12px;text-align:center;min-width:min-content;flex:1 1 0}
  .plan .pt-stats.pt-2x2 > .pt-stat{flex:1 1 calc(50% - 3px)}
  .plan .pt-stat b{display:block;font-size:.98rem;line-height:1.1;white-space:nowrap;letter-spacing:-.02em;font-variant-numeric:tabular-nums}
  .plan .pt-stat span{display:block;font-size:.64rem;line-height:1.15;white-space:normal;overflow-wrap:normal;word-break:normal;overflow:visible;margin:0}   /* a long label goes onto two lines, never "..." */
  .plan .fh-ctl .hours-ctl{min-height:0;padding:4px 10px}
  /* A page's own buttons whose heading was hidden (Review's Archive and Recently Deleted) sit beside its switcher */
  /* a header left with only its buttons (its heading repeats the page): the buttons on their own line under the switcher, at the right */
  #view > .view-head.ph-btns,#view > section > .view-head.ph-btns{display:flex;justify-content:flex-end;align-items:center;gap:6px;margin:4px 0 14px!important;padding:0!important;min-height:0;height:auto;position:static!important;transform:none!important}
  #view > .view-head.ph-btns + *,#view > section > .view-head.ph-btns + *{margin-top:0!important}
  /* breathing room between the header and the page's first row (the switcher or title pill) */
  /* frosted header: the theme shows through it, blurred (it was nearly solid) */
  /* its top edge is solid --paper, the same colour iOS paints behind the clock and battery (theme-color, set in 101-phone-v2.js),
     so the two read as one bar; it turns to frosted glass further down. Sits a little higher too. */
  header.top,body.sb-scrolled header.top{padding-top:4px!important;padding-bottom:6px!important;background:linear-gradient(to bottom,var(--paper) 0,color-mix(in srgb,var(--paper) 50%,transparent) 70%)!important;-webkit-backdrop-filter:blur(16px) saturate(1.5)!important;backdrop-filter:blur(16px) saturate(1.5)!important}
  #view{padding-top:6px!important}   /* 10px below the header in all */
  #view > .pview-tabs:first-child{margin-top:0!important}
  #view > .grp-grid{margin-top:16px}   /* same gap under the Groups pill as other pages */
  /* Companion chat: the page is fixed and only the conversation scrolls (#view's height is set by fitChat in 101-phone-v2.js) */
  html.ph-lock,html.ph-lock body{overflow:hidden!important;overscroll-behavior:none}
  html.ph-lock .wrap{padding-bottom:0!important;min-height:0!important}
  html.ph-lock #view{display:flex;flex-direction:column;overflow:hidden;padding-bottom:0!important;margin-bottom:0!important;min-height:0!important}
  html.ph-lock #view > .cpt{flex:1 1 auto;min-height:0;display:flex;flex-direction:column;margin:0!important}
  html.ph-lock #view > .cpt > .cpt-head{flex:none}
  html.ph-lock #view .cpt-pane{flex:1 1 auto;min-height:0;display:flex;flex-direction:column}
  html.ph-lock #view .cpt-pane > *{flex:none}
  html.ph-lock #view .cpt-pane > .cpt-log{flex:1 1 auto;min-height:0!important;max-height:none!important;overflow-y:auto;overscroll-behavior:contain;-webkit-overflow-scrolling:touch}
  html.ph-lock #view .cpt-form{position:static!important}
  @media (max-height:700px){html.ph-lock #view .cpt-priv{display:none}}   /* short phones: room for the conversation instead */
  /* Notes / Groups: the page name in a switcher-style pill (101-phone-v2.js) */
  #view > .pview-tabs.ph-solo .ph-solo-t{flex:1;display:flex;align-items:center;justify-content:center;min-height:42px;color:var(--ink);font:800 1.3rem var(--display);letter-spacing:-.01em}
  #view > .pview-tabs.ph-solo{justify-content:center}
  #view > .pview-tabs.ph-solo .ph-solo-t{flex:1 1 auto;min-width:0;padding:0 26px;border-radius:999px;background:var(--surface);box-shadow:var(--shadow)}   /* a selected-style pill sized to the name, like the chosen tab in a switcher */
  :is(#view > .view-head,#view > section > .view-head).ph-btns .btn.small{min-height:40px;margin:0!important}   /* (an older rule pulls header buttons up with a negative margin) */
  /* Task Board: Group By as a small control */
  .bview-row .board-ctl .segb button{min-height:34px;padding-block:4px;font-size:.84rem}
  .bview-row .board-ctl .mini{font-size:.78rem}
  /* Sheets with a colour band: a smaller ring and no empty strip under the band when there is no name to show */
  .g2-sheet-head:not(.sh-big):not(:has(.sh-t .mini)){min-height:84px!important}
  .g2-sheet-head .sh-ring{width:56px!important;height:56px!important;left:16px!important;top:16px!important}
  .g2-sheet-head:not(.sh-big) .sh-t h2,.sh-big .sh-kick{left:86px!important}
  .g2-sheet-head{padding-left:86px!important}
  /* A course's page: its tabs on one line each */
  .c2-head .cd-tabs button{font-size:.84rem;padding-inline:4px;white-space:nowrap}
}
/* the narrowest phones: icons only (each tab keeps its name for screen readers) */
@media (max-width:379px){.plan .pt-stat b{font-size:.8rem}.plan .pt-stat span{font-size:.6rem;white-space:normal;overflow:visible}}
@media (max-width:359px){header.top .today{font-size:.68rem!important}}
@media (max-width:359px){nav.tabs .in button,html[data-ts] nav.tabs .in button{font-size:0!important;line-height:0!important;gap:0;min-height:48px;justify-content:center}}
